window.ATLAS_ITEMS=window.ATLAS_ITEMS||{};window.ATLAS_ITEMS[334]={"id":"334","numero":334,"titre":"Polytraumatisé · brûlé","objectifs":[{"id":"334-1","rang":"A","rubrique":"Définition","titre":"Savoir définir un traumatisé sévère","contenu":"<p>Le <strong><span class=\"kw-def\">traumatisé sévère</span></strong> est défini <strong>a priori</strong> : c'est un blessé dont la <strong>violence</strong> ou le <strong>mécanisme</strong> du traumatisme <em>peuvent</em> entraîner des lésions menaçant le <span class=\"kw-alerte\">pronostic vital</span> — ou dont le mécanisme laisse penser que de telles lésions pourraient exister.</p>\n      <h4 style=\"margin:14px 0 6px;font-size:14px;\">Traumatisé sévère <span class=\"kw-bio\">vs</span> polytraumatisé</h4>\n      <table >\n        <thead><tr><th>Terme</th><th>Définition</th></tr></thead>\n        <tbody>\n          <tr><td><strong><span class=\"kw-def\">Traumatisé sévère</span></strong></td><td>Définition <strong>a priori</strong> (« blessé grave ») : violence/mécanisme pouvant entraîner des lésions vitales. Permet l'<strong>orientation précoce</strong> vers un trauma center.</td></tr>\n          <tr><td><span class=\"kw-def\">Polytraumatisé</span></td><td>Traumatisé avec <span class=\"kw-chiffre\">≥ 2 lésions</span> dont <span class=\"kw-chiffre\">≥ 1</span> <span class=\"kw-alerte\">menace</span> le <span class=\"kw-alerte\">pronostic vital</span>. <span class=\"kw-alerte\">Définition rétrospective</span> (établie après bilan lésionnel exhaustif / body-<span class=\"kw-imagerie\">TDM</span>) — <strong>inadaptée à l'<span class=\"kw-alerte\">urgence</span></strong>.</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\">\n        <strong>Piège.</strong> La gravité ne dépend <strong>pas</strong> du nombre de lésions mais de leur retentissement vital/fonctionnel. L'enjeu en <span class=\"kw-alerte\">urgence</span> est d'identifier au plus tôt le patient sévère pour l'orienter directement vers un <span class=\"kw-def\">trauma center</span>, sans attendre le body-<span class=\"kw-imagerie\">TDM</span>.</div>\n      <p>Concept transversal : le <strong><span class=\"kw-def\">damage control</span></strong> — privilégier la <strong>restauration physiologique</strong> à la réparation anatomique chez le traumatisé en <span class=\"kw-alerte\">choc</span> <span class=\"kw-etio\">hémorragique</span>.</p>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 333 — Situations sanitaires exceptionnelles · 332 — Etat de <span class=\"kw-alerte\">choc</span></em></p>","frequence":0},{"id":"334-2","rang":"B","rubrique":"Epidémiologie","titre":"Connaître les causes de mortalité après un traumatisme","contenu":"<p><span class=\"kw-clinique\">Les</span> traumatismes sont la <strong><span class=\"kw-chiffre\">1ʳᵉ cause de mortalité</span></strong> chez le sujet jeune (<span class=\"kw-chiffre\">&lt; 40 ans</span>) et la <span class=\"kw-chiffre\">3ᵉ cause</span> tous âges confondus. Ils sont aussi source de <strong>handicaps lourds</strong> et d'un coût financier important.</p>\n      <h4 style=\"margin:14px 0 6px;font-size:14px;\"><span class=\"kw-def\">Mortalité</span> selon le délai</h4>\n      <table >\n        <thead><tr><th>Délai</th><th>Causes de décès</th></tr></thead>\n        <tbody>\n          <tr><td><strong><span class=\"kw-def\">Mortalité</span> précoce</strong></td><td><span class=\"kw-alerte\">Hémorragie</span> ; <span class=\"kw-alerte\">traumatisme crânien grave</span>. Décès sur <span class=\"kw-clinique\">les</span> lieux ou dans les premières heures.</td></tr>\n          <tr><td><strong><span class=\"kw-def\">Mortalité</span> tardive</strong></td><td>Conséquences du <span class=\"kw-alerte\">traumatisme crânien</span> ; <span class=\"kw-alerte\">syndrome de défaillance multiviscérale</span> (SDMV). Décès dans <span class=\"kw-clinique\">les</span> jours-semaines suivants.</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\">\n        <strong>À retenir.</strong> La prise en charge dans un centre spécialisé (<span class=\"kw-def\">trauma center</span>) diminue la <span class=\"kw-def\">mortalité</span> de <span class=\"kw-chiffre\">25 %</span>. Tout défaut d'orientation imposant un transfert secondaire est associé à une <span class=\"kw-alerte\">surmortalité</span>.</div>","frequence":0},{"id":"334-3","rang":"A","rubrique":"Diagnostic positif","titre":"Savoir identifier et caractériser les lésions cliniquement","contenu":"<p>À l'arrivée sur <span class=\"kw-clinique\">les</span> lieux, le médecin du <span class=\"kw-alerte\">SMUR</span> recherche les détresses vitales selon la grille universelle <strong><span class=\"kw-def\">ABCDE</span></strong>, dans cet ordre strict :</p>\n      <table >\n        <thead><tr><th>Étape</th><th>Évaluation</th></tr></thead>\n        <tbody>\n          <tr><td><strong>A</strong> — Airway</td><td>Liberté des <span class=\"kw-clinique\">voies aériennes</span> ; recherche d'une obstruction. Rachis cervical immobilisé.</td></tr>\n          <tr><td><strong>B</strong> — Breathing</td><td><span class=\"kw-clinique\">SpO₂</span>, <span class=\"kw-clinique\">FR</span>, <span class=\"kw-clinique\">cyanose</span>, signes de <span class=\"kw-alerte\">détresse</span> respiratoire.</td></tr>\n          <tr><td><strong>C</strong> — Circulation</td><td>État de <span class=\"kw-alerte\">choc</span>, PA (<span class=\"kw-clinique\">pouls radial</span> = PAS &gt;<span class=\"kw-chiffre\"> 70 mmHg</span>), FC, <span class=\"kw-clinique\">hémorragie active</span>.</td></tr>\n          <tr><td><strong>D</strong> — Disability</td><td><span class=\"kw-clinique\">Glasgow</span>, pupilles, tonicité des membres, tonus du sphincter anal (TR).</td></tr>\n          <tr><td><strong>E</strong> — Exposure</td><td>Déshabillage complet : <span class=\"kw-clinique\">plaies</span>, foyers de fracture. Prévention de l'<span class=\"kw-alerte\">hypothermie</span>.</td></tr>\n        </tbody>\n      </table>\n      <p>L'examen clinique recherche <span class=\"kw-clinique\">les</span> lésions sur les <strong>5 régions du corps</strong> : <strong>tête-cou-rachis</strong> ; <strong>thorax</strong> ; <strong>abdomen</strong> ; <strong>bassin</strong> ; <strong>membres</strong>.</p>\n      <div class=\"callout callout-warn\">\n        <strong>Piège.</strong> Le <span class=\"kw-clinique\">toucher rectal</span> est systématique si le patient est inconscient ou en cas de suspicion de <span class=\"kw-clinique\">lésion</span> du rachis : une <span class=\"kw-alerte\">béance anale</span> fait suspecter une lésion médullaire.</div>\n      <h4 style=\"margin:14px 0 6px;font-size:14px;\">Syndromes médullaires incomplets</h4>\n      <table >\n        <thead><tr><th>Syndrome</th><th>Présentation clinique</th></tr></thead>\n        <tbody>\n          <tr><td><strong><span class=\"kw-def\">Brown-Séquard</span></strong> (hémisection médullaire)</td><td><span class=\"kw-clinique\">Paralysie</span> et perte de la <span class=\"kw-clinique\">proprioception</span> <strong>homolatérales</strong> à la lésion ; perte de la sensibilité <span class=\"kw-clinique\">thermo-algique</span> <strong>controlatérale</strong> (décussation du faisceau spino-thalamique).</td></tr>\n          <tr><td>Syndrome <strong>centromédullaire</strong></td><td>Déficit moteur prédominant aux <span class=\"kw-clinique\">membres supérieurs</span> par rapport aux membres inférieurs ; typique du sujet âgé après hyperextension cervicale.</td></tr>\n          <tr><td>Syndrome <strong>cordonal postérieur</strong></td><td>Perte de la <span class=\"kw-clinique\">proprioception</span> et du sens vibratoire (ataxie proprioceptive), motricité et sensibilité thermo-algique conservées.</td></tr>\n          <tr><td>Syndrome <strong>cordonal antérieur</strong></td><td><span class=\"kw-clinique\">Paralysie</span> et perte thermo-algique <span class=\"kw-alerte\">sous-lésionnelles</span> bilatérales, avec conservation relative de la proprioception et du sens vibratoire (atteinte de l'artère spinale antérieure).</td></tr>\n        </tbody>\n      </table>","frequence":0},{"id":"334-4","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les critères de gravité d’un traumatisé","contenu":"<p>L'<strong><span class=\"kw-def\">algorithme de Vittel</span></strong> (adulte) définit le traumatisé sévère et l'oriente vers un centre spécialisé. Il comporte <strong>5 étapes</strong> : la présence d'<strong><span class=\"kw-alerte\">un seul critère</span></strong> suffit à classer en traumatisé sévère.</p>\n      <table >\n        <thead><tr><th>Étape</th><th>Critères</th></tr></thead>\n        <tbody>\n          <tr><td><strong>1 — Variables physiologiques</strong></td><td><span class=\"kw-def\">Glasgow</span> <span class=\"kw-chiffre\">&lt; 13</span> ; PAS <span class=\"kw-chiffre\">&lt; 90 mmHg</span> ; SpO₂ <span class=\"kw-chiffre\">&lt; 90 %</span>.<br><span class=\"kw-alerte\">Gravité extrême</span> : <span class=\"kw-def\">Glasgow</span> = 3 ; PAS <span class=\"kw-chiffre\">&lt; 65 mmHg</span> ; SpO₂ <span class=\"kw-chiffre\">&lt; 80 %</span> ou imprenable.</td></tr>\n          <tr><td><strong>2 — Cinétique</strong></td><td>Éjection du véhicule ; victime projetée/écrasée ; chute <span class=\"kw-chiffre\">&gt; 6 m</span> ; autre passager décédé ; déformation du véhicule ; <span class=\"kw-etio\">blast</span>.</td></tr>\n          <tr><td><strong>3 — Lésions anatomiques</strong></td><td>Trauma <span class=\"kw-alerte\">pénétrant</span> tête/cou/thorax/abdomen/bassin/bras/cuisse ; <span class=\"kw-alerte\">volet thoracique</span> ; fracas/instabilité du bassin ; suspicion d'atteinte médullaire ; brûlure sévère ; amputation ; <span class=\"kw-alerte\">ischémie aiguë</span> de membre.</td></tr>\n          <tr><td><strong>4 — <span class=\"kw-alerte\">Réanimation</span> préhospitalière</strong></td><td>Ventilation assistée ; remplissage <span class=\"kw-chiffre\">&gt; 1 L</span> ; catécholamines ; pantalon antichoc gonflé.</td></tr>\n          <tr><td><strong>5 — <span class=\"kw-def\">Terrain</span></strong></td><td>Âge <span class=\"kw-chiffre\">&gt; 75 ans</span> ; <span class=\"kw-def\">insuffisance cardiaque</span>/coronarienne/respiratoire ; <span class=\"kw-ci\">grossesse</span> (2ᵉ-3ᵉ trimestre) ; trouble de la crase / traitement antithrombotique.</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\">\n        <strong>À retenir.</strong> Un critère positif sur <span class=\"kw-clinique\">les</span> étapes 1 à 4 = orientation en centre spécialisé. L'étape 5 (<span class=\"kw-def\">terrain</span>) impose une admission (en MIR) ou la discute (en Réa).</div>","frequence":1},{"id":"334-5","rang":"A","rubrique":"Prise en charge","titre":"Connaître les principes de prise en charge préhospitalère des lésions","contenu":"<p>Avant <span class=\"kw-clinique\">les</span> secours médicalisés, le <strong>témoin</strong> est le 1ᵉʳ maillon de la chaîne de survie : <strong>Protéger</strong> (sur-accident) — <strong>Alerter</strong> (15 <span class=\"kw-alerte\">SAMU</span>, 18 pompiers, 112) — <strong>Secourir</strong> (compression d'hémorragie, position d'attente sur ordre du régulateur).</p>\n      <h4 style=\"margin:14px 0 6px;font-size:14px;\">Gestes d'hémostase médicaux préhospitaliers (priorité n°1)</h4>\n      <ul>\n        <li><strong>Compression</strong> de toute hémorragie extériorisée ; <strong>suture</strong> d'une plaie <span class=\"kw-etio\">hémorragique</span> du scalp.</li>\n        <li><span class=\"kw-clinique\">Épistaxis</span> : tamponnement.</li>\n        <li>Hémorragie artérielle de membre / amputation : <strong><span class=\"kw-alerte\">garrot</span></strong> à la racine (noter l'heure de pose).</li>\n        <li><span class=\"kw-alerte\">Pneumothorax sous tension</span> : <strong>exsufflation</strong> à l'aiguille (pas de <span class=\"kw-ttt\">drainage</span> en préhospitalier).</li>\n        <li>Suspicion de traumatisme pelvien : <strong>ceinture de contention pelvienne</strong> au niveau des trochanters.</li>\n      </ul>\n      <h4 style=\"margin:14px 0 6px;font-size:14px;\">Autres mesures thérapeutiques</h4>\n      <ul>\n        <li>Antalgie : <span class=\"kw-ttt\">morphine</span> IVD ; immobilisation des fractures déplacées dans des attelles à <span class=\"kw-def\">dépression</span> après <span class=\"kw-ttt\">réduction</span>.</li>\n        <li>Lutte contre l'<span class=\"kw-alerte\">hypothermie</span> : couverture de survie.</li>\n        <li><span class=\"kw-ttt\">Acide tranexamique</span> : <span class=\"kw-chiffre\">1 g sur 10 min</span> chez tout traumatisé sévère.</li>\n        <li><span class=\"kw-ttt\">Antibioprophylaxie</span> par <span class=\"kw-ttt\">amoxicilline-acide clavulanique</span> si <strong>fracture ouverte</strong>.</li>\n      </ul>\n      <div class=\"callout callout-danger\">\n        <strong><span class=\"kw-alerte\">Urgence</span>.</strong> Le délai de transport vers l'hôpital ne doit <strong>jamais excéder <span class=\"kw-chiffre\">90 minutes</span></strong>. Toute hémorragie non contrôlée impose un transfert sans délai vers un centre apte à l'hémostase — aucun examen ne doit retarder ce transfert.</div>","frequence":0},{"id":"334-6","rang":"B","rubrique":"Prise en charge","titre":"Connaître les principes de réanimation préhospitalère","contenu":"<p><strong>Conditionnement</strong> : monitorage continu (PA, FC, SpO₂, FR) ; pose de <span class=\"kw-chiffre\">2 VVP</span> de bon calibre (<span class=\"kw-chiffre\">16 G</span>) ; mesure de la <span class=\"kw-bio\">glycémie capillaire</span>, de l'<span class=\"kw-bio\">hémoglobine</span> (Hémocue) et de la <span class=\"kw-bio\">lactatémie</span>.</p>\n      <h4 style=\"margin:14px 0 6px;font-size:14px;\">Volet respiratoire</h4>\n      <ul>\n        <li><span class=\"kw-ttt\">Oxygénothérapie</span> titrée pour <span class=\"kw-bio\">SpO₂ &gt; 95 %</span> : masque à haute concentration <span class=\"kw-chiffre\">15 L/min</span>.</li>\n        <li><strong><span class=\"kw-ttt\">Intubation</span> orotrachéale en séquence rapide</strong> (hypnotique + curare, <strong>sans morphinique</strong>) si <span class=\"kw-alerte\">Glasgow ≤ 8</span>, <span class=\"kw-alerte\">détresse</span> respiratoire ou détresse hémodynamique. Intubation à risque (rachis cervical, trauma facial).</li>\n      </ul>\n      <h4 style=\"margin:14px 0 6px;font-size:14px;\">Volet hémodynamique</h4>\n      <ul>\n        <li><strong>Remplissage</strong> par <span class=\"kw-ttt\">cristalloïdes</span> sur VVP, <strong>± <span class=\"kw-ttt\">noradrénaline</span></strong> si <span class=\"kw-clinique\">hypotension</span> persistante après <span class=\"kw-chiffre\">1 L</span>.</li>\n      </ul>\n      <table >\n        <thead><tr><th>Profil</th><th>Définition</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-alerte\">Patient instable</span></td><td>PAS <span class=\"kw-chiffre\">&lt; 90 mmHg</span> malgré la <span class=\"kw-alerte\">réanimation</span> — risque de décès très élevé.</td></tr>\n          <tr><td>Patient critique</td><td>PAS <span class=\"kw-chiffre\">&gt; 90 mmHg</span> grâce à la <span class=\"kw-alerte\">réanimation</span> (remplissage et/ou <span class=\"kw-ttt\">noradrénaline</span>).</td></tr>\n          <tr><td>Patient potentiellement grave</td><td>PAS <span class=\"kw-chiffre\">&gt; 90 mmHg</span> sans manœuvre de <span class=\"kw-alerte\">réanimation</span>.</td></tr>\n        </tbody>\n      </table>\n      <p>Immobilisation systématique : <strong>collier cervical rigide</strong> (tout traumatisé sévère est un traumatisé du rachis jusqu'à preuve du contraire), mobilisation en bloc, matelas à <span class=\"kw-def\">dépression</span>.</p>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 332 — Etat de <span class=\"kw-alerte\">choc</span> · 329 — Transfusion sanguine</em></p>","frequence":2},{"id":"334-7","rang":"B","rubrique":"Prise en charge","titre":"Connaître les principes de la prise en charge diagnostique à l’arrivée à l’hôpital","contenu":"<h4 style=\"margin:14px 0 6px;font-size:14px;\">15 premières minutes — bilan clinique</h4>\n      <p>Transfert sur brancard chauffant avec respect de la rectitude crânio-rachidienne ; vérification des VVP ; poursuite O₂/remplissage. Examen des 5 régions du corps, statut vaccinal tétanos, sonde thermique.</p>\n      <h4 style=\"margin:14px 0 6px;font-size:14px;\">30 premières minutes — bilan paraclinique initial</h4>\n      <ul>\n        <li><strong>Biologie</strong> : <span class=\"kw-bio\">NFS</span>, <span class=\"kw-bio\">hémostase</span> (<span class=\"kw-bio\">TP</span>, <span class=\"kw-bio\">TCA</span>, <span class=\"kw-bio\">fibrinogène</span>), <strong>bilan prétransfusionnel</strong> (groupe ABO-RH1 + RH-KEL1, RAI — 2 déterminations), <span class=\"kw-bio\">GDS</span>/<span class=\"kw-bio\">lactates</span>, <span class=\"kw-bio\">ionogramme</span>/<span class=\"kw-bio\">créatinine</span>/<span class=\"kw-bio\">CPK</span>, <span class=\"kw-bio\">ECG</span>/<span class=\"kw-bio\">troponine</span>, <span class=\"kw-bio\">bilan hépatique</span>/<span class=\"kw-bio\">lipase</span> ; <span class=\"kw-bio\">β-hCG</span> chez la femme.</li>\n        <li><strong>Imagerie systématique sur le brancard</strong> : <span class=\"kw-imagerie\">RXT</span> (face) ; <span class=\"kw-imagerie\">RX du bassin</span> (face) ; <strong><span class=\"kw-imagerie\">échographie</span> <span class=\"kw-imagerie\">FAST</span></strong> (hémopéritoine, <span class=\"kw-imagerie\">épanchement pleural</span>, hémopéricarde).</li>\n      </ul>\n      <h4 style=\"margin:14px 0 6px;font-size:14px;\">Au-delà de <span class=\"kw-chiffre\">60 min</span> — bilan lésionnel</h4>\n      <p>Le <strong><span class=\"kw-imagerie\">body-TDM</span></strong> (<span class=\"kw-imagerie\">TDM</span> corps entier injecté, crâne → pelvis) est l'examen de référence : délai <span class=\"kw-chiffre\">&lt; 45 min</span> si patient critique, jusqu'à <span class=\"kw-chiffre\">90 min</span> si stable.</p>\n      <div class=\"callout callout-warn\">\n        <strong>Piège.</strong> Seule exception au body-<span class=\"kw-imagerie\">TDM</span> : le <span class=\"kw-alerte\">patient moribond</span> (instabilité hémodynamique extrême), <em>a fortiori</em> sur traumatisme pénétrant → transfert direct au bloc opératoire, <span class=\"kw-imagerie\">TDM</span> dans un 2ᵉ temps.</div>","frequence":1},{"id":"334-8","rang":"B","rubrique":"Prise en charge","titre":"Connaître les principes de la prise en charge thérapeutique à l’arrivée à l’hôpital","contenu":"<p>L'<span class=\"kw-alerte\">état de choc</span> à la phase initiale d'un traumatisme sévère est le plus souvent un <strong><span class=\"kw-alerte\">choc hémorragique</span></strong>. La prise en charge combine traitement <strong>symptomatique</strong> et <strong>étiologique</strong> (<span class=\"kw-alerte\">urgence</span> absolue).</p>\n      <h4 style=\"margin:14px 0 6px;font-size:14px;\">Traitement symptomatique</h4>\n      <ul>\n        <li><strong>Hypovolémie</strong> : <span class=\"kw-ttt\">cristalloïdes</span> → <span class=\"kw-ttt\">noradrénaline</span> → produits sanguins labiles (<span class=\"kw-ttt\">CGR O+</span> homme, <span class=\"kw-ttt\">O−</span> femme en âge de procréer).</li>\n        <li><strong>Coagulopathie</strong> : <span class=\"kw-ttt\">PFC</span>/<span class=\"kw-ttt\">CGR</span> ratio <span class=\"kw-chiffre\">1/1</span> à <span class=\"kw-chiffre\">1/2</span> ; <span class=\"kw-ttt\">concentrés plaquettaires</span> ratio <span class=\"kw-chiffre\">1/4</span> ; <span class=\"kw-ttt\">fibrinogène</span> (objectif <span class=\"kw-chiffre\">&gt; 1,5-2 g/L</span>) ; <span class=\"kw-ttt\">acide tranexamique</span> ; <span class=\"kw-ttt\">calcium</span> ; lutte contre l'<span class=\"kw-clinique\">hypothermie</span>.</li>\n      </ul>\n      <h4 style=\"margin:14px 0 6px;font-size:14px;\">Objectifs tensionnels et transfusionnels</h4>\n      <table >\n        <thead><tr><th>Cible</th><th>Sans neurotraumatisme</th><th>Avec neurotraumatisme</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-clinique\">PAM</span></td><td><span class=\"kw-chiffre\">60-65 mmHg</span> (pas au-delà)</td><td><span class=\"kw-chiffre\">75-85 mmHg</span> (si TC grave)</td></tr>\n          <tr><td><span class=\"kw-bio\">Hémoglobine</span></td><td><span class=\"kw-chiffre\">&gt; 7 g/dL</span></td><td><span class=\"kw-chiffre\">&gt; 10 g/dL</span></td></tr>\n          <tr><td><span class=\"kw-bio\">Plaquettes</span></td><td><span class=\"kw-chiffre\">&gt; 50 G/L</span></td><td><span class=\"kw-chiffre\">&gt; 100 G/L</span></td></tr>\n          <tr><td><span class=\"kw-bio\">TP</span></td><td><span class=\"kw-chiffre\">&gt; 40 %</span></td><td><span class=\"kw-chiffre\">&gt; 60 %</span></td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\">\n        <strong>Piège majeur QCM.</strong> En <span class=\"kw-alerte\">choc</span> <span class=\"kw-etio\">hémorragique</span> pur, on vise une <strong><span class=\"kw-clinique\">hypotension</span> permissive</strong> (PAM 60-65). En cas de <span class=\"kw-alerte\">TC grave associé</span>, la cible monte à <span class=\"kw-chiffre\">75-85 mmHg</span> pour préserver la pression de perfusion cérébrale (PPC = PAM − PIC).</div>\n      <h4 style=\"margin:14px 0 6px;font-size:14px;\">Traitement étiologique — damage control</h4>\n      <p>Gestes d'hémostase simples (garrot, ceinture pelvienne, pansement compressif) puis hémostase au <strong>bloc opératoire</strong> ou par <strong><span class=\"kw-imagerie\">artério-embolisation</span></strong>. La <span class=\"kw-ttt\">chirurgie</span> réparatrice est <strong>différée</strong> (« second look »).</p>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 329 — Transfusion sanguine · 332 — Etat de <span class=\"kw-alerte\">choc</span></em></p>","frequence":1},{"id":"334-9","rang":"B","rubrique":"Prise en charge","titre":"Connaître les principales complications du traumatisé sévère à court, moyen et long termes","contenu":"<table >\n        <thead><tr><th>Complication</th><th>Prévention / prise en charge</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-alerte\">Maladie thromboembolique</span></td><td>Matelas anti-escarres ; compression pneumatique intermittente ; <span class=\"kw-ttt\">héparinothérapie préventive</span> à distance de l'hémorragie aiguë.</td></tr>\n          <tr><td><span class=\"kw-alerte\">Infection</span></td><td><span class=\"kw-ttt\">Antibiothérapie</span> ciblée pour certaines lésions (fracture ouverte, <span class=\"kw-alerte\">perforation digestive</span>, trauma thoracique grave).</td></tr>\n          <tr><td><span class=\"kw-alerte\">Dénutrition</span></td><td><strong>Nutrition entérale précoce</strong> dès que possible — favorise la cicatrisation.</td></tr>\n          <tr><td><span class=\"kw-clinique\">Douleur</span></td><td>Antalgie adaptée.</td></tr>\n          <tr><td>Séquelles</td><td>Rééducation après la <span class=\"kw-alerte\">réanimation</span> ; <span class=\"kw-def\">suivi</span> des séquelles <strong>somatiques</strong> (incapacité fonctionnelle) et <strong>psychologiques</strong> (<span class=\"kw-def\">syndrome anxio-dépressif</span>, <span class=\"kw-alerte\">syndrome de stress post-traumatique</span>).</td></tr>\n        </tbody>\n      </table>","frequence":0},{"id":"334-10","rang":"A","rubrique":"Définition","titre":"Connaître la définition d’une brûlure et de sa profondeur","contenu":"<p>Une <strong><span class=\"kw-def\">brûlure</span></strong> est une destruction traumatique de la peau et des tissus sous-jacents par un processus <span class=\"kw-etio\">thermique</span> (<span class=\"kw-chiffre\">90 %</span> — liquides &gt; flammes &gt; solides chauds), <span class=\"kw-etio\">électrique</span>, <span class=\"kw-etio\">chimique</span>, mécanique ou radique. La profondeur dépend de la <strong>température</strong> et de la <strong>durée d'exposition</strong>.</p>\n      <table >\n        <thead><tr><th>Profondeur</th><th>Atteinte</th><th><span class=\"kw-clinique\">Évolution</span></th></tr></thead>\n        <tbody>\n          <tr><td><strong>1ᵉʳ degré</strong></td><td>Purement intra-épidermique. <span class=\"kw-clinique\">Érythème</span> douloureux (coup de soleil), pas de décollement.</td><td>Cicatrisation sans séquelle (<span class=\"kw-chiffre\">3-7 j</span>).</td></tr>\n          <tr><td><strong>2ᵉ degré superficiel</strong></td><td>Derme papillaire, <strong>respect de la membrane basale</strong>. <span class=\"kw-clinique\">Phlyctène</span>, fond rouge, très douloureux, <span class=\"kw-clinique\">vitropression positive</span>.</td><td>Guérison sans cicatrice (<span class=\"kw-chiffre\">10-14 j</span>).</td></tr>\n          <tr><td><strong>2ᵉ degré profond</strong></td><td>Derme profond, destruction de la membrane basale. Phlyctène, fond pâle, peu douloureux, <span class=\"kw-clinique\">vitropression négative</span>.</td><td>Guérison cicatricielle (<span class=\"kw-chiffre\">21-35 j</span>), <span class=\"kw-alerte\">séquelles</span>.</td></tr>\n          <tr><td><strong>3ᵉ degré</strong></td><td>Destruction totale de la peau. <span class=\"kw-alerte\">Nécrose</span> blanche/brune/noire, peau cartonnée, <strong>insensible</strong>, pas de phlyctène.</td><td>Pas de guérison spontanée → <span class=\"kw-ttt\">greffe de peau</span>.</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\">\n        <strong>Piège.</strong> Avant le <span class=\"kw-chiffre\">15ᵉ jour</span>, il est difficile de distinguer le 2ᵉ degré profond du 3ᵉ degré. L'atteinte des plans sous-jacents (muscle, tendon, os) définit la <span class=\"kw-alerte\">carbonisation</span>.</div>","frequence":0},{"id":"334-11","rang":"B","rubrique":"Définition","titre":"Connaître la définition d’un syndrome d’inhalation de fumées d’incendie","contenu":"<p>Le <strong><span class=\"kw-def\">syndrome d'inhalation de fumées d'incendie</span></strong> résulte de l'inhalation des produits de <strong>combustion</strong> de matériaux synthétiques et naturels, au cours d'un <strong>incendie en milieu clos</strong>.</p>\n      <p>Il associe deux mécanismes lésionnels :</p>\n      <ul>\n        <li>Une <strong>agression thermique et chimique directe</strong> des voies aériennes → <span class=\"kw-clinique\">œdème laryngé</span>, <span class=\"kw-clinique\">bronchospasme</span>, risque d'<span class=\"kw-alerte\">OAP lésionnel</span>/<span class=\"kw-alerte\">SDRA</span>.</li>\n        <li>Une <strong>intoxication systémique</strong> aux gaz asphyxiants : <span class=\"kw-etio\">monoxyde de carbone</span> (CO) et <span class=\"kw-etio\">cyanure</span> (HCN).</li>\n      </ul>\n      <div class=\"callout callout-info\">\n        <strong>À retenir.</strong> Évoquer le diagnostic devant : suie dans l'oropharynx/<span class=\"kw-clinique\">les</span> <span class=\"kw-clinique\">expectorations</span>, brûlures faciales et cervicales, symptomatologie respiratoire (<span class=\"kw-clinique\">toux</span>, dysphonie, <span class=\"kw-clinique\">wheezing</span>).</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 337 — Intoxication aiguë</em></p>","frequence":0},{"id":"334-12","rang":"B","rubrique":"Physiopathologie","titre":"Comprendre le mécanisme des complications après une brûlure","contenu":"<p>L'agression thermique active la cascade <strong>pro-<span class=\"kw-etio\">inflammatoire</span></strong>, à l'origine de deux phases successives :</p>\n      <table >\n        <thead><tr><th>Phase</th><th>Mécanisme et conséquences</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Phase initiale</strong> (<span class=\"kw-chiffre\">0–48 h</span>)</td><td>Modification de l'équilibre de Starling → <span class=\"kw-alerte\">fuite capillaire</span> majeure ; pertes hydroélectrolytiques et protéiques. Entretenue par l'inflammation et la baisse de pression oncotique.<br><strong>Clinique :</strong> phlyctènes, <span class=\"kw-clinique\">œdèmes</span>, tendance au <span class=\"kw-alerte\">collapsus</span> et au <span class=\"kw-def\">choc hypovolémique</span>.</td></tr>\n          <tr><td><strong>Phase secondaire</strong> (<span class=\"kw-chiffre\">J3</span>–<span class=\"kw-chiffre\">J21</span>)</td><td><span class=\"kw-alerte\">SIRS</span> (syndrome de réponse inflammatoire systémique), <span class=\"kw-alerte\">dysfonction immunitaire</span> (susceptibilité aux infections) ; hyperactivité métabolique.<br><strong>Clinique :</strong> risque infectieux majeur, <span class=\"kw-alerte\">dénutrition</span> — source d'infections et de retard de cicatrisation.</td></tr>\n          <tr><td><strong>Phase de cicatrisation</strong> (au-delà de <span class=\"kw-chiffre\">J21</span>)</td><td>Réparation tissulaire ; risque de <span class=\"kw-alerte\">cicatrices hypertrophiques / rétractiles</span> et de séquelles fonctionnelles.<br><strong>Clinique :</strong> rééducation et prise en charge esthétique/fonctionnelle au long cours.</td></tr>\n        </tbody>\n      </table>","frequence":0},{"id":"334-13","rang":"B","rubrique":"Physiopathologie","titre":"Comprendre la physiopathologie du syndrome d’inhalation de fumée d’incendie","contenu":"<table >\n        <thead><tr><th>Gaz</th><th><span class=\"kw-def\">Physiopathologie</span></th></tr></thead>\n        <tbody>\n          <tr><td><strong><span class=\"kw-etio\">Monoxyde de carbone</span> (CO)</strong></td><td>Affinité du CO pour l'<span class=\"kw-bio\">hémoglobine</span> très supérieure à celle de l'O₂ → formation de <span class=\"kw-bio\">carboxyhémoglobine</span> → <span class=\"kw-alerte\">hypoxie tissulaire</span>. Organes cibles : cerveau, myocarde.</td></tr>\n          <tr><td><strong><span class=\"kw-etio\">Cyanure</span> (HCN)</strong></td><td>L'ion cyanure inhibe la <strong><span class=\"kw-def\">cytochrome oxydase</span></strong> mitochondriale → blocage de la respiration cellulaire, métabolisme <span class=\"kw-etio\">anaérobie</span>. <span class=\"kw-alerte\">Hypoxie cellulaire sans hypoxémie</span> ; production de <span class=\"kw-bio\">lactates</span>.</td></tr>\n        </tbody>\n      </table>\n      <p>Localement, la fumée provoque une <span class=\"kw-clinique\">muqueuse inflammatoire</span> et un dépôt de <span class=\"kw-clinique\">suies</span>, avec risque d'<span class=\"kw-clinique\">œdème laryngé</span> et de <span class=\"kw-alerte\">détresse respiratoire</span>.</p>\n      <div class=\"callout callout-warn\">\n        <strong>Discriminant.</strong> Dans l'intoxication au cyanure, il n'y a <strong>pas d'hypoxémie</strong> (la PaO₂ est normale) mais une <span class=\"kw-alerte\">hypoxie cellulaire</span> : la cellule ne peut pas utiliser l'oxygène → acidose métabolique avec <span class=\"kw-bio\">hyperlactatémie</span> et <span class=\"kw-bio\">trou anionique</span> augmenté.</div>","frequence":0},{"id":"334-14","rang":"A","rubrique":"Diagnostic positif","titre":"Savoir diagnostiquer une brûlure et la surface brûlée","contenu":"<p>Le diagnostic est <strong>clinique</strong> : déshabillage complet, schéma daté et signé, photographies. L'évaluation de la <strong><span class=\"kw-def\">surface cutanée brûlée</span> (SCB)</strong> conditionne le <span class=\"kw-def\">pronostic</span>.</p>\n      <div class=\"callout callout-warn\">\n        <strong>Piège.</strong> Seules <span class=\"kw-clinique\">les</span> brûlures du <strong>2ᵉ et 3ᵉ degré</strong> sont comptabilisées dans la SCB — jamais le 1ᵉʳ degré.</div>\n      <h4 style=\"margin:14px 0 6px;font-size:14px;\">Méthodes d'estimation</h4>\n      <table >\n        <thead><tr><th>Méthode</th><th>Principe</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Règle des 9 de Wallace</strong> (adulte)</td><td>Tête + cou = <span class=\"kw-chiffre\">9 %</span> ; chaque membre supérieur = <span class=\"kw-chiffre\">9 %</span> ; tronc antérieur = <span class=\"kw-chiffre\">18 %</span> ; tronc postérieur = <span class=\"kw-chiffre\">18 %</span> ; chaque membre inférieur = <span class=\"kw-chiffre\">18 %</span> ; périnée = <span class=\"kw-chiffre\">1 %</span>.</td></tr>\n          <tr><td>Paume de la main</td><td>Face palmaire de la main du patient (paume + doigts) ≈ <span class=\"kw-chiffre\">1 %</span> — utile pour <span class=\"kw-clinique\">les</span> lésions en mosaïque.</td></tr>\n          <tr><td>Wallace chez l'enfant</td><td>Tête plus volumineuse : <span class=\"kw-chiffre\">18 %</span> (au lieu de <span class=\"kw-chiffre\">9 %</span>) ; membre inférieur <span class=\"kw-chiffre\">14 %</span> (au lieu de <span class=\"kw-chiffre\">18 %</span>).</td></tr>\n          <tr><td>Lund &amp; Browder / Berkow</td><td>Tables standardisées tenant compte de l'âge, plus précises (utilisées à l'admission hospitalière).</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\">\n        <strong>À retenir.</strong> Toute brûlure atteignant <span class=\"kw-chiffre\">&gt; 10 %</span> de la surface cutanée totale est <strong>grave</strong>. Il existe une corrélation SCB ↔ besoins volémiques ↔ <span class=\"kw-def\">mortalité</span>.</div>","frequence":0},{"id":"334-15","rang":"A","rubrique":"Contenu multimédia","titre":"Identifier une brûlure superficielle et une brûlure profonde","contenu":"<p>La distinction <strong>superficielle / profonde</strong> conditionne le <span class=\"kw-def\">pronostic</span> et la stratégie thérapeutique : <span class=\"kw-clinique\">les</span> brûlures superficielles cicatrisent spontanément, les profondes nécessitent une <span class=\"kw-ttt\">greffe</span>.</p>\n      <figure class=\"obj-figure\">\n        <img src=\"../assets/images/334/brulure-profondeur-degres.png\" alt=\"Schéma en coupe de peau des quatre degrés de profondeur de brûlure : 1er degré intra-épidermique, 2e degré superficiel, 2e degré profond, 3e degré atteignant les tissus sous-cutanés\" loading=\"lazy\">\n        <figcaption>Profondeur des brûlures en coupe cutanée : 1ᵉʳ degré (épiderme), 2ᵉ degré superficiel et profond (derme), 3ᵉ degré (destruction épiderme + derme). Source : fiche source EDN item 334.</figcaption>\n      </figure>\n      <figure class=\"obj-figure\">\n        <img src=\"../assets/images/334/brulure-2e-degre-clinique.png\" alt=\"Photographies cliniques comparant une brûlure du 2e degré superficiel (phlyctènes à fond rouge) et du 2e degré profond (fond pâle, blanc rosé)\" loading=\"lazy\">\n        <figcaption>Aspect clinique : 2ᵉ degré superficiel (fond rouge, vitropression positive) <span class=\"kw-bio\">vs</span> 2ᵉ degré profond (fond pâle, vitropression négative). Source : fiche source EDN item 334.</figcaption>\n      </figure>\n      <table >\n        <thead><tr><th>Critère</th><th>Brûlure superficielle</th><th>Brûlure profonde</th></tr></thead>\n        <tbody>\n          <tr><td>Degrés</td><td>1ᵉʳ ; 2ᵉ degré <strong>superficiel</strong></td><td>2ᵉ degré <strong>profond</strong> ; 3ᵉ degré</td></tr>\n          <tr><td>Douleur</td><td><span class=\"kw-clinique\">Très douloureuse</span></td><td>Peu douloureuse à <span class=\"kw-alerte\">indolore</span> (3ᵉ degré)</td></tr>\n          <tr><td><span class=\"kw-clinique\">Vitropression</span></td><td><strong>Positive</strong> (fond rouge qui se recolore)</td><td><strong>Négative</strong> (fond pâle, cartonné)</td></tr>\n          <tr><td>Phanères</td><td>Adhérents</td><td>Non adhérents (3ᵉ degré)</td></tr>\n          <tr><td><span class=\"kw-clinique\">Évolution</span></td><td>Cicatrisation spontanée sans séquelle</td><td>Cicatrice / <span class=\"kw-ttt\">greffe</span> ; <span class=\"kw-alerte\">séquelles</span></td></tr>\n        </tbody>\n      </table>","frequence":0},{"id":"334-16","rang":"A","rubrique":"Identifier une urgence","titre":"Savoir reconnaître les signes de gravité d’une brûlure chez l’adulte et l’enfant","contenu":"<p>Toute brûlure grave requiert un <strong><span class=\"kw-def\">contact</span> systématique avec un centre de traitement des brûlés</strong>. <span class=\"kw-clinique\">Les</span> <span class=\"kw-alerte\"><span class=\"kw-def\">critères de</span> gravité</span> (SFAR 2019) :</p>\n      <table >\n        <thead><tr><th>Critère</th><th>Détail</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Surface</strong></td><td>SCB <span class=\"kw-chiffre\">&gt; 20 %</span> (2ᵉ degré) ou <span class=\"kw-chiffre\">&gt; 5 %</span> (3ᵉ degré) chez l'adulte ; <span class=\"kw-chiffre\">&gt; 10 %</span> (2ᵉ) ou <span class=\"kw-chiffre\">&gt; 5 %</span> (3ᵉ) chez l'<strong>enfant</strong>.<br><span class=\"kw-def\">Score de BAUX</span> (âge + SCB totale) : <span class=\"kw-chiffre\">&gt; 100</span> = <span class=\"kw-def\">mortalité</span> ≈<span class=\"kw-chiffre\"> 50 %</span>.</td></tr>\n          <tr><td><strong>Localisation</strong></td><td>Zones fonctionnelles : <span class=\"kw-alerte\">face</span>, <span class=\"kw-alerte\">voies aériennes</span>, mains, périnée, plis de flexion.</td></tr>\n          <tr><td><strong><span class=\"kw-def\">Terrain</span></strong></td><td>Âge <span class=\"kw-chiffre\">&lt; 3 ans</span> ou <span class=\"kw-chiffre\">&gt; 60 ans</span> ; <span class=\"kw-def\">comorbidités</span> (<span class=\"kw-ci\">insuffisance respiratoire</span>/cardiaque/rénale, <span class=\"kw-def\">diabète</span>, éthylisme).</td></tr>\n          <tr><td><strong>Contexte</strong></td><td>Traumatismes associés ; brûlure <span class=\"kw-etio\">électrique</span> (trouble du rythme, <span class=\"kw-alerte\">rhabdomyolyse</span>) ou <span class=\"kw-etio\">chimique</span> (effets systémiques) ; <span class=\"kw-alerte\">inhalation de fumées</span> ; troubles de conscience (suspecter une intoxication).</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\">\n        <strong>Piège pédiatrique.</strong> Chez l'enfant, <span class=\"kw-clinique\">les</span> seuils de gravité de surface sont <strong>plus bas</strong> que chez l'adulte (<span class=\"kw-chiffre\">60 %</span> des brûlures sont graves chez l'enfant de moins de <span class=\"kw-chiffre\">4 ans</span>).</div>","frequence":0},{"id":"334-17","rang":"A","rubrique":"Contenu multimédia","titre":"Identifier une brûlure des voies aériennes","contenu":"<p>La <strong><span class=\"kw-alerte\">brûlure des voies aériennes</span></strong> met en jeu le <span class=\"kw-alerte\">pronostic vital</span> par obstruction. Elle s'intègre souvent à une brûlure de la face (grave par définition).</p>\n      <h4 style=\"margin:14px 0 6px;font-size:14px;\">Signes à rechercher</h4>\n      <ul>\n        <li><span class=\"kw-clinique\">Suie</span> au niveau des orifices (nez, bouche) — confirmée par la suie en aval des cordes vocales en <span class=\"kw-imagerie\">fibroscopie</span>.</li>\n        <li><span class=\"kw-alerte\">Œdème laryngé</span> : rechercher de façon répétée toute <span class=\"kw-clinique\">dyspnée</span>, <span class=\"kw-clinique\">modification de la voix</span>, <span class=\"kw-clinique\">stridor</span> dans <span class=\"kw-clinique\">les</span> premières heures.</li>\n        <li>Brûlure des cils/sourcils ; <span class=\"kw-clinique\">brûlures faciales et cervicales</span> associées.</li>\n      </ul>\n      <div class=\"callout callout-danger\">\n        <strong><span class=\"kw-alerte\">Urgence</span>.</strong> Devant un <span class=\"kw-clinique\">œdème</span> des voies aériennes supérieures avec <span class=\"kw-alerte\">détresse</span> respiratoire → <strong><span class=\"kw-ttt\">intubation orotrachéale</span> précoce</strong>, avant l'aggravation de l'<span class=\"kw-clinique\">œdème</span>. Une brûlure profonde circulaire du cou peut imposer une <strong>incision de décharge</strong>.</div>\n      <div class=\"callout callout-warn\">\n        <strong>À compléter.</strong> Aucune image n'est disponible dans <span class=\"kw-clinique\">les</span> fiches sources pour cet objectif « Contenu multimédia ». Kevin fournira l'iconographie (suie péri-orificielle, <span class=\"kw-imagerie\">fibroscopie</span> bronchique) ultérieurement.</div>","frequence":0},{"id":"334-18","rang":"A","rubrique":"Prise en charge","titre":"Connaître les principes des soins locaux de brûlure","contenu":"<h4 style=\"margin:14px 0 6px;font-size:14px;\">Sur <span class=\"kw-clinique\">les</span> lieux — premiers gestes</h4>\n      <ul>\n        <li>Interrompre l'agent brûlant ; retirer <span class=\"kw-clinique\">les</span> vêtements <strong>non adhérents</strong> et les bagues (<strong>ne pas ôter les vêtements adhérents</strong> sauf imprégnation par liquide chaud/caustique).</li>\n        <li><strong>Refroidir</strong> : règle des « 15 » (eau à<span class=\"kw-chiffre\"> 15 °C</span> pendant <span class=\"kw-chiffre\">15 min</span>) — diminue douleur et profondeur ; ou <span class=\"kw-ttt\">hydrogel</span> (Brulstop). <span class=\"kw-ci\">Arrêter le refroidissement si sensation de froid</span> — risque d'<span class=\"kw-clinique\">hypothermie</span>.</li>\n        <li>Brûlure <span class=\"kw-etio\">chimique</span> : rinçage abondant <span class=\"kw-chiffre\">30 min</span> à l'eau.</li>\n      </ul>\n      <h4 style=\"margin:14px 0 6px;font-size:14px;\">Soins locaux hospitaliers</h4>\n      <ul>\n        <li>Lavage, <strong>mise à plat des phlyctènes</strong> au savon antiseptique, rasage péri-lésionnel.</li>\n        <li>Pansement avec un topique anti-<span class=\"kw-etio\">infectieux</span> : <span class=\"kw-ttt\">sulfadiazine d'argent</span> (Flammazine).</li>\n        <li>Couverture cutanée temporaire ou définitive (<span class=\"kw-ttt\">allogreffe</span>) — pierre angulaire de la prévention de l'infection.</li>\n      </ul>\n      <div class=\"callout callout-warn\">\n        <strong>Piège.</strong> <span class=\"kw-ci\">Aucune antibiothérapie systémique systématique</span> dans <span class=\"kw-clinique\">les</span> premières heures — sauf brûlure souillée ou périnéale. La prévention antitétanique est en revanche systématique.</div>","frequence":1},{"id":"334-19","rang":"B","rubrique":"Prise en charge","titre":"Connaître les principes de la prise en charge d’un brûlé (hors soins locaux)","contenu":"<table >\n        <thead><tr><th>Volet</th><th>Prise en charge</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Hémodynamique</strong></td><td>Remplissage : <span class=\"kw-chiffre\">20 mL/kg</span> de <span class=\"kw-ttt\">Ringer lactate</span> sur la 1ʳᵉ heure si SCB <span class=\"kw-chiffre\">&gt; 10 %</span> ; puis <strong>formule de Parkland</strong> (<span class=\"kw-chiffre\">4 mL/kg/%SCB</span> sur <span class=\"kw-chiffre\">24 h</span>). <span class=\"kw-ttt\">Noradrénaline</span> si besoin.</td></tr>\n          <tr><td><strong>Respiratoire</strong></td><td><span class=\"kw-ttt\">IOT</span> + sonde gastrique si <span class=\"kw-def\">Glasgow</span> &lt; 8, brûlures &gt;<span class=\"kw-chiffre\"> 50 %</span>, ou risque d'<span class=\"kw-clinique\">œdème</span> cervical. Haut risque de <span class=\"kw-alerte\">SDRA</span>.</td></tr>\n          <tr><td><strong><span class=\"kw-clinique\">Hypothermie</span></strong></td><td>Risque majeur si SCB <span class=\"kw-chiffre\">&gt; 20 %</span> → limiter le refroidissement, emballer dans des champs stériles + couverture.</td></tr>\n          <tr><td><strong>Douleur</strong></td><td><span class=\"kw-ttt\">Paracétamol</span> + <span class=\"kw-ttt\">morphine</span>, ± <span class=\"kw-ttt\">kétamine</span>, ± sédation profonde.</td></tr>\n          <tr><td><strong>Nutrition</strong></td><td><strong>Nutrition entérale précoce</strong> — état hypermétabolique, prévention de la dénutrition.</td></tr>\n          <tr><td><strong><span class=\"kw-ttt\">Chirurgie</span></strong></td><td><span class=\"kw-alerte\">Brûlure circulaire profonde</span> → <strong>incisions de décharge</strong> en <span class=\"kw-alerte\">urgence</span> (&lt;<span class=\"kw-chiffre\"> 6 h</span>) : escarrotomies, aponévrotomies.</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\">\n        <strong>Piège.</strong> Le <span class=\"kw-alerte\">syndrome du compartiment abdominal</span> peut compliquer un remplissage important + la fuite capillaire.</div>","frequence":0},{"id":"334-20","rang":"B","rubrique":"Prise en charge","titre":"Connaître les principes de prise en charge d’un syndrome d’inhalation de fumées d’incendie","contenu":"<ul>\n        <li><strong>Liberté des voies aériennes</strong> : <span class=\"kw-ttt\">IOT</span> précoce si <span class=\"kw-clinique\">œdème</span> des VAS / <span class=\"kw-alerte\">détresse</span> respiratoire.</li>\n        <li><span class=\"kw-ttt\">Oxygénothérapie</span> à <strong><span class=\"kw-chiffre\">15 L/min</span></strong> systématique si suspicion d'intoxication au <span class=\"kw-etio\">CO</span> (<span class=\"kw-clinique\">les</span> <span class=\"kw-bio\">GDS</span> normaux n'éliminent pas le diagnostic). <span class=\"kw-imagerie\">Oxygénothérapie hyperbare</span> discutée si signes neurologiques, <span class=\"kw-alerte\">ischémie myocardique</span>, <span class=\"kw-ci\">grossesse</span>.</li>\n        <li><strong>Antidote du cyanure</strong> : <span class=\"kw-ttt\">hydroxocobalamine</span> (Cyanokit) en <span class=\"kw-alerte\">urgence</span> si intoxication massive suspectée (gravité clinique + <span class=\"kw-bio\">hyperlactatémie &gt; 10 mmol/L</span>).</li>\n        <li><span class=\"kw-imagerie\">Fibroscopie bronchique</span> : examen diagnostique de référence (suies, muqueuse <span class=\"kw-etio\">inflammatoire</span>) ; discuter le bilan lésionnel.</li>\n      </ul>\n      <div class=\"callout callout-warn\">\n        <strong>Piège.</strong> Le Cyanokit expose à une <span class=\"kw-alerte\">néphropathie aiguë</span> par précipitation de cristaux d'oxalate de calcium → le réserver aux patients avec <span class=\"kw-alerte\">signes de gravité</span>. La coloration <strong>rouge carmin des urines</strong> est physiologique (métabolisme de l'antidote).</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 337 — Intoxication aiguë</em></p>","frequence":0},{"id":"334-21","rang":"B","rubrique":"Physiopathologie","titre":"Connaître la physiopathologie de l’atteinte des organes intrathoraciques après traumatisme","contenu":"<table >\n        <thead><tr><th>Mécanisme</th><th>Lésions</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Traumatismes fermés (<span class=\"kw-chiffre\">90 %</span>)</strong> — compression / écrasement</td><td>Lésions pariétales (fractures de côtes, du sternum), <span class=\"kw-clinique\">contusion pulmonaire</span>, contusion cardiaque, déchirure diaphragmatique.</td></tr>\n          <tr><td>Traumatismes fermés — décélération brutale</td><td>Lésions d'étirement/cisaillement aux jonctions mobile-fixe : <strong><span class=\"kw-alerte\">rupture de l'isthme aortique</span></strong>, <span class=\"kw-alerte\">rupture</span> bronchique. Lésions souvent <span class=\"kw-alerte\">occultes</span> (paroi intacte).</td></tr>\n          <tr><td>Traumatismes fermés — <span class=\"kw-etio\">blast</span></td><td>Transmission d'ondes de surpression/<span class=\"kw-def\">dépression</span> aux organes à travers la paroi.</td></tr>\n          <tr><td><strong>Traumatismes pénétrants (<span class=\"kw-chiffre\">10 %</span>)</strong></td><td><span class=\"kw-etio\">Arme blanche</span>, <span class=\"kw-etio\">arme à feu</span> : atteinte directe + blast balistique. Toute plaie parasternale = risque cardiaque ; toute plaie entre <span class=\"kw-clinique\">les</span> lignes médio-claviculaires = risque pour les gros vaisseaux.</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\">\n        <strong>À retenir.</strong> L'importance des lésions intrathoraciques n'est <strong>pas corrélée</strong> à la sévérité des lésions pariétales : une décélération peut rompre l'aorte sans fracture de côte.</div>","frequence":1},{"id":"334-22","rang":"A","rubrique":"Diagnostic positif","titre":"Savoir suspecter un traumatisme thoracique","contenu":"<p>La suspicion repose sur l'<strong>inspection</strong> et l'<strong>examen physique</strong>, qui orientent vers une <span class=\"kw-clinique\">lésion</span> sous-jacente :</p>\n      <table >\n        <thead><tr><th>Signe clinique</th><th>Lésion suspectée</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-clinique\">Dyspnée</span>, <span class=\"kw-clinique\">cyanose</span></td><td><span class=\"kw-imagerie\">Épanchement pleural</span>, contusion pulmonaire, <span class=\"kw-alerte\">tamponnade</span>.</td></tr>\n          <tr><td><span class=\"kw-clinique\">Respiration paradoxale</span></td><td><span class=\"kw-alerte\">Volet thoracique</span>.</td></tr>\n          <tr><td><span class=\"kw-clinique\">Turgescence jugulaire</span></td><td><span class=\"kw-alerte\">Tamponnade</span> ; <span class=\"kw-alerte\">pneumothorax compressif</span>.</td></tr>\n          <tr><td><span class=\"kw-clinique\">Asymétrie</span> auscultatoire ; <span class=\"kw-clinique\">tympanisme</span></td><td><span class=\"kw-imagerie\">Épanchement pleural</span> (liquidien/gazeux), <span class=\"kw-imagerie\">pneumothorax</span>.</td></tr>\n          <tr><td><span class=\"kw-clinique\">Emphysème sous-cutané</span> thoracique</td><td><span class=\"kw-imagerie\">Pneumothorax</span>. <em>Cervical</em> → <span class=\"kw-alerte\">rupture</span> trachéo-bronchique/œsophagienne.</td></tr>\n          <tr><td><span class=\"kw-clinique\">Asymétrie</span> des pouls/PA aux membres ; souffle interscapulaire</td><td><span class=\"kw-alerte\">Rupture aortique traumatique</span>.</td></tr>\n          <tr><td><span class=\"kw-clinique\">Ecchymose</span> pariétale (« signe de la ceinture »)</td><td><span class=\"kw-alerte\">Choc</span> à haute vélocité — <span class=\"kw-clinique\">lésion</span> sous-jacente sévère probable.</td></tr>\n        </tbody>\n      </table>","frequence":0},{"id":"334-23","rang":"A","rubrique":"Examens complémentaires","titre":"Savoir demander les examens complémentaires permettant le diagnostic de traumatisme thoracique","contenu":"<table >\n        <thead><tr><th>Examen</th><th>Apport</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-bio\">Gaz du sang</span></td><td>Retentissement de l'atteinte respiratoire.</td></tr>\n          <tr><td><span class=\"kw-bio\">ECG</span>, <span class=\"kw-bio\">troponine</span>, <span class=\"kw-imagerie\">ETT</span></td><td>Recherche d'une <span class=\"kw-clinique\">contusion myocardique</span>.</td></tr>\n          <tr><td><span class=\"kw-imagerie\">Échographie pleuro-pulmonaire</span> (FAST/eFAST)</td><td><span class=\"kw-imagerie\">Épanchement pleural</span>, <span class=\"kw-imagerie\">pneumothorax</span>, contusion — réalisable au lit, performante chez l'instable.</td></tr>\n          <tr><td><span class=\"kw-imagerie\">Radiographie thoracique</span> (face)</td><td>Examen initial sur le brancard ; supplantée par le FAST/<span class=\"kw-imagerie\">TDM</span>.</td></tr>\n          <tr><td><strong><span class=\"kw-imagerie\">TDM thoracique injectée</span></strong></td><td>Examen de référence : contusions pulmonaires, <span class=\"kw-alerte\">hémomédiastin</span>, lésions des gros vaisseaux.</td></tr>\n        </tbody>\n      </table>","frequence":0,"liens":[{"href":"https://radiopaedia.org/articles/penetrating-thoracic-trauma","label":"Radiopaedia : Penetrating thoracic trauma"},{"href":"https://radiopaedia.org/articles/aortic-isthmus","label":"Radiopaedia : Aortic isthmus"},{"href":"https://radiopaedia.org/articles/thoracic-aortic-injury","label":"Radiopaedia : Thoracic aortic injury"},{"href":"https://radiopaedia.org/articles/diaphragmatic-rupture","label":"Radiopaedia : Diaphragmatic rupture"}]},{"id":"334-24","rang":"A","rubrique":"Examens complémentaires","titre":"Savoir reconnaître un hémothorax et un pneumothorax sur une radiographie","contenu":"<table >\n        <thead><tr><th>Épanchement</th><th>Sémiologie radiographique</th></tr></thead>\n        <tbody>\n          <tr><td><strong><span class=\"kw-imagerie\">Hémothorax</span></strong></td><td><span class=\"kw-radio\">Opacité déclive dense et homogène</span> effaçant la coupole diaphragmatique ; <strong>ligne de Damoiseau</strong> (limite supérieure concave). Cliché debout : comblement du cul-de-sac pleural.</td></tr>\n          <tr><td><strong><span class=\"kw-imagerie\">Pneumothorax</span></strong></td><td><span class=\"kw-radio\">Hyperclarté</span> avasculaire périphérique ; ligne pleurale visible ; <span class=\"kw-radio\">asymétrie de transparence</span> des hémichamps.</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\">\n        <strong>Piège.</strong> Un <span class=\"kw-imagerie\">pneumothorax</span> peut être <strong>occulte</strong> (non visible sur la <span class=\"kw-imagerie\">RXT</span> de face couché) et n'être détecté qu'au <span class=\"kw-imagerie\">TDM</span> — il ne bénéficie alors pas forcément d'un <span class=\"kw-ttt\">drainage</span>.</div>\n      <div class=\"callout callout-danger\">\n        <strong><span class=\"kw-alerte\">Urgence</span>.</strong> Un <span class=\"kw-alerte\">pneumothorax compressif</span> se traduit par une déviation médiastinale controlatérale ± abaissement de la coupole : c'est un diagnostic <strong>clinique</strong> qui n'attend pas la <span class=\"kw-imagerie\">radiographie</span>.</div>","frequence":0},{"id":"334-25","rang":"A","rubrique":"Contenu multimédia","titre":"Radiographies d’hémothorax et de pneumothorax","contenu":"<p>Repères de lecture d'une <span class=\"kw-imagerie\">radiographie thoracique</span> de traumatisé :</p>\n      <ul>\n        <li><strong><span class=\"kw-imagerie\">Hémothorax</span></strong> : <span class=\"kw-radio\">opacité déclive homogène</span>, ligne de Damoiseau, grisaille diffuse d'un hémichamp ; ± déviation médiastinale si abondant.</li>\n        <li><strong><span class=\"kw-imagerie\">Pneumothorax</span></strong> : <span class=\"kw-radio\">hyperclarté périphérique avasculaire</span>, ligne pleurale fine, parfois moignon pulmonaire rétracté au hile.</li>\n        <li><strong><span class=\"kw-alerte\">Rupture</span> de l'isthme aortique</strong> : <span class=\"kw-radio\">élargissement du médiastin &gt; 8 cm</span>, disparition du bouton aortique, déviation trachéale.</li>\n      </ul>\n      <figure class=\"obj-figure\">\n        <img src=\"../assets/images/334/rxt-pneumothorax-hemothorax.png\" alt=\"Radiographie de thorax de face : pneumothorax complet gauche (hyperclarté avasculaire, poumon rétracté au hile) et hémothorax droit (opacité déclive de l'hémithorax)\" loading=\"lazy\">\n        <figcaption><span class=\"kw-imagerie\">Pneumothorax</span> complet gauche : <span class=\"kw-radio\">hyperclarté avasculaire périphérique</span>, poumon rétracté au hile. <span class=\"kw-imagerie\">Hémothorax</span> droit : <span class=\"kw-radio\">opacité déclive homogène</span> de l'hémithorax (± fractures de côtes). Source : banque iconographique officielle EDN (« Imagerie à connaître »).</figcaption>\n      </figure>","frequence":0},{"id":"334-26","rang":"A","rubrique":"Identifier une urgence","titre":"Savoir identifier les situations indiquant le recours à une thérapeutique de sauvetage","contenu":"<table >\n        <thead><tr><th>Situation</th><th>Geste de sauvetage</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-alerte\">Pneumothorax compressif</span> (asphyxiant)</td><td><strong>Exsufflation</strong> à l'aiguille en <span class=\"kw-alerte\">urgence</span>, puis <span class=\"kw-ttt\">drainage</span>.</td></tr>\n          <tr><td>Plaie soufflante du thorax</td><td>Pansement <strong>non occlusif</strong> (3 côtés) pour prévenir le <span class=\"kw-imagerie\">pneumothorax</span> compressif.</td></tr>\n          <tr><td><span class=\"kw-alerte\">Hémothorax</span> massif</td><td><span class=\"kw-ttt\">Drainage</span> ; <strong>thoracotomie d'hémostase</strong> si drainage immédiat <span class=\"kw-chiffre\">&gt; 1 500 mL</span> ou débit <span class=\"kw-chiffre\">&gt; 200 mL/h</span>.</td></tr>\n          <tr><td>Traumatisme pénétrant / suspicion de <span class=\"kw-alerte\">tamponnade</span></td><td>Position demi-assise ; transfert urgent ; <span class=\"kw-ttt\">antibioprophylaxie</span>.</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-danger\">\n        <strong><span class=\"kw-alerte\">Urgence</span>.</strong> Chez un patient non stabilisé, la priorité est l'<strong>hémostase rapide</strong> (<span class=\"kw-ttt\">drainage</span>, chirurgie, embolisation) avant tout body-<span class=\"kw-imagerie\">TDM</span>.</div>","frequence":0},{"id":"334-27","rang":"B","rubrique":"Prise en charge","titre":"Connaître les principes de la prise en charge d’un traumatisme thoracique","contenu":"<ul>\n        <li><strong>Analgésie</strong> rigoureuse : <span class=\"kw-ttt\">morphine</span> + <span class=\"kw-ttt\">kétamine</span> IV ; <strong><span class=\"kw-ttt\">ALR</span></strong> (péridurale thoracique, bloc paravertébral) si douleur résistante &gt;<span class=\"kw-chiffre\"> 6 h</span>. La douleur limite la <span class=\"kw-clinique\">toux</span> → atélectasie, surinfection.</li>\n        <li><strong>Ventilation</strong> : <span class=\"kw-ttt\">VNI</span> précoce si pas de <span class=\"kw-imagerie\">pneumothorax</span> ; ventilation protectrice (<span class=\"kw-chiffre\">6-8 mL/kg</span>) si IOT.</li>\n        <li><strong><span class=\"kw-ttt\">Drainage</span> thoracique</strong> par voie axillaire : drain <span class=\"kw-chiffre\">18-24 F</span> pour un <span class=\"kw-imagerie\">pneumothorax</span>, <span class=\"kw-chiffre\">28-36 F</span> pour un hémothorax ; drainage obl<span class=\"kw-chiffre\">iga</span>toire si hémothorax <span class=\"kw-chiffre\">&gt; 500 mL</span>.</li>\n        <li><strong>Avis chirurgical spécialisé</strong> : traumatisme pénétrant, <span class=\"kw-clinique\">lésion</span> cardiaque, volet thoracique, <span class=\"kw-alerte\">rupture de l'isthme aortique</span> (traitement par <span class=\"kw-ttt\">endoprothèse</span> endovasculaire), lésion diaphragmatique.</li>\n        <li>Kinésithérapie respiratoire incitative pour <span class=\"kw-clinique\">les</span> fractures de côtes.</li>\n      </ul>","frequence":0},{"id":"334-28","rang":"B","rubrique":"Physiopathologie","titre":"Connaître la physiopathologie de l’atteinte des organes abdominaux (intra et rétropéritonéaux) après traumatisme","contenu":"<p><span class=\"kw-clinique\">Les</span> traumatismes fermés sont majoritaires (<span class=\"kw-chiffre\">75 %</span>). Mécanismes lésionnels :</p>\n      <ul>\n        <li><strong>Écrasement</strong> des viscères entre la paroi et le plan rigide postérieur (rachis, côtes).</li>\n        <li><strong>Arrachement</strong> des organes pédiculés (rate, rein, grêle) lors d'un trauma tangentiel.</li>\n        <li><strong>Désinsertion</strong> lors d'une décélération brutale (rate par son long pédicule, foie par sa <span class=\"kw-clinique\">masse</span>).</li>\n        <li><strong>Éclatement</strong> d'un organe creux en réplétion (estomac, vessie).</li>\n      </ul>\n      <h4 style=\"margin:14px 0 6px;font-size:14px;\">Deux risques principaux</h4>\n      <table >\n        <thead><tr><th>Risque</th><th>Caractéristiques</th></tr></thead>\n        <tbody>\n          <tr><td><strong><span class=\"kw-alerte\">Choc hémorragique</span></strong></td><td>Gravité <strong>initiale</strong> : <span class=\"kw-clinique\">lésion</span> d'un organe plein (rate, foie) ou <span class=\"kw-alerte\">rupture</span> vasculaire. Hémorragie intra- ou <span class=\"kw-alerte\">rétropéritonéale</span>.</td></tr>\n          <tr><td><strong>Perforation d'organe creux</strong></td><td>2ᵉ problème : <span class=\"kw-alerte\">diagnostic difficile et retardé</span> (<span class=\"kw-def\">stade</span> de <span class=\"kw-clinique\">péritonite</span>) ; signe indirect = <span class=\"kw-radio\">pneumopéritoine</span>.</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\">\n        <strong>Piège.</strong> <span class=\"kw-clinique\">Les</span> dispositifs de sécurité (ceinture, airbag) protègent moins bien l'abdomen que le crâne et le thorax.</div>\n      <div class=\"callout callout-danger\">\n        <strong><span class=\"kw-alerte\">Piège classant — rupture splénique différée.</span></strong> Un <span class=\"kw-clinique\">hématome sous-capsulaire</span> de la rate peut se rompre secondairement, <strong>jusqu'à <span class=\"kw-chiffre\">J15</span></strong> après le traumatisme initial, en dehors de tout nouvel épisode traumatique — d'où l'intérêt d'une <span class=\"kw-def\">surveillance</span> clinique et échographique prolongée même chez un patient initialement stable et asymptomatique.</div>","frequence":0},{"id":"334-29","rang":"A","rubrique":"Diagnostic positif","titre":"Savoir suspecter un traumatisme abdominal","contenu":"<table >\n        <thead><tr><th>Temps de l'examen</th><th>Signes</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Symptômes</strong></td><td><span class=\"kw-clinique\">Douleur abdominale</span> ; <span class=\"kw-clinique\">irradiation</span> à la <strong>scapula gauche</strong> (trauma splénique) ou <strong>droite</strong> (trauma hépatique) ; <span class=\"kw-clinique\">hématurie</span> (<span class=\"kw-clinique\">lésion</span> rénale).</td></tr>\n          <tr><td><strong>Inspection</strong></td><td>Contusions, « <span class=\"kw-clinique\">signe de la ceinture</span> », météorisme.</td></tr>\n          <tr><td><strong>Palpation</strong></td><td><span class=\"kw-clinique\">Défense</span>, <span class=\"kw-clinique\">contracture</span>, <span class=\"kw-clinique\">matité</span> (hémopéritoine) ou tympanisme (pneumopéritoine).</td></tr>\n          <tr><td><strong>Syndromes</strong></td><td>Syndrome <span class=\"kw-clinique\">péritonéal</span> ; syndrome <span class=\"kw-clinique\">occlusif</span> ; signes de <span class=\"kw-alerte\">choc hémorragique</span>.</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\">\n        <strong>Piège.</strong> Évoquer un traumatisme abdominal pendant le transport devant : remplissage par <span class=\"kw-chiffre\">&gt; 1 L</span>, <span class=\"kw-clinique\">hypotension</span> persistante, <span class=\"kw-alerte\">arrêt cardiaque</span> massé chez un traumatisé. <strong>Tout traumatisé sévère est un traumatisé du bassin</strong> jusqu'à preuve du contraire (instabilité à la palpation des crêtes iliaques).</div>","frequence":0},{"id":"334-30","rang":"A","rubrique":"Examens complémentaires","titre":"Savoir demander les examens d’imagerie permettant le diagnostic de traumatisme abdominal","contenu":"<p>Le choix de l'imagerie dépend de la <strong>stabilité hémodynamique</strong> :</p>\n      <table >\n        <thead><tr><th>Statut</th><th>Imagerie</th></tr></thead>\n        <tbody>\n          <tr><td><strong><span class=\"kw-alerte\">Patient instable</span></strong></td><td><span class=\"kw-imagerie\">RXT</span> + <span class=\"kw-imagerie\">RX bassin</span> + <strong><span class=\"kw-imagerie\">FAST-échographie</span></strong> : recherche un <span class=\"kw-alerte\">hémopéritoine</span> (image anéchogène : espace inter-hépato-rénal de Morrison, inter-spléno-rénal de Köhler, cul-de-sac de Douglas). <strong>Pas de <span class=\"kw-imagerie\">TDM</span> injectée en <span class=\"kw-alerte\">urgence</span></strong> (distracteur d'annale).</td></tr>\n          <tr><td><strong>Patient stable</strong></td><td><strong><span class=\"kw-imagerie\">TDM abdomino-pelvienne injectée</span></strong> (body-<span class=\"kw-imagerie\">TDM</span>) : cartographie <span class=\"kw-clinique\">les</span> lésions ; le <span class=\"kw-alerte\">blush</span> (fuite active de produit de contraste) identifie le foyer <span class=\"kw-etio\">hémorragique</span>.</td></tr>\n        </tbody>\n      </table>\n      <figure class=\"obj-figure\">\n        <img src=\"../assets/images/334/tdm-trauma-splenique.png\" alt=\"TDM abdominale d'un traumatisme splénique : coupe sans injection et coupe au temps artériel montrant une fracture de rate sous forme d'hypodensité arciforme intra-splénique\" loading=\"lazy\">\n        <figcaption><span class=\"kw-imagerie\">TDM</span> d'un traumatisme splénique : fracture de rate = hypodensité arciforme intra-splénique à tous les temps, avec réhaussement tigré physiologique au temps artériel. Source : fiche source EDN item 334.</figcaption>\n      </figure>\n      <div class=\"callout callout-warn\">\n        <strong>Piège.</strong> La FAST-<span class=\"kw-imagerie\">échographie</span> <strong>ne voit pas</strong> l'hémorragie <span class=\"kw-alerte\">rétropéritonéale</span> — siège électif des hémorragies sur traumatisme du bassin.</div>","frequence":0,"liens":[{"href":"https://cerf.radiologie.fr/sites/cerf.radiologie.fr/files/Enseignement/pdf/U11%20Q329%20traumadig.pdf","label":"CERF — Traumatisme abdominal (U11)"},{"href":"https://radiopaedia.org/articles/liver-trauma","label":"Radiopaedia : Liver trauma"},{"href":"https://radiopaedia.org/articles/urethral-injury-1","label":"Radiopaedia : Urethral injury 1"}]},{"id":"334-31","rang":"A","rubrique":"Identifier une urgence","titre":"Savoir identifier le recours à une thérapeutique d’hémostase en urgence chez l’adulte et l’enfant","contenu":"<p>Le recours à une hémostase en <span class=\"kw-alerte\">urgence</span> est dicté par l'<strong>instabilité hémodynamique</strong> :</p>\n      <table >\n        <thead><tr><th>Situation</th><th>Geste d'hémostase</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-alerte\">Instable</span> + hémopéritoine au FAST</td><td><strong>Laparotomie « damage control »</strong> de sauvetage.</td></tr>\n          <tr><td><span class=\"kw-alerte\">Choc</span> + fracas du bassin radiologique + FAST négative</td><td>Hémorragie pelvienne probable → <strong><span class=\"kw-imagerie\">artério-embolisation</span></strong>.</td></tr>\n          <tr><td>Stable + blush artériel au <span class=\"kw-imagerie\">TDM</span></td><td>Embolisation artérielle sélective différée.</td></tr>\n          <tr><td>Instabilité extrême réfractaire</td><td><strong>Ballon d'occlusion intra-aortique</strong> — thérapeutique de sauvetage avant <span class=\"kw-ttt\">chirurgie</span>/embolisation.</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\">\n        <strong>À retenir.</strong> Chez le patient <strong>stable</strong> (<span class=\"kw-chiffre\">90 %</span> des traumatismes abdominaux fermés), l'attitude est <span class=\"kw-def\">non opératoire</span> avec <span class=\"kw-def\">surveillance</span> en milieu chirurgical, quel que soit l'organe atteint.</div>","frequence":0},{"id":"334-32","rang":"B","rubrique":"Prise en charge","titre":"Connaître les principes de la prise en charge d’un traumatisme abdominal chez l’adulte et l’enfant","contenu":"<h4 style=\"margin:14px 0 6px;font-size:14px;\">Patient stable (<span class=\"kw-chiffre\">90 %</span>)</h4>\n      <p>Attitude <strong>non opératoire</strong> : <span class=\"kw-def\">surveillance</span> clinique, <span class=\"kw-ttt\">biologique</span> et scannographique en milieu chirurgical. Embolisation artérielle différée si blush ; geste radioguidé ou <span class=\"kw-ttt\">chirurgie</span> réglée éventuels.</p>\n      <h4 style=\"margin:14px 0 6px;font-size:14px;\">Patient instable</h4>\n      <p><strong><span class=\"kw-ttt\">Chirurgie</span> de damage control</strong> : laparotomie écourtée (incision xypho-pubienne), exploration, geste d'hémostase « sommaire » :</p>\n      <ul>\n        <li><span class=\"kw-alerte\">Rupture</span> de rate : <span class=\"kw-ttt\">splénectomie d'hémostase</span> (± précédée d'embolisation).</li>\n        <li><span class=\"kw-clinique\">Lésion</span> hépatique : <span class=\"kw-ttt\">packing hépatique</span>, clampage.</li>\n        <li><span class=\"kw-alerte\">Rupture</span> rénale : <span class=\"kw-ttt\">néphrectomie</span>.</li>\n        <li><span class=\"kw-clinique\">Lésion</span> d'organe creux / mésentérique : <strong>laparotomie exploratrice</strong> (pas de place pour la cœlioscopie ici).</li>\n      </ul>\n      <p>Fermeture pariétale par laparostome (système VAC) pour éviter l'hyperpression abdominale, permettant un <strong>« second look »</strong> à<span class=\"kw-chiffre\"> 24-48 h</span>. <span class=\"kw-ttt\">Antibiothérapie</span> si ouverture du tube digestif ou trauma pénétrant.</p>\n      <div class=\"callout callout-warn\">\n        <strong>Complication spécifique.</strong> Le <span class=\"kw-alerte\">syndrome du compartiment abdominal</span> : pression intra-abdominale <span class=\"kw-chiffre\">&gt; 20 mmHg</span> (mesure intra-vésicale) → baisse de la pression de perfusion abdominale → <span class=\"kw-alerte\">défaillance rénale</span> et respiratoire. Traitement : laparostome.</div>","frequence":1},{"id":"334-33","rang":"B","rubrique":"Physiopathologie","titre":"Connaître les mécanismes lésionnels","contenu":"<p>Une <strong><span class=\"kw-def\">fracture</span></strong> est une <span class=\"kw-alerte\">rupture</span>/discontinuité osseuse interrompant la ligne corticale.</p>\n      <table >\n        <thead><tr><th>Mécanisme</th><th>Caractéristiques</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Traumatisme direct</strong></td><td>Impact du dehors vers le dedans. Fracture <strong>au point d'impact</strong>. Lésions des parties molles, <span class=\"kw-alerte\">ouverture cutanée</span> fréquente. Contexte : AVP, accident du travail.</td></tr>\n          <tr><td><strong>Traumatisme indirect</strong></td><td>Torsion/flexion du dedans vers le dehors. Fracture <strong>à distance</strong> du point d'impact ; lésions des articulations sus- et sous-jacentes. Contexte : sport (ski), chute simple.</td></tr>\n        </tbody>\n      </table>\n      <h4 style=\"margin:14px 0 6px;font-size:14px;\">Types de fractures selon l'os</h4>\n      <table >\n        <thead><tr><th>Type</th><th>Contrainte / os</th><th>Exemple</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-def\">Traumatique</span></td><td>Contrainte brutale, os normal</td><td>—</td></tr>\n          <tr><td><span class=\"kw-def\">Pathologique</span></td><td>Contrainte banale, <span class=\"kw-etio\">os pathologique</span></td><td>Métastase osseuse, maladie de Paget</td></tr>\n          <tr><td><span class=\"kw-def\">De contrainte (fatigue)</span></td><td>Contraintes répétées, os normal</td><td>Surentraînement sportif</td></tr>\n          <tr><td><span class=\"kw-def\">Par insuffisance osseuse</span></td><td>Contrainte banale, <span class=\"kw-etio\">os fragile</span></td><td><span class=\"kw-etio\">Ostéoporose</span></td></tr>\n        </tbody>\n      </table>","frequence":0},{"id":"334-34","rang":"B","rubrique":"Physiopathologie","titre":"Connaître la classification des fractures ouvertes","contenu":"<p>Une <strong><span class=\"kw-def\">fracture ouverte</span></strong> est une fracture dont une plaie cutanée communique avec le foyer. C'est un facteur de mauvais <span class=\"kw-def\">pronostic</span> : <span class=\"kw-alerte\">porte d'entrée infectieuse</span>, risque de retard de consolidation et de <span class=\"kw-alerte\">pseudarthrose</span>.</p>\n      <h4 style=\"margin:14px 0 6px;font-size:14px;\"><span class=\"kw-def\">Classification</span> de Gustilo et Anderson (référence actuelle)</h4>\n      <table >\n        <thead><tr><th>Type</th><th>Description</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Type 1</strong></td><td>Plaie propre, longueur <span class=\"kw-chiffre\">&lt; 1 cm</span>.</td></tr>\n          <tr><td><strong>Type 2</strong></td><td>Plaie propre, <span class=\"kw-chiffre\">&gt; 1 cm</span>, sans dégâts extensifs des parties molles.</td></tr>\n          <tr><td><strong>Type 3A</strong></td><td>Lésions extensives des parties molles, mais couverture osseuse possible, périoste intact.</td></tr>\n          <tr><td><strong>Type 3B</strong></td><td>Perte de substance extensive, os exposé/dépériosté, contamination massive → <span class=\"kw-ttt\">lambeau</span> de couverture nécessaire.</td></tr>\n          <tr><td><strong>Type 3C</strong></td><td><span class=\"kw-alerte\">Lésion artérielle</span> nécessitant une réparation.</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\">\n        <strong>À retenir.</strong> L'ancienne <span class=\"kw-def\">classification</span> de <span class=\"kw-def\">Cauchoix et Duparc</span> ne tenait compte que de l'ouverture cutanée. Gustilo lui est préférée car elle intègre l'atteinte des parties molles et vasculaires.</div>","frequence":0},{"id":"334-35","rang":"A","rubrique":"Diagnostic positif","titre":"Savoir suspecter à l’anamnèse et à l’examen clinique une lésion osseuse","contenu":"<p>L'<strong>anamnèse</strong> précise le mécanisme (direct/indirect), l'énergie du traumatisme et le <span class=\"kw-def\">terrain</span>. La fracture est suspectée devant la <strong>triade clinique</strong> :</p>\n      <ul>\n        <li><span class=\"kw-clinique\">Douleur</span> localisée, exacerbée à la palpation.</li>\n        <li><span class=\"kw-clinique\">Déformation</span> du membre (angulation, raccourcissement, décalage rotatoire).</li>\n        <li><span class=\"kw-clinique\">Impotence fonctionnelle</span> du membre.</li>\n      </ul>\n      <h4 style=\"margin:14px 0 6px;font-size:14px;\">Facteurs aggravants à rechercher</h4>\n      <ul>\n        <li><strong>Polyfracturé</strong> des membres : plusieurs foyers fracturaires.</li>\n        <li><strong>Articulation flottante</strong> : fracture au-dessus et au-dessous d'une même articulation.</li>\n        <li><strong>Fracture articulaire</strong> : risque de complications tardives (arthrose, raideur).</li>\n        <li>Fractures-luxations.</li>\n      </ul>\n      <div class=\"callout callout-danger\">\n        <strong><span class=\"kw-alerte\">Urgence</span> à ne pas manquer.</strong> Devant toute <span class=\"kw-clinique\">lésion</span> osseuse, l'examen recherche systématiquement <span class=\"kw-clinique\">les</span> <span class=\"kw-alerte\">complications vasculo-nerveuses</span> : <span class=\"kw-clinique\">pouls périphériques</span>, examen sensitivo-moteur en aval, recherche d'une ouverture cutanée.</div>","frequence":3},{"id":"334-36","rang":"A","rubrique":"Identifier une urgence","titre":"Savoir suspecter des complications vasculaires et neurologiques","contenu":"<h4 style=\"margin:14px 0 6px;font-size:14px;\">Complications vasculaires</h4>\n      <ul>\n        <li><strong>Ischémiques</strong> : <span class=\"kw-clinique\">asymétrie des pouls</span>, <span class=\"kw-clinique\">pâleur</span> et froideur du membre en aval, douleur intense.</li>\n        <li><span class=\"kw-alerte\">Artère poplitée</span> à risque si <strong>luxation du genou</strong> ou fracture fémorale distale/tibiale proximale ; <span class=\"kw-alerte\">artère humérale</span> si fracture supracondylienne.</li>\n        <li>Confirmation : <span class=\"kw-imagerie\">écho-doppler</span>, <span class=\"kw-imagerie\">angio-TDM</span>, <span class=\"kw-imagerie\">artériographie</span>.</li>\n      </ul>\n      <h4 style=\"margin:14px 0 6px;font-size:14px;\">Complications neurologiques (nerf selon la localisation)</h4>\n      <table >\n        <thead><tr><th><span class=\"kw-clinique\">Lésion</span> osseuse</th><th>Nerf à risque</th></tr></thead>\n        <tbody>\n          <tr><td>Col de la fibula</td><td>Nerf <span class=\"kw-clinique\">fibulaire</span></td></tr>\n          <tr><td>Diaphyse humérale</td><td>Nerf <span class=\"kw-clinique\">radial</span></td></tr>\n          <tr><td>Palette humérale</td><td>Nerf <span class=\"kw-clinique\">ulnaire</span></td></tr>\n          <tr><td>Fracture du radius</td><td>Nerf <span class=\"kw-clinique\">médian</span></td></tr>\n          <tr><td>Luxation gléno-humérale</td><td>Nerf <span class=\"kw-clinique\">axillaire</span> ± plexus brachial</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-danger\">\n        <strong><span class=\"kw-alerte\">Urgence</span>.</strong> Une <strong>compression nerveuse</strong> doit être levée en urgence. Une <span class=\"kw-alerte\">ischémie aiguë de membre</span> impose une <span class=\"kw-ttt\">revascularisation</span> immédiate.</div>","frequence":0},{"id":"334-37","rang":"A","rubrique":"Examens complémentaires","titre":"Connaître les indications et savoir demander un examen d’imagerie devant un traumatisé des membres et/ou du bassin","contenu":"<table >\n        <thead><tr><th>Examen</th><th>Indication</th></tr></thead>\n        <tbody>\n          <tr><td><strong><span class=\"kw-imagerie\">Radiographies standards</span></strong></td><td><strong>2 incidences orthogonales</strong> visualisant <span class=\"kw-clinique\">les</span> <strong>articulations sus- et sous-jacentes</strong> (ex. fracture de jambe : jambe face + profil + genou + cheville).</td></tr>\n          <tr><td><strong><span class=\"kw-imagerie\">TDM corps entier injectée</span></strong></td><td>Si <span class=\"kw-alerte\">polyfracturé</span>, polytraumatisé, traumatisé du bassin (la FAST ne voit pas <span class=\"kw-clinique\">les</span> hémorragies rétropéritonéales du bassin).</td></tr>\n          <tr><td><span class=\"kw-imagerie\">TDM centrée</span></td><td>Préciser une <strong>fracture articulaire</strong>.</td></tr>\n          <tr><td><span class=\"kw-imagerie\">Écho-<span class=\"kw-imagerie\">doppler</span></span> / <span class=\"kw-imagerie\">angio-TDM</span> / <span class=\"kw-imagerie\">artériographie</span></td><td>Si <span class=\"kw-alerte\">atteinte artérielle</span> cliniquement suspectée.</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\">\n        <strong>Piège.</strong> L'<span class=\"kw-imagerie\">IRM</span> n'est <strong>pas indispensable en <span class=\"kw-alerte\">urgence</span></strong> pour un traumatisme des membres.</div>","frequence":0,"liens":[{"href":"https://radiopaedia.org/articles/lower-extremity-fractures","label":"Radiopaedia : Lower extremity fractures"},{"href":"https://radiopaedia.org/articles/pelvic-fractures","label":"Radiopaedia : Pelvic fractures"}]},{"id":"334-38","rang":"B","rubrique":"Examens complémentaires","titre":"Connaître la sémiologie radiologique de base des fractures diaphysaires simples des os longs","contenu":"<figure class=\"obj-figure\">\n        <img src=\"../assets/images/334/fracture-traits-schema.png\" alt=\"Schéma comparatif des types de traits de fracture des os longs : normale, transverse, oblique, spirale, comminutive, segmentaire, arrachement, bordée, protubérance, en bois vert\" loading=\"lazy\">\n        <figcaption>Principaux types de traits de fracture diaphysaire selon le mécanisme. Source : fiche source EDN item 334.</figcaption>\n      </figure>\n      <table >\n        <thead><tr><th>Trait</th><th>Description / mécanisme</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Transversal</strong></td><td>Perpendiculaire au grand axe de l'os — mécanisme de cisaillement.</td></tr>\n          <tr><td><strong>Oblique</strong></td><td>Angle aigu avec l'axe, sans torsion ; parfois 3ᵉ fragment en aile de papillon — flexion.</td></tr>\n          <tr><td><strong>Spiroïde</strong></td><td>Trait en spirale — mécanisme de torsion.</td></tr>\n          <tr><td><strong>Comminutif</strong></td><td><span class=\"kw-chiffre\">&gt; 3 fragments</span> — traumatisme à haute énergie.</td></tr>\n          <tr><td><strong>Bifocal</strong></td><td>2 traits indépendants isolant un fragment intermédiaire (à risque de dévascularisation).</td></tr>\n        </tbody>\n      </table>\n      <h4 style=\"margin:14px 0 6px;font-size:14px;\">Déplacement et stabilité</h4>\n      <p>Le déplacement (du segment distal) se décrit en <strong>angulation</strong> (varus/valgus, flexum/recurvatum), <strong>translation</strong> (→ chevauchement, raccourcissement) et <strong>rotation</strong> (décalage).</p>\n      <ul>\n        <li><strong>Potentiellement stables</strong> : fractures transversales, obliques courtes.</li>\n        <li><span class=\"kw-alerte\">Instables</span> : obliques longues, spiroïdes, bifocales, comminutives, à 3ᵉ fragment.</li>\n      </ul>","frequence":1},{"id":"334-39","rang":"B","rubrique":"Contenu multimédia","titre":"Identifier une fracture diaphysaire des os longs","contenu":"<p>Sur une <span class=\"kw-imagerie\">radiographie</span>, la fracture diaphysaire se reconnaît à l'interruption de la <strong>ligne corticale</strong> par un <span class=\"kw-radio\">trait clair</span>, avec analyse du <strong>déplacement</strong> des fragments.</p>\n      <figure class=\"obj-figure\">\n        <img src=\"../assets/images/334/fracture-spiroide-rx.png\" alt=\"Radiographie d'une fracture diaphysaire spiroïde d'un os long de l'enfant, le trait parcourant l'os en spirale\" loading=\"lazy\">\n        <figcaption><span class=\"kw-imagerie\">Radiographie</span> d'une fracture diaphysaire <strong>spiroïde</strong> (trait en spirale, mécanisme de torsion) — à ne pas confondre avec une fracture oblique. Source : fiche source EDN item 334.</figcaption>\n      </figure>\n      <ul>\n        <li>Rechercher l'interruption corticale sur <span class=\"kw-clinique\">les</span> <strong>2 incidences</strong> orthogonales.</li>\n        <li>Caractériser le trait (transversal, oblique, spiroïde, comminutif).</li>\n        <li>Décrire le déplacement : angulation, translation/chevauchement, rotation.</li>\n        <li>Vérifier <span class=\"kw-clinique\">les</span> articulations sus- et sous-jacentes.</li>\n      </ul>","frequence":2,"liens":[{"href":"https://radiopaedia.org/articles/spiral-fracture","label":"Radiopaedia : Spiral fracture"}]},{"id":"334-40","rang":"A","rubrique":"Examens complémentaires","titre":"Savoir rechercher des complications précoces","contenu":"<table >\n        <thead><tr><th>Complication</th><th>Reconnaître</th></tr></thead>\n        <tbody>\n          <tr><td><strong><span class=\"kw-alerte\">Syndrome des loges</span></strong></td><td><span class=\"kw-clinique\">Douleurs insomniantes</span> exacerbées à la palpation et à l'extension passive, <strong>résistantes aux <span class=\"kw-ttt\">antalgiques</span></strong> ; pouls longtemps <strong>conservés</strong>. Mesure des pressions : <span class=\"kw-chiffre\">&gt; 30 mmHg</span> ou ΔPAD &lt;<span class=\"kw-chiffre\"> 30 mmHg</span> → <strong>aponévrotomie en <span class=\"kw-alerte\">urgence</span></strong>.</td></tr>\n          <tr><td><strong><span class=\"kw-alerte\">Embolie graisseuse</span></strong></td><td>Intervalle libre (heures à<span class=\"kw-chiffre\"> 48 h</span>) ; <span class=\"kw-def\">triade de Gurd</span> : <span class=\"kw-alerte\">SDRA</span> + signes neuropsychiques + <span class=\"kw-clinique\">purpura pétéchial</span> (tronc, conjonctives, muqueuse buccale).</td></tr>\n          <tr><td><strong><span class=\"kw-alerte\">Rhabdomyolyse</span> (crush syndrome)</strong></td><td>Destruction myocytaire ; <span class=\"kw-bio\">CPK</span> élevées, <span class=\"kw-clinique\">myoglobinurie</span> (urines porto) ; risque d'<span class=\"kw-alerte\">insuffisance rénale aiguë</span> et d'<span class=\"kw-alerte\">hyperkaliémie</span>.</td></tr>\n          <tr><td><strong>Infectieuses</strong></td><td><span class=\"kw-etio\">Gangrène gazeuse</span> (<span class=\"kw-etio\">Clostridium</span>), germes pyogènes, <span class=\"kw-etio\">tétanos</span> (prévention SAT-VAT).</td></tr>\n        </tbody>\n      </table>\n      <figure class=\"obj-figure\">\n        <img src=\"../assets/images/334/embolie-graisseuse-petechies.png\" alt=\"Photographies cliniques de purpura pétéchial du tronc, du cou et de la muqueuse buccale chez un patient atteint d'un syndrome d'embolie graisseuse\" loading=\"lazy\">\n        <figcaption><span class=\"kw-def\">Purpura</span> pétéchial de l'embolie graisseuse : tronc, cou, conjonctives et muqueuse buccale. Source : fiche source EDN item 334.</figcaption>\n      </figure>\n      <div class=\"callout callout-info\">\n        <strong>À retenir.</strong> L'embolie graisseuse complique <span class=\"kw-chiffre\">&lt; 1 %</span> des fractures isolées d'os long mais jusqu'à <span class=\"kw-chiffre\">30 %</span> des fractures multiples (fémur + tibia) avec PEC retardée — d'où l'intérêt de l'immobilisation précoce.</div>","frequence":4,"liens":[{"href":"https://radiopaedia.org/articles/fat-embolism-syndrome","label":"Radiopaedia : Fat embolism syndrome"}]},{"id":"334-41","rang":"A","rubrique":"Prise en charge","titre":"Connaître des principes de prise en charge initiale d’une fracture","contenu":"<h4 style=\"margin:14px 0 6px;font-size:14px;\">Sur <span class=\"kw-clinique\">les</span> lieux</h4>\n      <ul>\n        <li>Stabilisation par une <strong>attelle</strong> pour calmer la douleur (participe à la PEC de l'<span class=\"kw-alerte\">état de choc</span>).</li>\n        <li>Pansement <strong>occlusif stérile</strong> sur <span class=\"kw-clinique\">les</span> plaies si fracture ouverte.</li>\n        <li>Fracture de la ceinture pelvienne : <span class=\"kw-ttt\">ceinture pelvienne</span> (<span class=\"kw-alerte\">risque vital</span> par hématome rétropéritonéal).</li>\n      </ul>\n      <h4 style=\"margin:14px 0 6px;font-size:14px;\">Aux urgences</h4>\n      <ul>\n        <li>Patient à jeun, VVP, <span class=\"kw-def\">bilan préopératoire</span>.</li>\n        <li>Antalgie : <span class=\"kw-ttt\">AINS</span> (efficaces en traumatologie), <span class=\"kw-ttt\">morphine</span>.</li>\n        <li><strong>Attelle plâtrée</strong> après <span class=\"kw-ttt\">réduction</span> si grand déplacement ou <span class=\"kw-alerte\">menace</span> cutanée.</li>\n        <li>Si ouverture cutanée : <strong>SAT-VAT</strong> + <span class=\"kw-ttt\">antibioprophylaxie</span> au plus tôt ; lavage abondant, antiseptique aqueux (<span class=\"kw-ci\">pas de solution alcoolique sur peau lésée</span>), pansement stérile.</li>\n      </ul>","frequence":0},{"id":"334-42","rang":"B","rubrique":"Prise en charge","titre":"Connaître les principes de prise en charge des fractures ouvertes et fermées","contenu":"<table >\n        <thead><tr><th>Traitement</th><th>Indications</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Orthopédique</strong> (immobilisation)</td><td>Fracture fermée (ou Gustilo 1 après parage) <strong>non déplacée et stable</strong> ; fracture comminutive non ostéosynthésable.</td></tr>\n          <tr><td><strong><span class=\"kw-ttt\">Ostéosynthèse</span> par <span class=\"kw-clinique\">plaque</span></strong></td><td>Fracture fermée ou Gustilo 1, déplacée et/ou instable.</td></tr>\n          <tr><td><strong>Enclouage centro-médullaire</strong></td><td>Fractures fermées ou Gustilo 1-2 (voire 3A avec couverture musculaire immédiate).</td></tr>\n          <tr><td><strong>Fixateur externe</strong></td><td>Contamination importante : Gustilo 2 vues tardivement, <span class=\"kw-alerte\">Gustilo 3B et 3C</span> ; contusion cutanée importante.</td></tr>\n        </tbody>\n      </table>\n      <h4 style=\"margin:14px 0 6px;font-size:14px;\">Spécificités de la fracture ouverte</h4>\n      <ul>\n        <li><strong>Parage chirurgical obl<span class=\"kw-chiffre\">iga</span>toire</strong> : excision des tissus dévitalisés, débridement, lavage abondant.</li>\n        <li>Fermeture cutanée <strong>sans tension</strong> (sinon <span class=\"kw-ttt\">lambeau</span> de couverture).</li>\n        <li><span class=\"kw-ttt\">Antibioprophylaxie</span> : <span class=\"kw-ttt\">céfazoline</span> (Gustilo 1) ; <span class=\"kw-ttt\">amoxicilline-acide clavulanique</span> (Gustilo 2-3).</li>\n      </ul>\n      <div class=\"callout callout-danger\">\n        <strong><span class=\"kw-alerte\">Urgence</span> thérapeutique.</strong> Le traitement d'une <span class=\"kw-alerte\">fracture ouverte</span> doit classiquement avoir lieu dans <span class=\"kw-clinique\">les</span> <span class=\"kw-chiffre\">6 heures</span>.</div>","frequence":3},{"id":"334-43","rang":"A","rubrique":"Prise en charge","titre":"Connaître les principes de prise en charge des principales complications des fractures","contenu":"<table >\n        <thead><tr><th>Complication</th><th>Prise en charge</th></tr></thead>\n        <tbody>\n          <tr><td><strong><span class=\"kw-alerte\">Syndrome des loges</span></strong></td><td><strong>Aponévrotomie en <span class=\"kw-alerte\">urgence</span></strong> (sans refermer la peau, pansement occlusif, fermeture progressive à 5-7 j sinon greffe).</td></tr>\n          <tr><td><strong><span class=\"kw-alerte\">Rhabdomyolyse</span></strong></td><td>Réhydratation agressive (<span class=\"kw-chiffre\">500 mL/h</span>), <span class=\"kw-ttt\">alcalinisation des urines</span> (<span class=\"kw-bio\">pH</span> &gt; 6) ; traitement de l'<span class=\"kw-alerte\">hyperkaliémie</span> ; <span class=\"kw-ttt\">épuration extra-rénale</span> si hyperkaliémie menaçante, acidose réfractaire ou <span class=\"kw-clinique\">anurie</span>.</td></tr>\n          <tr><td><strong><span class=\"kw-alerte\">Embolie graisseuse</span></strong></td><td><strong>Prévention</strong> : immobilisation précoce et complète, lutte contre l'hypovolémie. Traitement curatif purement symptomatique (O₂, VM si <span class=\"kw-alerte\">SDRA</span>).</td></tr>\n          <tr><td><strong>MTEV</strong></td><td>Prévention systématique si <span class=\"kw-clinique\">lésion</span> du membre inférieur, du rachis ou polytraumatisme.</td></tr>\n          <tr><td><strong>Raideur post-traumatique</strong></td><td>Rééducation ; mobilisation sous AG ; arthrolyse à partir du 3ᵉ mois.</td></tr>\n          <tr><td><strong><span class=\"kw-alerte\">Pseudarthrose</span> / cal vicieux</strong></td><td><span class=\"kw-ttt\">Reprise chirurgicale</span> : décortication, greffe osseuse.</td></tr>\n        </tbody>\n      </table>","frequence":1},{"id":"334-44","rang":"A","rubrique":"Définition","titre":"Connaître la définition de la fracture du rachis et de l’atteinte médullaire associée","contenu":"<p>La <strong><span class=\"kw-def\">stabilité du rachis</span></strong> est sa capacité à maintenir des rapports anatomiques normaux entre vertèbres. Une fracture est <strong><span class=\"kw-alerte\">instable</span></strong> lorsqu'elle expose à une <span class=\"kw-clinique\">lésion</span> neurologique secondaire en cas de déplacement.</p>\n      <table >\n        <thead><tr><th>Lésion instable</th><th>Caractéristiques</th></tr></thead>\n        <tbody>\n          <tr><td>Disco-l<span class=\"kw-chiffre\">iga</span>mentaire pure</td><td><span class=\"kw-alerte\">Rupture</span> des moyens d'union (segment mobile rachidien) : <span class=\"kw-def\">entorse grave</span>, luxation. Surtout cervicale.</td></tr>\n          <tr><td>Osseuse pure</td><td>Atteinte du <strong>segment vertébral moyen</strong> (mur postérieur, pédicules, articulaires postérieures). Jonction thoraco-lombaire.</td></tr>\n          <tr><td>Caractéristiques</td><td><span class=\"kw-def\">Burst fracture</span> (éclatement comminutif du corps) ; <span class=\"kw-def\">tear drop</span> (fracture du corps + <span class=\"kw-alerte\">rupture</span> complète du SMR).</td></tr>\n        </tbody>\n      </table>\n      <h4 style=\"margin:14px 0 6px;font-size:14px;\">Atteinte médullaire = somme de <span class=\"kw-chiffre\"<span class=\"kw-chiffre\">>2</span> l</span>ésions</h4>\n      <table >\n        <thead><tr><th><span class=\"kw-clinique\">Lésion</span></th><th>Caractéristiques</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Primaire</strong></td><td>Mécanique, au moment du traumatisme. <span class=\"kw-alerte\">Inaccessible au traitement</span>. Écrasement/étirement plutôt que section complète.</td></tr>\n          <tr><td><strong>Secondaire</strong> (<span class=\"kw-def\">AMSOS</span>)</td><td>Agressions médullaires secondaires d'origine systémique : ischémie/<span class=\"kw-clinique\">nécrose</span> dans <span class=\"kw-clinique\">les</span> heures-jours suivants. <strong>Seules ces lésions sont accessibles à la PEC</strong> (maintien de la PA et de l'oxygénation).</td></tr>\n        </tbody>\n      </table>","frequence":1},{"id":"334-45","rang":"B","rubrique":"Eléments physiopathologiques","titre":"Connaître les conséquences hémodynamiques et ventilatoires de l’atteinte médullaire selon le niveau lésionnel","contenu":"<p>Le niveau de l'atteinte est désigné par le <strong>dernier myélomère fonctionnel</strong>. Une atteinte au-dessus de <span class=\"kw-chiffre\">T1</span> donne une <span class=\"kw-alerte\">tétraplégie</span>, en dessous une <span class=\"kw-alerte\">paraplégie</span>.</p>\n      <table >\n        <thead><tr><th>Niveau</th><th>Conséquences</th></tr></thead>\n        <tbody>\n          <tr><td><strong>&gt; T6</strong> (atteinte haute) — hémodynamique</td><td><span class=\"kw-alerte\">Choc neurogénique</span> : vasoplégie sous-lésionnelle (chute de PAS) + <span class=\"kw-clinique\">bradycardie</span> (surtout si cervicale) → risque d'<span class=\"kw-alerte\">arrêt cardiaque</span>. <span class=\"kw-clinique\">Hypotension</span> orthostatique.</td></tr>\n          <tr><td><strong>C1-<span class=\"kw-bio\">C3</span></strong> — ventilatoire</td><td>Atteinte des <strong>muscles respiratoires</strong> → <span class=\"kw-alerte\">hypoventilation majeure</span>.</td></tr>\n          <tr><td><strong><span class=\"kw-bio\">C3</span>-C4</strong> — ventilatoire</td><td>Paralysie <strong>phrénique</strong> : <span class=\"kw-clinique\">hoquet</span>, paralysie d'un hémidiaphragme.</td></tr>\n          <tr><td><strong>&lt; <span class=\"kw-bio\">C4</span></strong> (jusqu'à T6-L1)</td><td>Atteinte des muscles intercostaux et abdominaux → baisse de l'efficacité de la <span class=\"kw-clinique\">toux</span> → <span class=\"kw-clinique\">encombrement bronchique</span>, pneumopathies.</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\">\n        <strong>À retenir.</strong> Facteurs prédictifs d'autonomie ventilatoire à vérifier en préhospitalier : <span class=\"kw-clinique\">toux</span> efficace, ampliation thoracique correcte, capacité à compter jusqu'à 10 à voix haute.</div>","frequence":1},{"id":"334-46","rang":"A","rubrique":"Diagnostic positif","titre":"Circonstances, signes fonctionnels et physiques, savoir effectuer un examen neurologique complet et renseigner l’échelle ASIA","contenu":"<p>L'examen neurologique doit être <strong>complet, daté et consigné par écrit</strong> : motricité des 4 membres, motricité périnéale (contraction anale au TR), sensibilité (niveau métamérique), ROT, réflexes bulbo-caverneux et clitorido-anal. Rechercher un <span class=\"kw-alerte\">priapisme</span> (atteinte médullaire de mauvais <span class=\"kw-def\">pronostic</span>).</p>\n      <h4 style=\"margin:14px 0 6px;font-size:14px;\">Cotation <span class=\"kw-def\">MRC</span> de la force (0 à 5)</h4>\n      <ul>\n        <li><span class=\"kw-chiffre\">0</span> : aucune contraction · <span class=\"kw-chiffre\">1</span> : contraction visible sans déplacement · <span class=\"kw-chiffre\">2</span> : mouvement sans <span class=\"kw-clinique\">pesanteur</span></li>\n        <li><span class=\"kw-chiffre\">3</span> : contre <span class=\"kw-clinique\">pesanteur</span> · <span class=\"kw-chiffre\">4</span> : contre résistance · <span class=\"kw-chiffre\">5</span> : force normale</li>\n      </ul>\n      <h4 style=\"margin:14px 0 6px;font-size:14px;\"><span class=\"kw-def\">Score</span> ASIA / grade AIS</h4>\n      <p>Le <strong><span class=\"kw-def\">score ASIA</span></strong> est l'observation standardisée internationale : <span class=\"kw-def\">score</span> moteur (10 fonctions clés × 2 côtés), scores sensitifs (28 dermatomes, piqûre + tact). Le grade <span class=\"kw-def\">AIS</span> quantifie le caractère incomplet (analyse des segments sacrés S4-S5) :</p>\n      <table >\n        <thead><tr><th><span class=\"kw-def\">Grade</span></th><th>Description</th></tr></thead>\n        <tbody>\n          <tr><td><strong>A</strong></td><td>Atteinte <span class=\"kw-alerte\">complète</span> : aucune fonction motrice ni sensitive en S4-S5.</td></tr>\n          <tr><td><strong>B</strong></td><td>Sensibilité préservée en S4-S5, motricité abolie.</td></tr>\n          <tr><td><strong>C</strong></td><td>Motricité incomplète, force résiduelle non fonctionnelle (&lt;<span class=\"kw-chiffre\"> 50 %</span> des muscles clés à <span class=\"kw-chiffre\">≥ 3</span>).</td></tr>\n          <tr><td><strong>D</strong></td><td>Motricité préservée, <span class=\"kw-chiffre\">≥ 50 %</span> des muscles clés à <span class=\"kw-chiffre\">≥ 3</span> — marche souvent possible.</td></tr>\n          <tr><td><strong>E</strong></td><td>Fonctions sensitives et motrices normales.</td></tr>\n        </tbody>\n      </table>","frequence":2},{"id":"334-47","rang":"A","rubrique":"Identifier une urgence","titre":"Connaître les symptômes devant faire suspecter une lésion médullaire","contenu":"<p>Suspecter une <span class=\"kw-clinique\">lésion</span> médullaire devant un <strong><span class=\"kw-clinique\">syndrome rachidien</span></strong> (douleur spontanée/provoquée à la palpation des épineuses, raideur, déformation) et/ou un <strong><span class=\"kw-clinique\">syndrome lésionnel ou sous-lésionnel</span></strong> (<span class=\"kw-clinique\">déficit moteur</span>, sensitif, troubles sphinctériens).</p>\n      <h4 style=\"margin:14px 0 6px;font-size:14px;\"><span class=\"kw-alerte\">Choc</span> spinal (interruption médullaire complète)</h4>\n      <ul>\n        <li><strong>1ᵉʳ temps</strong> — <span class=\"kw-alerte\">choc</span> spinal : <span class=\"kw-clinique\">paralysie flasque</span> sous-lésionnelle, anesthésie à tous <span class=\"kw-clinique\">les</span> modes, abolition des ROT, <span class=\"kw-alerte\">rétention aiguë d'urine</span>.</li>\n        <li>Éléments de mauvais <span class=\"kw-def\">pronostic</span> : <span class=\"kw-alerte\">atonie du sphincter anal</span>, <span class=\"kw-alerte\">priapisme</span>, disparition du réflexe bulbo-caverneux — d'où l'importance de l'examen périnéal et du TR.</li>\n        <li><strong>2ᵉ temps</strong> — automatisme médullaire (jours-semaines) : <span class=\"kw-def\">syndrome pyramidal</span>, ROT vifs, réflexe de triple retrait.</li>\n      </ul>\n      <div class=\"callout callout-danger\">\n        <strong><span class=\"kw-alerte\">Urgence</span>.</strong> Tout déficit neurologique, surtout <strong>incomplet et évolutif</strong>, impose une imagerie et un avis chirurgical en urgence immédiate.</div>","frequence":0},{"id":"334-48","rang":"A","rubrique":"Prise en charge","titre":"Connaître les indications et les modalités des principes d’immobilisation","contenu":"<p>L'immobilisation concerne <strong>tout traumatisé du rachis et tout polytraumatisé</strong>, sur <span class=\"kw-clinique\">les</span> lieux et pendant tout le transport. L'absence de déficit neurologique initial <strong>n'exclut pas</strong> une <span class=\"kw-clinique\">lésion</span> instable.</p>\n      <h4 style=\"margin:14px 0 6px;font-size:14px;\">Modalités</h4>\n      <ul>\n        <li><strong>Collier / minerve cervicale rigide</strong> systématique (tout traumatisé crânien est un traumatisé du rachis jusqu'à preuve du contraire).</li>\n        <li>Maintien de la <strong>rectitude tête-cou-tronc</strong>, sans traction axiale.</li>\n        <li><strong>Mobilisation en bloc</strong> : 4 personnes minimum, plan dur, <span class=\"kw-ttt\">matelas à dépression</span> (matelas-coquille).</li>\n        <li>Ceinture de contention pelvienne au moindre doute sur un traumatisme pelvien.</li>\n      </ul>\n      <div class=\"callout callout-info\">\n        <strong>À retenir.</strong> L'immobilisation est maintenue jusqu'à l'interprétation du <span class=\"kw-imagerie\">TDM rachidien</span> par le radiologue.</div>","frequence":0},{"id":"334-49","rang":"A","rubrique":"Examens complémentaires","titre":"Connaître les indications d’imagerie devant un traumatisé du rachis ou vertébro-médullaire","contenu":"<table >\n        <thead><tr><th>Examen</th><th>Place et indications</th></tr></thead>\n        <tbody>\n          <tr><td><strong><span class=\"kw-imagerie\">TDM</span></strong></td><td>Examen de <strong>référence</strong>, <strong>systématique</strong> chez le traumatisé sévère. Excellente pour le trait de fracture et la sténose canalaire.</td></tr>\n          <tr><td><strong><span class=\"kw-imagerie\">IRM</span></strong></td><td>Indiquée si : <span class=\"kw-alerte\">déficit neurologique non expliqué par le TDM</span> ; suspicion d'atteinte <strong>disco-l<span class=\"kw-chiffre\">iga</span>mentaire</strong>. Seule à visualiser la moelle épinière, <span class=\"kw-clinique\">les</span> ligaments, l'hématome épidural.</td></tr>\n          <tr><td><span class=\"kw-imagerie\">Radiographies</span></td><td>Utiles si <span class=\"kw-imagerie\">TDM</span>/<span class=\"kw-imagerie\">IRM</span> inaccessibles, ou trauma à faible cinétique sans signe neurologique.</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\">\n        <strong>Piège.</strong> <span class=\"kw-clinique\">Les</span> <strong>clichés dynamiques</strong> (hyperflexion/hyperextension) ne sont <span class=\"kw-ci\">pas indiqués en urgence</span> pour un traumatisme cervical : ils recherchent une instabilité disco-l<span class=\"kw-chiffre\">iga</span>mentaire à distance (8-10 j), une fois la contracture musculaire levée.</div>","frequence":0,"liens":[{"href":"https://radiopaedia.org/articles/vertebra","label":"Radiopaedia : Vertebra"},{"href":"https://radiopaedia.org/articles/spinal-fractures","label":"Radiopaedia : Spinal fractures"}]},{"id":"334-50","rang":"B","rubrique":"Prise en charge","titre":"Connaître les principes de prise en charge des traumatismes du rachis","contenu":"<h4 style=\"margin:14px 0 6px;font-size:14px;\">Traitement de la fracture</h4>\n      <table >\n        <thead><tr><th>Traitement</th><th>Indications</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Fonctionnel</strong></td><td>Fracture stable sans risque de déformation (apophyse transverse/épineuse) : repos, <span class=\"kw-ttt\">antalgiques</span>, kinésithérapie.</td></tr>\n          <tr><td><strong>Orthopédique</strong></td><td><span class=\"kw-clinique\">Lésion</span> osseuse sans danger neurologique : contention rigide.</td></tr>\n          <tr><td><strong>Chirurgical</strong></td><td><span class=\"kw-alerte\">Déficit neurologique</span> ; <span class=\"kw-clinique\">lésion</span> instable à risque ; déformation importante (cyphose &gt; 15°). Objectifs : décompression, <span class=\"kw-ttt\">réduction</span>, stabilisation (ostéosynthèse + greffe).</td></tr>\n        </tbody>\n      </table>\n      <h4 style=\"margin:14px 0 6px;font-size:14px;\">Mesures générales</h4>\n      <ul>\n        <li><strong>Prévention des AMSOS</strong> : contrôle glycémique, bonne PA (remplissage ± vasopresseur), bonne oxygénation.</li>\n        <li>Sondage vésical si troubles sphinctériens.</li>\n      </ul>\n      <div class=\"callout callout-danger\">\n        <strong>Piège classique.</strong> <span class=\"kw-ci\">Aucune indication des corticoïdes</span> dans le traumatisme médullaire (majoration du risque <span class=\"kw-etio\">infectieux</span> et thromboembolique). Priorité aux lésions à <span class=\"kw-alerte\">pronostic vital</span> chez le polytraumatisé.</div>","frequence":0},{"id":"334-51","rang":"B","rubrique":"Définition","titre":"Connaître la définition d’un traumatisé crânien léger, modéré et grave","contenu":"<p>La gravité du <strong><span class=\"kw-def\">traumatisme crânien</span></strong> (TC) se définit par le <strong><span class=\"kw-def\">score de Glasgow</span></strong> (GCS), évalué après stabilisation des fonctions vitales.</p>\n      <table >\n        <thead><tr><th>Gravité</th><th><span class=\"kw-def\">Score de <span class=\"kw-def\">Glasgow</span></span></th></tr></thead>\n        <tbody>\n          <tr><td><strong>TC léger</strong></td><td>GCS <span class=\"kw-chiffre\">13 à 15</span></td></tr>\n          <tr><td><strong>TC modéré</strong></td><td>GCS <span class=\"kw-chiffre\">9 à 12</span></td></tr>\n          <tr><td><strong><span class=\"kw-alerte\">TC grave</span></strong></td><td>GCS <span class=\"kw-chiffre\">≤ 8</span> — complété par le <span class=\"kw-def\">score de Liège</span></td></tr>\n        </tbody>\n      </table>\n      <p>Le <span class=\"kw-def\">score de <span class=\"kw-def\">Glasgow</span></span> cote la réponse <strong>oculaire</strong> (Y/4), <strong>verbale</strong> (V/5) et <strong>motrice</strong> (M/6), soit un total sur <span class=\"kw-chiffre\">15</span>. En cas d'<span class=\"kw-clinique\">asymétrie</span>, on retient la <strong>meilleure réponse motrice</strong> et la réponse oculaire du côté déficitaire.</p>\n      <div class=\"callout callout-info\">\n        <strong>À retenir.</strong> <span class=\"kw-clinique\">Les</span> TC représentent <span class=\"kw-chiffre\">70 %</span> des décès par AVP et la 1ʳᵉ cause de décès chez les moins de <span class=\"kw-chiffre\">35 ans</span>.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 299 — Tumeur intracranienne</em></p>","frequence":1},{"id":"334-52","rang":"B","rubrique":"Eléments physiopathologiques","titre":"Connaître les principes physiopathologiques des lésions cérébrales traumatiques","contenu":"<p>Principe central : <strong><span class=\"kw-def\">PPC = PAM − PIC</span></strong> (pression de perfusion cérébrale = pression artérielle moyenne − pression intracrânienne). La PPC doit être <span class=\"kw-chiffre\">&gt; 70 mmHg</span> ; sa chute entraîne une <span class=\"kw-alerte\">ischémie cérébrale</span>.</p>\n      <h4 style=\"margin:14px 0 6px;font-size:14px;\">Lésions primaires <span class=\"kw-bio\">vs</span> secondaires</h4>\n      <ul>\n        <li><strong>Lésions primaires</strong> : mécaniques, au moment de l'impact (étirement-cisaillement à l'interface substance blanche/grise → <span class=\"kw-alerte\">lésions axonales diffuses</span> ; contusions par coup/contrecoup).</li>\n        <li><strong>Lésions secondaires</strong> : retardées (heures-jours), liées aux <span class=\"kw-def\">ACSOS</span> — agressions cérébrales secondaires d'origine systémique — <strong>à prévenir</strong>.</li>\n      </ul>\n      <h4 style=\"margin:14px 0 6px;font-size:14px;\">ACSOS à corriger</h4>\n      <p><span class=\"kw-alerte\">Hypotension</span>/<span class=\"kw-def\">HTA</span>, <span class=\"kw-alerte\">hypoxémie</span>, <span class=\"kw-alerte\">hypercapnie</span>, hypo/hyperglycémie, hypo/<span class=\"kw-clinique\">hyperthermie</span>, anémie.</p>\n      <div class=\"callout callout-warn\">\n        <strong>Piège.</strong> La <span class=\"kw-alerte\">PIC</span> reflète 3 volumes (encéphale, <span class=\"kw-bio\">LCS</span>, sang). Une PIC <span class=\"kw-chiffre\">&gt; 20 mmHg</span> définit l'<span class=\"kw-alerte\">HTIC</span> ; elle augmente avec l'hypercapnie, l'acidose, l'agitation, la douleur, l'<span class=\"kw-clinique\">hyperthermie</span>.</div>","frequence":1},{"id":"334-53","rang":"A","rubrique":"Diagnostic positif","titre":"Savoir suspecter et diagnostiquer un traumatisme crânien","contenu":"<p>Le diagnostic repose sur un <strong>examen neurologique complet, daté et consigné</strong> :</p>\n      <ul>\n        <li><span class=\"kw-clinique\">Score de Glasgow</span> ; examen des pupilles (<span class=\"kw-alerte\">anisocorie</span>, réactivité).</li>\n        <li>Examen complet du <strong>cuir chevelu</strong> : plaie, <span class=\"kw-alerte\">hémorragie active</span>, fuite de <span class=\"kw-bio\">LCS</span>.</li>\n        <li><span class=\"kw-clinique\">Déformation crânienne</span> (embarrure) ; <span class=\"kw-clinique\">rhinorrhée</span>/<span class=\"kw-clinique\">otorrhée</span> claire (brèche ostéo-méningée).</li>\n        <li>Testing sensitivo-moteur ; examen des nerfs crâniens.</li>\n        <li>Recherche de <strong>signes de localisation</strong> et de <strong>signes d'engagement</strong>.</li>\n      </ul>\n      <div class=\"callout callout-warn\">\n        <strong>Piège.</strong> Une <span class=\"kw-clinique\">otorragie</span>, une <span class=\"kw-clinique\">rhinorrhée</span> ou des <span class=\"kw-clinique\">ecchymoses</span> péri-orbitaires/mastoïdiennes doivent faire évoquer une <span class=\"kw-alerte\">fracture de la base du crâne</span>.</div>","frequence":1},{"id":"334-54","rang":"A","rubrique":"Identifier une urgence","titre":"Identifier le traumatisé crânien grave","contenu":"<p>Le <strong><span class=\"kw-alerte\">TC grave</span></strong> est défini par un <span class=\"kw-def\">score de <span class=\"kw-def\">Glasgow</span></span> <span class=\"kw-chiffre\">≤ 8</span>. Il impose une <strong><span class=\"kw-ttt\">intubation</span> + ventilation mécanique</strong> et une prise en charge en <span class=\"kw-alerte\">réanimation</span>.</p>\n      <h4 style=\"margin:14px 0 6px;font-size:14px;\"><span class=\"kw-alerte\">Signes de gravité</span> associés</h4>\n      <ul>\n        <li><strong>Signes de localisation</strong> : <span class=\"kw-clinique\">asymétrie</span> faciale, <span class=\"kw-clinique\">déficit moteur</span> d'un hémicorps.</li>\n        <li><strong>Signes d'engagement</strong> : <span class=\"kw-alerte\">mydriase unilatérale aréactive</span> (engagement temporal), décortication/décérébration, désintégration rostro-caudale des réflexes du tronc.</li>\n      </ul>\n      <h4 style=\"margin:14px 0 6px;font-size:14px;\"><span class=\"kw-def\">Score</span> de Liège</h4>\n      <p>Le <span class=\"kw-def\">score de Liège</span> explore <span class=\"kw-clinique\">les</span> réflexes du tronc cérébral dans le sens cranio-caudal : fronto-orbiculaire (5) → oculocéphalique vertical (4) → photomoteur (3) → oculocéphalique horizontal (2) → oculo-cardiaque (1) → tous absents (0). La disparition du dernier réflexe (oculo-cardiaque) signe la <span class=\"kw-alerte\">mort encéphalique</span>.</p>\n      <div class=\"callout callout-warn\">\n        <strong>Piège.</strong> Le réflexe oculocéphalogyre ne se recherche qu'<strong>après un <span class=\"kw-imagerie\">TDM</span> du rachis cervical</strong> éliminant une <span class=\"kw-clinique\">lésion</span> instable.</div>","frequence":0},{"id":"334-55","rang":"A","rubrique":"Identifier une urgence","titre":"Identifier le traumatisé crânien nécessitant une évaluation spécialisée","contenu":"<p>La <strong><span class=\"kw-def\">classification de Masters</span></strong> stratifie le risque de <span class=\"kw-clinique\">lésion</span> intracrânienne et guide l'indication d'imagerie/<span class=\"kw-alerte\">hospitalisation</span> :</p>\n      <table >\n        <thead><tr><th>Groupe</th><th>Profil</th><th>Conduite</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Groupe 1 — faible risque</strong></td><td><span class=\"kw-def\">Glasgow</span> 15, asymptomatique ou <span class=\"kw-clinique\">céphalées</span> régressives, <span class=\"kw-clinique\">vertiges</span>.</td><td>Pas de <span class=\"kw-imagerie\">TDM</span> systématique. <span class=\"kw-def\">Surveillance</span>, éducation, RAD si entourage fiable.</td></tr>\n          <tr><td><strong>Groupe 2 — risque modéré</strong></td><td><span class=\"kw-def\">Glasgow</span> 14-15 ; <span class=\"kw-clinique\">amnésie</span> ou PC initiale ; <span class=\"kw-clinique\">vomissements</span>, <span class=\"kw-clinique\">céphalées</span> croissantes, intoxication, trouble de coagulation, polytraumatisme, plaie pénétrante, âge &gt;<span class=\"kw-chiffre\"> 65 ans</span>, enfant &lt;<span class=\"kw-chiffre\"> 2 ans</span>.</td><td><span class=\"kw-imagerie\">TDM</span> ; <span class=\"kw-alerte\">hospitalisation</span> <span class=\"kw-chiffre\">24-48 h</span> pour <span class=\"kw-def\">surveillance</span>.</td></tr>\n          <tr><td><strong>Groupe 3 — risque élevé</strong></td><td><span class=\"kw-def\">Glasgow</span> <span class=\"kw-chiffre\">≤ 13</span> ; <span class=\"kw-alerte\">signes de focalisation</span> ; brèche ostéo-méningée, embarrure.</td><td><span class=\"kw-imagerie\">TDM en urgence</span> ; transfert vers un centre spécialisé (neurochirurgie).</td></tr>\n        </tbody>\n      </table>","frequence":0},{"id":"334-56","rang":"A","rubrique":"Examens complémentaires","titre":"Savoir demander à bon escient l’examen d’imagerie pertinent devant un traumatisme crânien à la phase aiguë","contenu":"<ul>\n        <li>La <strong><span class=\"kw-imagerie\">TDM cérébrale sans injection</span></strong> est l'examen de <strong>référence</strong> pour tout traumatisé crânien devant bénéficier d'une imagerie (selon la <span class=\"kw-def\">classification</span> de Masters).</li>\n        <li>En pratique, on réalise une <strong><span class=\"kw-imagerie\">TDM corps entier avec coupes osseuses</span></strong> chez le traumatisé sévère.</li>\n        <li><span class=\"kw-imagerie\">Angio-TDM</span> si recherche de lésions vasculaires associées (<span class=\"kw-etio\">dissection</span>) ou évaluation de la perfusion cérébrale.</li>\n        <li><span class=\"kw-imagerie\">TDM du rachis cervical</span> au moindre doute (tout traumatisé crânien est un traumatisé du rachis cervical jusqu'à preuve du contraire).</li>\n      </ul>\n      <div class=\"callout callout-warn\">\n        <strong>Piège.</strong> <span class=\"kw-clinique\">Les</span> <span class=\"kw-alerte\">lésions axonales diffuses</span> sont souvent <strong>non visibles sur le <span class=\"kw-imagerie\">TDM</span> initial</strong> → une <span class=\"kw-imagerie\">IRM</span> à distance peut être nécessaire devant un <span class=\"kw-clinique\">coma</span> sans <span class=\"kw-clinique\">lésion</span> <span class=\"kw-imagerie\">TDM</span> expliquant le tableau.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 335 — Trauma maxillo-faciale</em></p>","frequence":2,"liens":[{"href":"https://radiopaedia.org/articles/temporal-bone-fracture-1","label":"Radiopaedia : Temporal bone fracture 1"},{"href":"https://radiopaedia.org/cases/skull-fracture-infant","label":"Radiopaedia : Skull fracture infant"}]},{"id":"334-57","rang":"B","rubrique":"Contenu multimédia","titre":"Tomodensitométrie d’hématome extra-dural, sous-dural et contusions cérébrales","contenu":"<p><span class=\"kw-clinique\">Les</span> <strong>complications hémorragiques précoces</strong> du TC se distinguent sur la <span class=\"kw-imagerie\">TDM cérébrale</span> par leur forme, leur topographie et leur cinétique :</p>\n      <table >\n        <thead><tr><th><span class=\"kw-clinique\">Lésion</span></th><th>Mécanisme</th><th>Clinique</th><th>Aspect <span class=\"kw-imagerie\">TDM</span></th><th>Traitement</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong><span class=\"kw-alerte\">Hématome extra-dural</span> (HED)</strong></td>\n            <td>Saignement <strong>artériel</strong> (artère méningée moyenne) entre l'os et la dure-mère. <span class=\"kw-def\">Mortalité</span><span class=\"kw-chiffre\"> 5-10 %</span>.</td>\n            <td>Séquence classique en <strong>3 temps</strong> : PC initiale → <span class=\"kw-clinique\">intervalle libre</span> → aggravation rapide avec <span class=\"kw-alerte\">mydriase homolatérale</span> (engagement temporal).</td>\n            <td><span class=\"kw-radio\">Hyperdensité spontanée en lentille biconvexe</span> juxta-osseuse ; effet de <span class=\"kw-clinique\">masse</span>.</td>\n            <td><strong><span class=\"kw-alerte\">Urgence neurochirurgicale vitale</span></strong>.</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-alerte\">Hématome sous-dural</span> (HSD) aigu</strong></td>\n            <td>Saignement <strong>veineux</strong> le plus souvent. <span class=\"kw-def\">Mortalité</span> élevée (<span class=\"kw-chiffre\">40-90 %</span>).</td>\n            <td>Troubles de conscience fréquents et précoces, <strong>sans intervalle libre</strong> ; signes de localisation.</td>\n            <td><span class=\"kw-radio\">Hyperdensité spontanée en croissant</span> moulant la convexité de l'hémisphère.</td>\n            <td><span class=\"kw-ttt\">Chirurgie</span> à discuter si épaisseur <span class=\"kw-chiffre\">&gt; 5 mm</span>.</td>\n          </tr>\n          <tr>\n            <td><strong>Contusion / hématome intracérébral</strong></td>\n            <td><span class=\"kw-clinique\">Lésion</span> de coup/contrecoup du parenchyme.</td>\n            <td><span class=\"kw-alerte\">Lésions évolutives</span> → <span class=\"kw-def\">surveillance</span> clinique et <span class=\"kw-imagerie\">TDM</span>.</td>\n            <td>Foyers hyperdenses intraparenchymateux ; aggravation à la <strong><span class=\"kw-imagerie\">TDM</span> H+48</strong> (extension de l'<span class=\"kw-clinique\">œdème</span>).</td>\n            <td>Médical ; <span class=\"kw-ttt\">chirurgie</span> selon le retentissement.</td>\n          </tr>\n        </tbody>\n      </table>\n      <p>À distinguer de l'<strong>hémorragie sous-arachnoïdienne</strong> traumatique : <span class=\"kw-radio\">hyperdensité spontanée des espaces sous-arachnoïdiens</span> de la convexité — toujours se demander si elle n'est pas la cause inaugurale du <span class=\"kw-clinique\">malaise</span> ayant conduit au TC.</p>\n      <figure class=\"obj-figure\">\n        <img src=\"../assets/images/334/tdm-hematome-extradural-sous-dural.png\" alt=\"TDM cérébrale sans injection : hématome extra-dural droit en lentille biconvexe et hématome sous-dural droit en croissant, avec effet de masse\" loading=\"lazy\">\n        <figcaption><span class=\"kw-alerte\">HED</span> = <span class=\"kw-radio\">lentille biconvexe</span> juxta-osseuse (décollement de la dure-mère, ne franchit pas <span class=\"kw-clinique\">les</span> sutures). <span class=\"kw-alerte\">HSD</span> = <span class=\"kw-radio\">croissant</span> moulant la convexité (franchit les sutures). Effet de <span class=\"kw-clinique\">masse</span> : effacement des sillons + déviation de la ligne médiane. Source : banque iconographique officielle EDN (« Imagerie à connaître »).</figcaption>\n      </figure>","frequence":7},{"id":"334-58","rang":"B","rubrique":"Prise en charge","titre":"Connaître les principes de prise en charge des traumatisés crâniens","contenu":"<table >\n        <thead><tr><th>Situation</th><th>Prise en charge</th></tr></thead>\n        <tbody>\n          <tr><td><strong><span class=\"kw-clinique\">Lésion</span> d'emblée chirurgicale</strong></td><td><span class=\"kw-alerte\">HED</span>, HSD, hématome intracérébral, embarrure sévère, plaie crânio-cérébrale, hydrocéphalie aiguë → <strong>bloc opératoire en <span class=\"kw-alerte\">urgence</span></strong> ; pose d'un capteur de <span class=\"kw-def\">PIC</span>.</td></tr>\n          <tr><td><strong>Pas de <span class=\"kw-clinique\">lésion</span> chirurgicale</strong></td><td><span class=\"kw-alerte\">Hospitalisation</span> en réanimation ; monitorage <strong>invasif</strong> de la PIC si <span class=\"kw-def\">Glasgow</span> <span class=\"kw-chiffre\">≤ 8.</span></td></tr>\n        </tbody>\n      </table>\n      <h4 style=\"margin:14px 0 6px;font-size:14px;\">Mesures du TC grave</h4>\n      <ul>\n        <li><span class=\"kw-ttt\">Intubation</span> + <span class=\"kw-ttt\">ventilation mécanique</span> ; antalgie ; correction des troubles de l'hémostase.</li>\n        <li>Tête proclive 30°, rachis cervical aligné.</li>\n        <li><span class=\"kw-ci\">Pas de prophylaxie antiépileptique systématique</span> ; DVE si hydrocéphalie aiguë.</li>\n      </ul>\n      <h4 style=\"margin:14px 0 6px;font-size:14px;\">Lutte contre <span class=\"kw-clinique\">les</span> ACSOS — cibles</h4>\n      <ul>\n        <li><span class=\"kw-bio\">SpO₂</span> <span class=\"kw-chiffre\">≥ 90 %</span> avec normocapnie (<span class=\"kw-chiffre\">35-38 mmHg</span>) ; <span class=\"kw-clinique\">PAM</span> &gt;<span class=\"kw-chiffre\"> 90 mmHg</span>, normovolémie.</li>\n        <li><span class=\"kw-bio\">Glycémie</span><span class=\"kw-chiffre\"> 6-9 mmol/L</span> ; température <span class=\"kw-chiffre\">35-37 °C</span> ; <span class=\"kw-bio\">Hb</span> &gt;<span class=\"kw-chiffre\"> 9 g/dL</span>.</li>\n        <li><span class=\"kw-def\">PPC</span> &gt;<span class=\"kw-chiffre\"> 70 mmHg</span>, PIC la plus proche de la normale.</li>\n      </ul>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 299 — Tumeur intracranienne · 105 — Epilepsie · 135 — <span class=\"kw-ttt\">Antalgique</span></em></p>","frequence":3}],"astuces":[],"strategie":{"urgence":"<p><strong>Degré :</strong> <span class=\"kw-alerte\">urgence vitale immédiate</span> ; <span class=\"kw-def\">mortalité</span> précoce par <span class=\"kw-etio\">hémorragie</span> et <span class=\"kw-etio\">traumatisme crânien</span><br><strong>Fenêtre :</strong> <span class=\"kw-def\">golden hour</span> ; transport &lt; <span class=\"kw-chiffre\">90 min</span> ; <span class=\"kw-imagerie\">TDM corps entier</span> &lt; <span class=\"kw-chiffre\">45 min</span> si critique (jusqu'à <span class=\"kw-chiffre\">90 min</span> si stable) ; <span class=\"kw-ttt\">fracture ouverte</span> opérée &lt; <span class=\"kw-chiffre\">6 h</span><br><strong>1er geste :</strong> contrôle de toute <span class=\"kw-alerte\">hémorragie</span> (compression, <span class=\"kw-ttt\">ceinture pelvienne</span>, <span class=\"kw-ttt\">garrot</span>, suture du scalp) puis bilan <span class=\"kw-def\">ABCDE</span></p>","hospit":"<p><strong>Ambulatoire :</strong> <span class=\"kw-def\">surveillance</span> à domicile écrite réservée au <span class=\"kw-etio\">TC léger</span> de l'enfant à risque faible (entourage fiable)<br><strong>Hospit :</strong> tout <span class=\"kw-alerte\">traumatisé sévère</span> orienté d'emblée vers un <span class=\"kw-ttt\">trauma center</span> (<span class=\"kw-def\">algorithme de Vittel</span>) ; <span class=\"kw-alerte\">brûlure grave</span> vers un <span class=\"kw-ttt\">centre de traitement des brûlés</span><br><strong>Réa :</strong> <span class=\"kw-alerte\">détresse vitale</span>, <span class=\"kw-alerte\">TC grave</span> (<span class=\"kw-chiffre\">Glasgow ≤ 8</span>), atteinte médullaire haute (&gt; T6), <span class=\"kw-alerte\">choc hémorragique</span></p>","redflags":"<ul><li><strong>Signes vitaux :</strong> <span class=\"kw-chiffre\">Glasgow &lt; 13</span>, <span class=\"kw-chiffre\">PAS &lt; 90 mmHg</span> ou <span class=\"kw-chiffre\">SpO2 &lt; 90 %</span> ; gravité extrême : <span class=\"kw-chiffre\">Glasgow 3</span>, <span class=\"kw-chiffre\">PAS &lt; 65 mmHg</span>, <span class=\"kw-chiffre\">SpO2 &lt; 80 %</span> ou imprenable</li><li><strong>Cinétique violente :</strong> éjection ou projection/écrasement, <span class=\"kw-clinique\">chute &gt; 6 m</span>, autre passager décédé, blast (explosion)</li><li><strong>Lésions :</strong> <span class=\"kw-etio\">plaie pénétrante</span> (tête, cou, thorax, abdomen, bassin), <span class=\"kw-alerte\">volet thoracique</span>, instabilité du bassin, suspicion d'<span class=\"kw-alerte\">atteinte médullaire</span>, amputation, <span class=\"kw-alerte\">ischémie aiguë de membre</span>, brûlure sévère + inhalation de fumées</li><li><strong>Suppléance :</strong> ventilation assistée, <span class=\"kw-ttt\">remplissage &gt; 1 L</span>, catécholamines</li><li><strong><span class=\"kw-def\">Terrain</span> :</strong> <span class=\"kw-clinique\">âge &gt; 65 ans</span>, <span class=\"kw-ci\">insuffisance cardiaque</span>/coronaire/respiratoire, grossesse (2e-3e trimestre), <span class=\"kw-ci\">antithrombotique</span> ou trouble de la crase</li></ul>","principes":"<p><strong>Fil conducteur :</strong> <span class=\"kw-def\">damage control</span> — stopper l'<span class=\"kw-alerte\">hémorragie</span> avant toute réparation anatomique, dès le préhospitalier</p><p><strong>Pré-hospitalier — damage control resuscitation</strong></p><p>Orientation vers le trauma center, transport &lt;<span class=\"kw-chiffre\"> 90 min</span></p><ul><li>Contrôle de toute <span class=\"kw-alerte\">hémorragie</span> extériorisée (compression, suture du scalp) ; exsufflation d'un <span class=\"kw-alerte\">PNO sous tension</span></li><li>2 <span class=\"kw-ttt\">VVP</span> de gros calibre (<span class=\"kw-chiffre\"<span class=\"kw-chiffre\">>16</span>G</span>), monitorage, dextro, Hémocue, <span class=\"kw-bio\">lactatémie</span></li><li><span class=\"kw-ttt\">O2</span> pour <span class=\"kw-bio\">SpO2</span> &gt;<span class=\"kw-chiffre\"> 95 %</span> ; <span class=\"kw-ttt\">IOT en séquence rapide</span> si <span class=\"kw-chiffre\">Glasgow ≤ 8</span>, <span class=\"kw-alerte\">détresse</span> respiratoire ou hémodynamique</li><li><span class=\"kw-ttt\">Remplissage par cristalloïdes</span> ± <span class=\"kw-ttt\">noradrénaline</span> (objectif PAS &gt;<span class=\"kw-chiffre\"> 90 mmHg</span>) ; <span class=\"kw-ttt\">acide tranexamique</span><span class=\"kw-chiffre\"> 1 g</span> sur <span class=\"kw-chiffre\">10 min</span></li><li>Immobilisation rachidienne (minerve rigide, matelas coquille, mobilisation en bloc) ; <span class=\"kw-ttt\">couverture de survie</span> (<span class=\"kw-clinique\">hypothermie</span>)</li></ul><p><strong><span class=\"kw-alerte\">Réanimation</span> du <span class=\"kw-alerte\">choc</span> <span class=\"kw-etio\">hémorragique</span></strong></p><p>Lutter contre la triade léthale <span class=\"kw-alerte\">hypothermie – acidose – coagulopathie</span></p><ul><li><span class=\"kw-bio\">PAM</span> cible <span class=\"kw-chiffre\">60-65 mmHg</span> (sans neurotrauma) ou <span class=\"kw-chiffre\">75-85 mmHg</span> si TC grave associé</li><li>Seuils : <span class=\"kw-bio\">Hb</span> &gt; <span class=\"kw-chiffre\">7 g/dL</span>, <span class=\"kw-bio\">plaquettes</span> &gt; <span class=\"kw-chiffre\">50 G/L</span>, <span class=\"kw-bio\">TP</span> &gt; <span class=\"kw-chiffre\">40 %</span> (respectivement <span class=\"kw-chiffre\">10 g/dL</span>, <span class=\"kw-chiffre\"<span class=\"kw-chiffre\">>100</span> G/L</span>,<span class=\"kw-chiffre\"> 60 %</span> si neurotrauma)</li><li><span class=\"kw-ttt\">PFC</span> + <span class=\"kw-ttt\">CGR</span> ratio 1/1 à 1/2 ; <span class=\"kw-ttt\">concentrés plaquettaires</span> 1/4 ; <span class=\"kw-ttt\">fibrinogène</span> &gt;<span class=\"kw-chiffre\"> 1,5-2 g/L</span> ; <span class=\"kw-ttt\">calcium IV</span></li><li>Hémostase chirurgicale ou <span class=\"kw-ttt\">embolisation</span> sans délai (<span class=\"kw-ci\">ne jamais</span> retarder l'hémostase)</li></ul><p><strong>Brûlé grave</strong></p><p><span class=\"kw-def\">Contact</span> systématique avec un centre de traitement des brûlés</p><ul><li>Surface : <span class=\"kw-def\">règle des 9 de Wallace</span> (2e et 3e degrés uniquement) ; <span class=\"kw-alerte\">brûlure grave</span> si SCB &gt; <span class=\"kw-chiffre\">10 %</span></li><li>Remplissage : <span class=\"kw-ttt\">cristalloïdes (Ringer lactate)</span><span class=\"kw-chiffre\"> 20 mL</span>/kg sur la 1re heure si SCB &gt;<span class=\"kw-chiffre\"> 10 %</span>, puis <span class=\"kw-def\">formule de Parkland</span><span class=\"kw-chiffre\"> 4 mL</span>/kg/%SCB</li><li>Local : <span class=\"kw-ttt\">sulfadiazine d'argent</span> (Flammazine) ; prévention antitétanique ; <span class=\"kw-ci\">pas d'ATB systématique</span></li><li><span class=\"kw-alerte\">Inhalation de fumées</span> : <span class=\"kw-ttt\">O2</span><span class=\"kw-chiffre\"> 15 L</span>/min, <span class=\"kw-ttt\">hydroxocobalamine</span> si suspicion de <span class=\"kw-etio\">cyanure</span> ; <span class=\"kw-ttt\">incision de décharge</span> si brûlure circulaire profonde</li></ul><p><strong>Fracture ouverte / des membres</strong></p><ul><li><span class=\"kw-ttt\">Antibioprophylaxie</span> selon <span class=\"kw-def\">Gustilo</span> : <span class=\"kw-ttt\">céfazoline</span> (<span class=\"kw-def\">stade</span> 1) ou <span class=\"kw-ttt\">amoxicilline-acide clavulanique</span> (<span class=\"kw-chiffre\">stade 2</span>-3) ; <span class=\"kw-ttt\">SAT-VAT</span></li><li>Lavage abondant + parage, <span class=\"kw-ci\">pas de solution alcoolique</span> sur peau lésée ; immobilisation par attelle ; <span class=\"kw-ttt\">chirurgie</span> &lt; <span class=\"kw-chiffre\">6 h</span></li><li>Rechercher complications : <span class=\"kw-alerte\">ischémie</span> (<span class=\"kw-clinique\">asymétrie des pouls</span>), atteinte neurologique, <span class=\"kw-alerte\">syndrome des loges</span></li></ul><p><strong>Rachis & atteinte médullaire</strong></p><ul><li>Immobilisation stricte (rectitude crânio-rachidienne) jusqu'à interprétation du <span class=\"kw-imagerie\">TDM</span> rachidien</li><li>Prévention des <span class=\"kw-def\">AMSOS</span> : <span class=\"kw-ttt\">PA</span> correcte (remplissage ± vasopresseur), oxygénation, contrôle glycémique</li><li>Examen <span class=\"kw-def\">ASIA</span> / <span class=\"kw-def\">grade</span> AIS ; <span class=\"kw-ttt\">chirurgie</span> en <span class=\"kw-alerte\">urgence</span> si déficit neurologique incomplet et évolutif</li><li>Atteinte &gt; T6 : <span class=\"kw-alerte\">choc neurogénique</span> (vasoplégie + <span class=\"kw-clinique\">bradycardie</span>) ; &gt; <span class=\"kw-bio\">C4</span> : hypoventilation</li></ul><p><strong>Traumatisme crânien</strong></p><ul><li><span class=\"kw-alerte\">TC grave</span> = <span class=\"kw-chiffre\">Glasgow ≤ 8</span> : <span class=\"kw-ttt\">décubitus 30°</span> tête dans l'axe, <span class=\"kw-ttt\">IOT</span>, PAM <span class=\"kw-chiffre\">75-85 mmHg</span>, <span class=\"kw-ttt\">osmothérapie (mannitol)</span> si <span class=\"kw-alerte\">HTIC</span></li><li><span class=\"kw-imagerie\">TDM cérébrale sans injection</span> en <span class=\"kw-alerte\">urgence</span> (<span class=\"kw-etio\">HED</span>, <span class=\"kw-etio\">HSD</span>, contusions)</li><li>Enfant — <span class=\"kw-etio\">TC léger</span> (<span class=\"kw-chiffre\">Glasgow</span> 13-15) : risque faible (<span class=\"kw-def\">surveillance</span> domicile) / intermédiaire / élevé (<span class=\"kw-imagerie\">TDM</span> + <span class=\"kw-alerte\">hospitalisation</span>)</li></ul>","suivi":"<p><strong>Complications précoces :</strong> <span class=\"kw-alerte\">triade hypothermie–acidose–coagulopathie</span>, <span class=\"kw-etio\">embolie graisseuse</span> (intervalle libre, triade de Gurd), <span class=\"kw-etio\">rhabdomyolyse</span> / crush syndrome, <span class=\"kw-etio\">syndrome du compartiment abdominal</span> (PIA &gt;<span class=\"kw-chiffre\"> 20 mmHg</span>), <span class=\"kw-etio\">SDRA</span><br><strong>Prévention :</strong> <span class=\"kw-ttt\">MTEV</span> (compression pneumatique puis <span class=\"kw-ttt\">héparine</span> à distance de l'hémorragie), <span class=\"kw-ttt\">nutrition entérale précoce</span>, matelas anti-escarres<br><strong><span class=\"kw-def\">Surveillance</span> :</strong> clinique, <span class=\"kw-ttt\">biologique</span> et scannographique en <span class=\"kw-ttt\">USC / réanimation</span> ; <span class=\"kw-imagerie\">RX</span> de contrôle des fractures ; séquelles (rééducation, <span class=\"kw-etio\">syndrome de stress post-traumatique</span>)</p>"},"liensGlobaux":[{"href":"https://www.ce-mir.fr/sites/www.ce-mir.fr/files/medias/documents/57.%20Traumatismes%20s%C3%A9v%C3%A8res_0.pdf","label":"CeMIR — 57. traumatismes sévères 0"},{"href":"https://www.pedia-univ.fr/deuxieme-cycle/referentiel/urgences-reanimation-chirurgie-orthopedique/traumatismes","label":"Pedia-univ — Traumatismes"},{"href":"https://campus.neurochirurgie.fr/article1787.html","label":"Collège — Article1787"},{"href":"https://www.ce-mir.fr/sites/www.ce-mir.fr/files/medias/documents/58.%20Br%C3%BBlures.pdf","label":"CeMIR — 58. brûlures"},{"href":"https://www.brulure.fr/generalites/differents-degres/","label":"Differents degres"},{"href":"https://www.youtube.com/watch?v=c9-Wn_66QIo","label":"https://www.youtube.com/watch?v=c9-Wn_66QIo"},{"href":"https://sofia.medicalistes.fr/spip/IMG/pdf/Le_syndrome_embolie_graisseuse.pdf","label":"Le syndrome embolie graisseuse"},{"href":"https://fr.wikipedia.org/wiki/Classification_de_Gustilo_pour_les_fractures_ouvertes","label":"Wikipedia — Classification de gustilo pour les fractures ouvertes"},{"href":"https://campus.neurochirurgie.fr/article1714.html","label":"Collège — Article1714"},{"href":"https://asia-spinalinjury.org/wp-content/uploads/2019/01/ASIA-ISNCSCI-Final-French-Version-Jan-2019.pdf","label":"Asia isncsci final french version jan 2019"},{"href":"https://radiopaedia.org/articles/trauma","label":"Radiopaedia : Trauma (généralités)"},{"href":"https://radiopaedia.org/articles/fracture-1","label":"Radiopaedia : Fractures (généralités)"}],"arbre":{"rootId":"root","nodes":[{"id":"root","kind":"root","label":"Traumatisé sévère au déchocage — Détresses vitales évaluées et traitées en ABCDE","detail":"<h4>CAT — Traumatisé sévère à l'arrivée à l'hôpital — Stratégie d'hémostase selon le statut hémodynamique (damage control)</h4>","branches":[{"to":"q-hemo","label":"Détresses vitales traitées (ABCDE)","color":"blue"}]},{"id":"q-hemo","kind":"decision","label":"État hémodynamique ? — PAS, réponse au remplissage ± noradrénaline","branches":[{"to":"q-extreme","label":"Instable : PAS &lt; 90 mmHg malgré la réanimation","color":"red"},{"to":"q-tdm","label":"Stable ou stabilisé : PAS &gt; 90 mmHg","color":"green"}]},{"id":"q-extreme","kind":"decision","label":"Instabilité extrême / patient moribond ? — Choc réfractaire à la réanimation initiale","branches":[{"to":"t-moribond","label":"Oui (a fortiori plaie pénétrante)","color":"red"},{"to":"q-source","label":"Non — bilan lésionnel sur brancard","color":"red"}]},{"id":"t-moribond","kind":"terminal","label":"Bloc opératoire d'emblée","color":"red","detail":"<h4>Conduite</h4><ul><li>Transfert direct au <span class=\"kw-ttt\">bloc opératoire</span> en <span class=\"kw-alerte\">urgence</span> (instabilité hémodynamique extrême)</li><li><span class=\"kw-imagerie\">TDM corps entier</span> différée, réalisée si possible dans un 2nd temps</li></ul><h4>Pourquoi</h4><ul><li>Sous-évaluation des lésions au <span class=\"kw-imagerie\">TDM</span> sur <span class=\"kw-clinique\">les</span> traumatismes pénétrants ; le geste d'hémostase ne doit pas être retardé</li></ul>"},{"id":"q-source","kind":"decision","label":"Bilan sur brancard (FAST + RX bassin + RXT) : origine de l'hémorragie ? — Pas de TDM injectée en urgence chez l'instable","branches":[{"to":"t-lapa","label":"FAST + : hémopéritoine","color":"red"},{"to":"t-pelvis","label":"Fracas du bassin + FAST négative","color":"red"},{"to":"t-thorax","label":"Hémothorax ou PNO compressif","color":"red"}]},{"id":"t-lapa","kind":"terminal","label":"Laparotomie d'hémostase (damage control)","color":"red","detail":"<h4>Conduite</h4><ul><li><span class=\"kw-ttt\">Laparotomie écourtée</span> (incision xypho-pubienne) : localiser et stopper le saignement</li><li><span class=\"kw-ttt\">Splénectomie d'hémostase</span>, <span class=\"kw-ttt\">packing hépatique</span> ou <span class=\"kw-ttt\">clampage</span> selon l'organe</li><li>Fermeture cutanée exclusive ou <span class=\"kw-ttt\">laparostome</span> → 2nd look chirurgical à<span class=\"kw-chiffre\"> 24-48 h</span></li></ul><h4>Principe</h4><ul><li><span class=\"kw-def\">Damage control surgery</span> : restauration physiologique avant réparation anatomique</li></ul>"},{"id":"t-pelvis","kind":"terminal","label":"Ceinture pelvienne + artério-embolisation","color":"red","detail":"<h4>Conduite</h4><ul><li><span class=\"kw-ttt\">Ceinture de contention pelvienne</span> posée au niveau des trochanters fémoraux</li><li><span class=\"kw-ttt\">Artério-embolisation</span> (saignement artériel) ou <span class=\"kw-ttt\">fixateur externe / clamp de bassin</span> (saignement veineux)</li></ul><h4>Pièges</h4><ul><li>Suspectée devant : <span class=\"kw-alerte\">choc</span> + fracas du bassin + <span class=\"kw-radio\">FAST négative</span> (hémorragie rétropéritonéale non vue en écho)</li><li><span class=\"kw-ci\">Sondage vésical interdit</span> avant interprétation du <span class=\"kw-imagerie\">TDM</span> (risque de <span class=\"kw-clinique\">lésion</span> urétrale)</li></ul>"},{"id":"t-thorax","kind":"terminal","label":"Drainage thoracique ± thoracotomie d'hémostase","color":"red","detail":"<h4>Conduite</h4><ul><li>PNO compressif : <span class=\"kw-ttt\">exsufflation</span> immédiate puis <span class=\"kw-ttt\">drainage thoracique</span></li><li>Hémothorax : <span class=\"kw-ttt\">drainage</span> ; <span class=\"kw-ttt\">thoracotomie d'hémostase</span> si &gt; <span class=\"kw-chiffre\">1500 mL</span> d'emblée ou débit &gt; <span class=\"kw-chiffre\">200 mL/h</span></li></ul>"},{"id":"q-tdm","kind":"decision","label":"TDM corps entier injecté : fuite active (blush) de PDC ? — Délai &lt; 45 min si critique, jusqu'à 90 min si stable","branches":[{"to":"t-embol","label":"Blush artériel/veineux +","color":"amber"},{"to":"t-conserv","label":"Pas de fuite active","color":"green"}]},{"id":"t-embol","kind":"terminal","label":"Artério-embolisation","color":"amber","detail":"<h4>Conduite</h4><ul><li><span class=\"kw-ttt\">Artério-embolisation</span> du foyer <span class=\"kw-etio\">hémorragique</span> (radiologie interventionnelle)</li><li>Réservée au patient stable ou stabilisé</li></ul><h4>Confirmation</h4><ul><li><span class=\"kw-radio\">Fuite (blush) artérielle et/ou veineuse de produit de contraste</span> au <span class=\"kw-imagerie\">TDM injecté</span></li></ul>"},{"id":"t-conserv","kind":"terminal","label":"Traitement non opératoire + surveillance","color":"green","detail":"<h4>Conduite</h4><ul><li>Attitude non opératoire quel que soit l'organe atteint tant que la stabilité est maintenue</li><li><span class=\"kw-ttt\">Surveillance</span> clinique, <span class=\"kw-ttt\">biologique</span> et scannographique en <span class=\"kw-ttt\">USC / réanimation</span> (milieu chirurgical)</li></ul><h4><span class=\"kw-ttt\">Chirurgie</span> si</h4><ul><li><span class=\"kw-ttt\">Laparotomie</span> si <span class=\"kw-clinique\">lésion</span> d'organe creux (<span class=\"kw-radio\">pneumopéritoine</span>) ou désinsertion mésentérique suspectée</li></ul>"}]},"cards":[{"i":"0e9dc0926378","n":334,"o":"334-1","u":"Définition","t":"Savoir définir un traumatisé sévère","q":"Comment définit-on un traumatisé sévère en médecine d'urgence ?","a":"<p>Un traumatisé sévère est un blessé dont la <strong>violence</strong> ou le <strong>mécanisme du traumatisme</strong> peuvent entraîner des lésions menaçant le pronostic vital, ou dont le mécanisme suggère l'existence potentielle de telles lésions. C'est une <strong>définition a priori</strong>, essentielle pour l'orientation rapide vers un trauma center.</p>"},{"i":"74abe449e7d3","n":334,"o":"334-1","u":"Définition","t":"Savoir définir un traumatisé sévère","q":"Pourquoi la distinction entre traumatisé sévère et polytraumatisé est-elle cruciale en situation d'urgence ?","a":"<p>La distinction est cruciale car l'objectif en urgence est d'identifier et d'orienter le <strong>traumatisé sévère</strong> le plus tôt possible vers un <strong>trauma center</strong>, sans attendre le bilan lésionnel exhaustif. La définition du polytraumatisé, étant rétrospective, ne permet pas cette prise en charge précoce et adaptée à l'urgence.</p>"},{"i":"9906cc858133","n":334,"o":"334-1","u":"Définition","t":"Savoir définir un traumatisé sévère","q":"Quelle est la distinction entre un \"traumatisé sévère\" et un \"polytraumatisé\" ?","a":"<ul><li>Le <strong>traumatisé sévère</strong> est une définition a priori basée sur le mécanisme du traumatisme et la suspicion de lésions vitales, permettant une orientation précoce.</li><li>Le <strong>polytraumatisé</strong> est défini rétrospectivement comme un traumatisé présentant <strong>au moins deux lésions dont au moins une menace le pronostic vital</strong>. Cette définition intervient après un bilan lésionnel exhaustif (par exemple, un body-TDM).</li></ul>"},{"i":"107675701a92","n":334,"o":"334-10","u":"Définition","t":"Connaître la définition d’une brûlure et de sa profondeur","q":"Qu'est-ce qui définit une carbonisation ?","a":"<p>La <strong>carbonisation</strong> est définie par l'atteinte des <strong>plans sous-jacents</strong> à la peau, tels que le muscle, le tendon et l'os.</p>"},{"i":"262df5e299d1","n":334,"o":"334-10","u":"Définition","t":"Connaître la définition d’une brûlure et de sa profondeur","q":"Comment se manifeste une brûlure du 2ᵉ degré profond et quelle est son évolution ?","a":"<p>Une brûlure du 2ᵉ degré profond atteint le <strong>derme profond</strong> avec destruction de la membrane basale. Elle présente une <strong>phlyctène</strong> sur un <strong>fond pâle</strong>, est <strong>peu douloureuse</strong>, et la <strong>vitropression est négative</strong>. La guérison est <strong>cicatricielle</strong> (en <strong>21 à 35 jours</strong>) avec des séquelles.</p>"},{"i":"38f367381cfe","n":334,"o":"334-10","u":"Définition","t":"Connaître la définition d’une brûlure et de sa profondeur","q":"Comment la profondeur d'une brûlure est-elle déterminée ?","a":"<p>La profondeur d'une brûlure est déterminée par deux facteurs principaux : la <strong>température</strong> de l'agent causal et la <strong>durée d'exposition</strong>.</p>"},{"i":"53e38adaeab2","n":334,"o":"334-10","u":"Définition","t":"Connaître la définition d’une brûlure et de sa profondeur","q":"Quel est le piège diagnostique concernant la profondeur des brûlures ?","a":"<p>Avant le <strong>15ᵉ jour</strong>, il est souvent <strong>difficile de distinguer</strong> cliniquement une brûlure du 2ᵉ degré profond d'une brûlure du 3ᵉ degré.</p>"},{"i":"7da7adb24442","n":334,"o":"334-10","u":"Définition","t":"Connaître la définition d’une brûlure et de sa profondeur","q":"Décrivez les caractéristiques d'une brûlure du 3ᵉ degré et son traitement.","a":"<p>Une brûlure du 3ᵉ degré implique une <strong>destruction totale de la peau</strong>. Elle se présente comme une <strong>nécrose blanche, brune ou noire</strong>, la peau est <strong>cartonnée</strong> et <strong>insensible</strong>, et il n'y a <strong>pas de phlyctène</strong>. La guérison spontanée est impossible et nécessite une <strong>greffe de peau</strong>.</p>"},{"i":"bb1ded48a80a","n":334,"o":"334-10","u":"Définition","t":"Connaître la définition d’une brûlure et de sa profondeur","q":"Quelles sont les caractéristiques cliniques et évolutives d'une brûlure du 1ᵉʳ degré ?","a":"<p>Une brûlure du 1ᵉʳ degré atteint purement l'<strong>intra-épiderme</strong>. Elle se manifeste par un <strong>érythème douloureux</strong> (comme un coup de soleil), sans décollement cutané. La cicatrisation est <strong>sans séquelle</strong> en <strong>3 à 7 jours</strong>.</p>"},{"i":"c1b3aae07564","n":334,"o":"334-10","u":"Définition","t":"Connaître la définition d’une brûlure et de sa profondeur","q":"Quelles sont les caractéristiques cliniques et le pronostic d'une brûlure du 2ᵉ degré superficiel ?","a":"<p>Une brûlure du 2ᵉ degré superficiel atteint le <strong>derme papillaire</strong>, avec respect de la membrane basale. Cliniquement, on retrouve une <strong>phlyctène</strong> sur un <strong>fond rouge</strong>, la brûlure est <strong>très douloureuse</strong>, et la <strong>vitropression est positive</strong>. La guérison se fait <strong>sans cicatrice</strong>, en <strong>10 à 14 jours</strong>.</p>"},{"i":"d5ad656781c5","n":334,"o":"334-10","u":"Définition","t":"Connaître la définition d’une brûlure et de sa profondeur","q":"Quels sont les mécanismes étiologiques des brûlures, et quel est le plus fréquent ?","a":"<p>Les mécanismes étiologiques des brûlures sont : <ul><li><strong>Thermique</strong> (majoritaire, environ 90 %, par liquides chauds, flammes, solides chauds)</li><li><strong>Électrique</strong></li><li><strong>Chimique</strong></li><li><strong>Mécanique</strong></li><li><strong>Radique</strong></li></ul><p>Le mécanisme thermique est le plus fréquent.</p>"},{"i":"f19740e72f73","n":334,"o":"334-10","u":"Définition","t":"Connaître la définition d’une brûlure et de sa profondeur","q":"Quelle est la définition générale d'une brûlure ?","a":"<p>Une brûlure est une <strong>destruction traumatique</strong> de la peau et des tissus sous-jacents, causée par un processus <strong>thermique</strong> (le plus fréquent), <strong>électrique</strong>, <strong>chimique</strong>, <strong>mécanique</strong> ou <strong>radique</strong>.</p>"},{"i":"2caa215c122b","n":334,"o":"334-14","u":"Diagnostic positif","t":"Savoir diagnostiquer une brûlure et la surface brûlée","q":"Comment la Règle des 9 de Wallace est-elle appliquée pour estimer la Surface Cutanée Brûlée (SCB) chez l'adulte ?","a":"<p>Chez l'adulte, la Règle des 9 de Wallace estime la SCB ainsi :</p><ul><li>Tête + cou = <strong>9 %</strong></li><li>Chaque membre supérieur = <strong>9 %</strong></li><li>Tronc antérieur = <strong>18 %</strong></li><li>Tronc postérieur = <strong>18 %</strong></li><li>Chaque membre inférieur = <strong>18 %</strong></li><li>Périnée = <strong>1 %</strong></li></ul>"},{"i":"30b0e4588e18","n":334,"o":"334-14","u":"Diagnostic positif","t":"Savoir diagnostiquer une brûlure et la surface brûlée","q":"Quelle est la particularité de l'utilisation de la Règle des 9 de Wallace chez l'enfant par rapport à l'adulte ?","a":"<p>Chez l'enfant, la Règle des 9 de Wallace est adaptée en raison d'une proportion corporelle différente :</p><ul><li>La tête est plus volumineuse et représente <strong>18 %</strong> (au lieu de 9 % chez l'adulte).</li><li>Chaque membre inférieur représente <strong>14 %</strong> (au lieu de 18 % chez l'adulte).</li></ul>"},{"i":"53ea8b6c0054","n":334,"o":"334-14","u":"Diagnostic positif","t":"Savoir diagnostiquer une brûlure et la surface brûlée","q":"Quelle est la signification d'une brûlure atteignant plus de 10 % de la surface cutanée totale ?","a":"<p>Toute brûlure atteignant <strong>> 10 % de la surface cutanée totale</strong> est considérée comme <strong>grave</strong> et implique une corrélation significative entre la SCB, les besoins volémiques et la mortalité.</p>"},{"i":"8e191f6445e7","n":334,"o":"334-14","u":"Diagnostic positif","t":"Savoir diagnostiquer une brûlure et la surface brûlée","q":"Dans quel cas la méthode de la « paume de la main » est-elle utile pour estimer la Surface Cutanée Brûlée (SCB) ?","a":"<p>La méthode de la « paume de la main » est utile pour estimer la SCB dans le cas de <strong>lésions en mosaïque</strong>.</p><p>Elle considère que la face palmaire de la main du patient (paume + doigts) représente approximativement <strong>1 %</strong> de la surface corporelle totale.</p>"},{"i":"a4eb4f291a93","n":334,"o":"334-14","u":"Diagnostic positif","t":"Savoir diagnostiquer une brûlure et la surface brûlée","q":"Quels sont les degrés de brûlure à prendre en compte pour évaluer la Surface Cutanée Brûlée (SCB) et quel est le piège à éviter ?","a":"<p>Seules les brûlures du <strong>2<sup>e</sup> et du 3<sup>e</sup> degré</strong> sont comptabilisées dans la Surface Cutanée Brûlée (SCB).</p><p>Le piège à éviter est de ne <strong>jamais inclure les brûlures du 1<sup>er</sup> degré</strong> dans le calcul de la SCB.</p>"},{"i":"a8c258cea72a","n":334,"o":"334-14","u":"Diagnostic positif","t":"Savoir diagnostiquer une brûlure et la surface brûlée","q":"Comment est réalisé le diagnostic initial et l'évaluation clinique d'une brûlure ?","a":"<p>Le diagnostic des brûlures est <strong>clinique</strong> et repose sur :</p><ul><li>Un <strong>déshabillage complet</strong> du patient.</li><li>La réalisation d'un <strong>schéma daté et signé</strong>.</li><li>La prise de <strong>photographies</strong>.</li></ul>"},{"i":"15f5f4cd0f9a","n":334,"o":"334-15","u":"Contenu multimédia","t":"Identifier une brûlure superficielle et une brûlure profonde","q":"Quelle est la principale différence de pronostic et de stratégie thérapeutique entre une brûlure superficielle et une brûlure profonde ?","a":"<p>Les brûlures superficielles (1er et 2e degré superficiel) cicatrisent <strong>spontanément</strong> et sans séquelles. Les brûlures profondes (2e degré profond et 3e degré) nécessitent souvent une <strong>greffe de peau</strong> et entraînent des <strong>séquelles</strong> (cicatrices).</p>"},{"i":"cca141a09b80","n":334,"o":"334-15","u":"Contenu multimédia","t":"Identifier une brûlure superficielle et une brûlure profonde","q":"Quels sont les signes cliniques distinctifs d'une brûlure du 2e degré superficiel ?","a":"<p>Une brûlure du 2e degré superficiel se caractérise par :</p><ul><li>Un <strong>fond rouge</strong> à l'inspection.</li><li>Une <strong>vitropression positive</strong> (la rougeur disparaît temporairement à la pression et se recolore).</li><li>Elle est généralement <strong>très douloureuse</strong>.</li><li>Les phanères restent <strong>adhérents</strong>.</li></ul>"},{"i":"cf029db82d89","n":334,"o":"334-15","u":"Contenu multimédia","t":"Identifier une brûlure superficielle et une brûlure profonde","q":"Quels sont les signes cliniques permettant d'identifier une brûlure profonde (2e degré profond et 3e degré) ?","a":"<p>Les signes cliniques d'une brûlure profonde incluent :</p><ul><li>Un <strong>fond pâle</strong>, voire cartonné pour le 3e degré.</li><li>Une <strong>vitropression négative</strong> (pas de blanchiment à la pression).</li><li>La douleur est <strong>peu douloureuse à indolore</strong>, surtout pour le 3e degré, en raison de la destruction des terminaisons nerveuses.</li><li>Les phanères sont <strong>non adhérents</strong> au 3e degré.</li></ul>"},{"i":"dc0b35e6f72b","n":334,"o":"334-15","u":"Contenu multimédia","t":"Identifier une brûlure superficielle et une brûlure profonde","q":"Comment les brûlures sont-elles classées selon leur profondeur et quelles structures cutanées sont atteintes ?","a":"<p>Les brûlures sont classées comme suit :</p><ul><li><strong>1er degré</strong> : atteinte de l'<strong>épiderme</strong>.</li><li><strong>2e degré superficiel</strong> : atteinte de l'<strong>épiderme</strong> et de la partie superficielle du <strong>derme</strong>.</li><li><strong>2e degré profond</strong> : atteinte de l'<strong>épiderme</strong> et de la partie profonde du <strong>derme</strong>.</li><li><strong>3e degré</strong> : destruction complète de l'<strong>épiderme</strong> et du <strong>derme</strong>.</li></ul>"},{"i":"0cc2e8ce1ac5","n":334,"o":"334-16","u":"Identifier une urgence","t":"Savoir reconnaître les signes de gravité d’une brûlure chez l’adulte et l’enfant","q":"Quels sont les seuils de surface corporelle brûlée (SCB) indiquant une brûlure grave chez l'adulte et l'enfant ?","a":"<p>Les seuils de surface corporelle brûlée (SCB) indiquant une brûlure grave sont :</p><ul><li>Chez l'adulte : <strong>> 20 % de SCB au 2ᵉ degré</strong> ou <strong>> 5 % de SCB au 3ᵉ degré</strong>.</li><li>Chez l'enfant : <strong>> 10 % de SCB au 2ᵉ degré</strong> ou <strong>> 5 % de SCB au 3ᵉ degré</strong>.</li></ul>"},{"i":"2f141d18d723","n":334,"o":"334-16","u":"Identifier une urgence","t":"Savoir reconnaître les signes de gravité d’une brûlure chez l’adulte et l’enfant","q":"Quel est le \"piège pédiatrique\" à connaître concernant les brûlures chez l'enfant ?","a":"<p>Le \"piège pédiatrique\" est que les <strong>seuils de gravité de surface brûlée sont plus bas chez l'enfant</strong> que chez l'adulte. En effet, environ <strong>60 % des brûlures sont considérées comme graves chez l'enfant de moins de 4 ans</strong>.</p>"},{"i":"3a4b49dbe1ca","n":334,"o":"334-16","u":"Identifier une urgence","t":"Savoir reconnaître les signes de gravité d’une brûlure chez l’adulte et l’enfant","q":"Quelles sont les localisations de brûlure qui définissent la gravité indépendamment de la surface brûlée ?","a":"<p>Les localisations de brûlure qui définissent la gravité sont au niveau des <strong>zones fonctionnelles</strong> :</p><ul><li>La <strong>face</strong>.</li><li>Les <strong>voies aériennes</strong>.</li><li>Les <strong>mains</strong>.</li><li>Le <strong>périnée</strong>.</li><li>Les <strong>plis de flexion</strong>.</li></ul>"},{"i":"bade73d2e557","n":334,"o":"334-16","u":"Identifier une urgence","t":"Savoir reconnaître les signes de gravité d’une brûlure chez l’adulte et l’enfant","q":"Quels sont les critères liés au terrain ou au contexte qui classent une brûlure comme grave ?","a":"<p>Les critères de gravité liés au terrain et au contexte sont :</p><ul><li><strong>Terrain</strong> : âge (<strong>< 3 ans ou > 60 ans</strong>), comorbidités (insuffisance respiratoire/cardiaque/rénale, diabète, éthylisme).</li><li><strong>Contexte</strong> : traumatismes associés, <strong>brûlure électrique</strong> (trouble du rythme, rhabdomyolyse), <strong>brûlure chimique</strong> (effets systémiques), <strong>inhalation de fumées</strong>, troubles de conscience (suspecter une intoxication).</li></ul>"},{"i":"3d7f8af0b9e4","n":334,"o":"334-17","u":"Contenu multimédia","t":"Identifier une brûlure des voies aériennes","q":"Quel examen permet de confirmer la présence de suie en aval des cordes vocales dans le cadre d'une brûlure des voies aériennes ?","a":"<p>La présence de suie en aval des cordes vocales est confirmée par la <strong>fibroscopie des voies aériennes supérieures</strong>.</p>"},{"i":"4fb9098eb611","n":334,"o":"334-17","u":"Contenu multimédia","t":"Identifier une brûlure des voies aériennes","q":"Quels signes cliniques orientent vers une brûlure des voies aériennes chez un patient brûlé ?","a":"<ul><li>La présence de <strong>suie au niveau des orifices</strong> (nez, bouche).</li><li>Une brûlure des <strong>cils ou sourcils</strong>.</li><li>Des brûlures de la <strong>face et du cou</strong> associées.</li><li>Des signes de dyspnée, une modification de la voix ou un stridor, surtout dans les premières heures, évocateurs d'un <strong>œdème laryngé</strong>.</li></ul>"},{"i":"a770433cd9e2","n":334,"o":"334-17","u":"Contenu multimédia","t":"Identifier une brûlure des voies aériennes","q":"Quelle est l'une des principales menaces vitales associée à la brûlure des voies aériennes ?","a":"<p>La principale menace vitale associée à la brûlure des voies aériennes est l'<strong>obstruction des voies aériennes</strong> due à l'œdème.</p>"},{"i":"ffe1d49053e3","n":334,"o":"334-17","u":"Contenu multimédia","t":"Identifier une brûlure des voies aériennes","q":"Quelle est la prise en charge immédiate à envisager en cas d'œdème des voies aériennes supérieures avec détresse respiratoire secondaire à une brûlure ?","a":"<p>La prise en charge immédiate est une <strong>intubation orotrachéale précoce</strong>, avant l'aggravation de l'œdème et la difficulté croissante de l'intubation.</p>"},{"i":"035bf03641da","n":334,"o":"334-18","u":"Prise en charge","t":"Connaître les principes des soins locaux de brûlure","q":"Quels sont les premiers gestes locaux à effectuer sur les lieux d'un accident pour une brûlure, concernant l'agent brûlant et les vêtements ?","a":"<p>Il faut d'abord <strong>interrompre l'agent brûlant</strong>. Ensuite, <strong>retirer les vêtements non adhérents et les bagues</strong>. Ne pas ôter les vêtements adhérents, sauf s'ils sont imprégnés par un liquide chaud ou caustique.</p>"},{"i":"05735e159fb2","n":334,"o":"334-18","u":"Prise en charge","t":"Connaître les principes des soins locaux de brûlure","q":"Quels sont les principes des soins locaux hospitaliers initiaux d'une brûlure ?","a":"<ul><li><strong>Lavage</strong> de la brûlure.</li><li><strong>Mise à plat des phlyctènes</strong> au savon antiseptique.</li><li><strong>Rasage péri-lésionnel</strong>.</li><li>Application d'un <strong>pansement avec un topique anti-infectieux</strong>, typiquement de la <strong>sulfadiazine d'argent (Flammazine)</strong>.</li><li>Mise en place d'une <strong>couverture cutanée temporaire ou définitive (allogreffe)</strong>, qui est fondamentale pour la prévention de l'infection.</li></ul>"},{"i":"1899da126f15","n":334,"o":"334-18","u":"Prise en charge","t":"Connaître les principes des soins locaux de brûlure","q":"Comment doit-on refroidir une brûlure sur les lieux de l'accident et quelles précautions faut-il prendre ?","a":"<p>Le refroidissement doit suivre la <strong>règle des « 15 »</strong> : utilisation d'eau à <strong>15°C</strong> pendant <strong>15 minutes</strong>. Cela diminue la douleur et la profondeur de la brûlure. On peut aussi utiliser un hydrogel (type Brulstop). Il est impératif d'<strong>arrêter le refroidissement si le patient ressent une sensation de froid</strong> pour éviter une hypothermie.</p>"},{"i":"39af0f5ff3e2","n":334,"o":"334-18","u":"Prise en charge","t":"Connaître les principes des soins locaux de brûlure","q":"Concernant la prévention de l'infection dans la prise en charge d'un brûlé, quelle est la règle concernant l'antibiothérapie et la vaccination antitétanique ?","a":"<p>Il ne faut <strong>pas d'antibiothérapie systémique systématique</strong> dans les premières heures, sauf en cas de brûlure souillée ou périnéale. En revanche, la <strong>prévention antitétanique est systématique</strong>.</p>"},{"i":"9daa4b884d52","n":334,"o":"334-18","u":"Prise en charge","t":"Connaître les principes des soins locaux de brûlure","q":"Quelle est la particularité des premiers soins locaux pour une brûlure chimique sur les lieux de l'accident ?","a":"<p>Pour une brûlure chimique, le premier geste local est un <strong>rinçage abondant à l'eau</strong>, d'une durée d'au moins <strong>30 minutes</strong>.</p>"},{"i":"22a80a02782b","n":334,"o":"334-22","u":"Diagnostic positif","t":"Savoir suspecter un traumatisme thoracique","q":"Que doit faire suspecter une asymétrie auscultatoire ou un tympanisme à l'examen thoracique d'un polytraumatisé ?","a":"<p>Une asymétrie auscultatoire ou un tympanisme doivent faire suspecter un <strong>épanchement pleural</strong> (liquide ou gazeux) ou un <strong>pneumothorax</strong>.</p>"},{"i":"3bd0e3f1d6cd","n":334,"o":"334-22","u":"Diagnostic positif","t":"Savoir suspecter un traumatisme thoracique","q":"Quelle lésion doit-on suspecter chez un polytraumatisé présentant une dyspnée et une cyanose ?","a":"<p>Devant une dyspnée et une cyanose chez un polytraumatisé, il faut suspecter un <strong>épanchement pleural</strong>, une <strong>contusion pulmonaire</strong>, ou une <strong>tamponnade cardiaque</strong>.</p>"},{"i":"40e7129167ab","n":334,"o":"334-22","u":"Diagnostic positif","t":"Savoir suspecter un traumatisme thoracique","q":"Quelle étiologie doit être recherchée devant l'apparition d'un emphysème sous-cutané cervical chez un polytraumatisé ?","a":"<p>Un emphysème sous-cutané cervical chez un polytraumatisé doit faire rechercher une <strong>rupture trachéo-bronchique</strong> ou <strong>œsophagienne</strong>.</p>"},{"i":"499e11a07512","n":334,"o":"334-22","u":"Diagnostic positif","t":"Savoir suspecter un traumatisme thoracique","q":"Quelles lésions sont suspectées devant une turgescence jugulaire chez un polytraumatisé ?","a":"<p>Une <strong>tamponnade</strong> ou un <strong>pneumothorax compressif</strong> doivent être suspectés en cas de turgescence jugulaire chez un polytraumatisé.</p>"},{"i":"6a4ef091921c","n":334,"o":"334-22","u":"Diagnostic positif","t":"Savoir suspecter un traumatisme thoracique","q":"Quels signes cliniques orientent vers une rupture aortique traumatique chez un polytraumatisé ?","a":"<p>Une <strong>asymétrie des pouls</strong> ou de la <strong>tension artérielle aux membres</strong>, ainsi qu'un <strong>souffle interscapulaire</strong>, orientent vers une rupture aortique traumatique.</p>"},{"i":"acee42787149","n":334,"o":"334-22","u":"Diagnostic positif","t":"Savoir suspecter un traumatisme thoracique","q":"Quel signe clinique est évocateur d'un volet thoracique chez un polytraumatisé ?","a":"<p>La présence d'une <strong>respiration paradoxale</strong> est évocatrice d'un volet thoracique chez un polytraumatisé.</p>"},{"i":"c6af4c1cc59f","n":334,"o":"334-22","u":"Diagnostic positif","t":"Savoir suspecter un traumatisme thoracique","q":"Quelle est la signification d'une ecchymose pariétale thoracique, ou « signe de la ceinture », chez un polytraumatisé ?","a":"<p>Une ecchymose pariétale thoracique, ou « signe de la ceinture », indique un <strong>choc à haute vélocité</strong> et fait suspecter une <strong>lésion sous-jacente sévère</strong>.</p>"},{"i":"1c32196068bf","n":334,"o":"334-23","u":"Examens complémentaires","t":"Savoir demander les examens complémentaires permettant le diagnostic de traumatisme thoracique","q":"Quels examens doivent être demandés pour rechercher une contusion myocardique chez le polytraumatisé avec traumatisme thoracique ?","a":"<p>Pour rechercher une contusion myocardique, il faut demander un <strong>ECG</strong>, la <strong>troponine</strong> et une <strong>ETT</strong> (échographie trans-thoracique).</p>"},{"i":"278ef63fe2bb","n":334,"o":"334-23","u":"Examens complémentaires","t":"Savoir demander les examens complémentaires permettant le diagnostic de traumatisme thoracique","q":"Quel est l'examen de référence pour le diagnostic des traumatismes thoraciques chez le polytraumatisé ?","a":"<p>L'examen de référence est la <strong>TDM thoracique injectée</strong>.</p>"},{"i":"569b8001646c","n":334,"o":"334-23","u":"Examens complémentaires","t":"Savoir demander les examens complémentaires permettant le diagnostic de traumatisme thoracique","q":"Quelles informations diagnostiques la TDM thoracique injectée apporte-t-elle dans le cadre d'un traumatisme thoracique chez le polytraumatisé ?","a":"<p>La TDM thoracique injectée permet de diagnostiquer les <strong>contusions pulmonaires</strong>, l'<strong>hémomédiastin</strong>, et les <strong>lésions des gros vaisseaux</strong>.</p>"},{"i":"8add1bca45da","n":334,"o":"334-23","u":"Examens complémentaires","t":"Savoir demander les examens complémentaires permettant le diagnostic de traumatisme thoracique","q":"Quel est l'intérêt de la radiographie thoracique de face comme examen initial dans l'évaluation d'un polytraumatisé avec traumatisme thoracique ?","a":"<p>La radiographie thoracique de face est un <strong>examen initial</strong> qui peut être réalisé <strong>sur le brancard</strong>. Cependant, elle est souvent <strong>supplantée par le FAST/TDM</strong> en raison de leur meilleure performance diagnostique.</p>"},{"i":"ad5d3b154207","n":334,"o":"334-23","u":"Examens complémentaires","t":"Savoir demander les examens complémentaires permettant le diagnostic de traumatisme thoracique","q":"Pour quelle raison et dans quel contexte pratique l'échographie pleuro-pulmonaire (FAST/eFAST) est-elle utile chez le polytraumatisé avec traumatisme thoracique ?","a":"<p>L'échographie pleuro-pulmonaire (FAST/eFAST) est utile pour rechercher un <strong>épanchement pleural</strong>, un <strong>pneumothorax</strong> ou une <strong>contusion</strong>. Elle est <strong>réalisable au lit du patient</strong> et est <strong>performante chez le patient instable</strong>.</p>"},{"i":"f320f015a054","n":334,"o":"334-23","u":"Examens complémentaires","t":"Savoir demander les examens complémentaires permettant le diagnostic de traumatisme thoracique","q":"Pourquoi réalise-t-on des gaz du sang chez un polytraumatisé présentant un traumatisme thoracique ?","a":"<p>Les gaz du sang sont réalisés pour évaluer le <strong>retentissement de l'atteinte respiratoire</strong>.</p>"},{"i":"2f84a26e8386","n":334,"o":"334-24","u":"Examens complémentaires","t":"Savoir reconnaître un hémothorax et un pneumothorax sur une radiographie","q":"Quels sont les signes radiographiques d'un hémothorax sur un cliché thoracique standard ?","a":"<p>Devant un hémothorax, une radiographie thoracique montre :</p><ul><li>Une <strong>opacité déclive</strong>, dense et homogène, effaçant la coupole diaphragmatique.</li><li>Une <strong>ligne de Damoiseau</strong> (limite supérieure concave de l'épanchement).</li><li>Sur un cliché en position debout, il y a un <strong>comblement du cul-de-sac pleural</strong>.</li></ul>"},{"i":"6b929b03ca83","n":334,"o":"334-24","u":"Examens complémentaires","t":"Savoir reconnaître un hémothorax et un pneumothorax sur une radiographie","q":"Comment identifier un pneumothorax compressif et quelle est la place de la radiographie dans son diagnostic ?","a":"<p>Un pneumothorax compressif se traduit par :</p><ul><li>Une <strong>déviation médiastinale controlatérale</strong>.</li><li>Un possible <strong>abaissement de la coupole</strong>.</ul><p>Il s'agit avant tout d'un <strong>diagnostic clinique</strong> qui ne doit pas retarder la prise en charge dans l'attente d'une radiographie.</p>"},{"i":"9bdfa72c7a00","n":334,"o":"334-24","u":"Examens complémentaires","t":"Savoir reconnaître un hémothorax et un pneumothorax sur une radiographie","q":"Peut-on passer à côté d'un pneumothorax sur une radiographie thoracique ?","a":"<p>Oui, un pneumothorax peut être <strong>occulte</strong> et non visible sur une radiographie thoracique de face réalisée en position couchée. Dans ce cas, il n'est détecté que par un <strong>scanner thoracique</strong> (TDM) et ne nécessite pas forcément un drainage.</p>"},{"i":"d4f6a50ea106","n":334,"o":"334-24","u":"Examens complémentaires","t":"Savoir reconnaître un hémothorax et un pneumothorax sur une radiographie","q":"Quels sont les signes radiographiques d'un pneumothorax sur un cliché thoracique standard ?","a":"<p>Un pneumothorax est caractérisé radiographiquement par :</p><ul><li>Une <strong>hyperclarté périphérique avasculaire</strong>.</li><li>La visibilité de la <strong>ligne pleurale</strong>.</li><li>Une <strong>asymétrie de transparence</strong> des hémichamps.</p></ul>"},{"i":"19a8787ef5d9","n":334,"o":"334-25","u":"Contenu multimédia","t":"Radiographies d’hémothorax et de pneumothorax","q":"Comment identifier un pneumothorax à la radiographie thoracique chez un polytraumatisé ?","a":"<p>Un pneumothorax à la radiographie thoracique est identifiable par :</p><ul><li>Une <strong>hyperclarté périphérique avasculaire</strong>.</li><li>Une <strong>ligne pleurale fine</strong>.</li><li>Un <strong>moignon pulmonaire rétracté</strong> au hile (surtout si le pneumothorax est complet).</li></ul>"},{"i":"37a92f636916","n":334,"o":"334-25","u":"Contenu multimédia","t":"Radiographies d’hémothorax et de pneumothorax","q":"Quels sont les signes radiographiques suggestifs d'une rupture de l'isthme aortique chez un polytraumatisé ?","a":"<p>Les signes radiographiques suggestifs d'une rupture de l'isthme aortique chez un polytraumatisé sont :</p><ul><li>Un <strong>élargissement du médiastin &gt; 8 cm</strong>.</li><li>La <strong>disparition du bouton aortique</strong>.</li><li>Une <strong>déviation trachéale</strong>.</li></ul>"},{"i":"8775bc342efc","n":334,"o":"334-25","u":"Contenu multimédia","t":"Radiographies d’hémothorax et de pneumothorax","q":"Quels sont les signes radiographiques clés d'un hémothorax chez un polytraumatisé ?","a":"<p>Les signes radiographiques clés d'un hémothorax sont :</p><ul><li>Une <strong>opacité déclive homogène</strong>.</li><li>Une <strong>ligne de Damoiseau</strong> (limite supérieure concave et ascendante en dehors).</li><li>Une <strong>grisaille diffuse</strong> d'un hémichamp.</li><li>Une <strong>déviation médiastinale</strong> si l'hémothorax est abondant.</li></ul>"},{"i":"45435a0711f2","n":334,"o":"334-26","u":"Identifier une urgence","t":"Savoir identifier les situations indiquant le recours à une thérapeutique de sauvetage","q":"Quelles sont les indications de thoracotomie d'hémostase en cas d'hémothorax massif chez un polytraumatisé ?","a":"<p>Une thoracotomie d'hémostase est indiquée en cas d'hémothorax massif si le drainage immédiat excède <strong>1 500 mL</strong> ou si le débit de drainage est supérieur à <strong>200 mL/h</strong>.</p>"},{"i":"bb11ba21bd51","n":334,"o":"334-26","u":"Identifier une urgence","t":"Savoir identifier les situations indiquant le recours à une thérapeutique de sauvetage","q":"Quelle est la priorité de prise en charge d'un traumatisme pénétrant avec suspicion de tamponnade chez un patient instable ?","a":"<p>La priorité est une <strong>hémostase rapide</strong> (drainage, chirurgie, embolisation) avant tout body-TDM chez un patient non stabilisé.</p>"},{"i":"e2cd5c976d84","n":334,"o":"334-26","u":"Identifier une urgence","t":"Savoir identifier les situations indiquant le recours à une thérapeutique de sauvetage","q":"Quel est le geste de sauvetage immédiat face à un pneumothorax compressif (asphyxiant) chez un polytraumatisé ?","a":"<p>Face à un pneumothorax compressif, le geste de sauvetage est une <strong>exsufflation à l'aiguille en urgence</strong>, suivie d'un drainage thoracique.</p>"},{"i":"ede54a65dc98","n":334,"o":"334-26","u":"Identifier une urgence","t":"Savoir identifier les situations indiquant le recours à une thérapeutique de sauvetage","q":"Quelle est la prise en charge d'une plaie soufflante du thorax pour prévenir un pneumothorax compressif ?","a":"<p>La prise en charge initiale d'une plaie soufflante du thorax est la pose d'un <strong>pansement non occlusif (fixé sur 3 côtés)</strong> afin de prévenir le développement d'un pneumothorax compressif.</p>"},{"i":"39c2c0bdbff4","n":334,"o":"334-29","u":"Diagnostic positif","t":"Savoir suspecter un traumatisme abdominal","q":"Quels sont les signes d'appel de traumatisme abdominal à rechercher lors de l'interrogatoire (symptômes) ?","a":"<p>Lors de l'interrogatoire, on recherche la <strong>douleur abdominale</strong>. Des irradiations sont évocatrices :</p><ul><li>Irradiation à la <strong>scapula gauche</strong> : évoque un traumatisme <strong>splénique</strong>.</li><li>Irradiation à la <strong>scapula droite</strong> : évoque un traumatisme <strong>hépatique</strong>.</li><li>La présence d'une <strong>hématurie</strong> doit faire suspecter une lésion <strong>rénale</strong>.</li></ul>"},{"i":"75fd8c1dd3bf","n":334,"o":"334-29","u":"Diagnostic positif","t":"Savoir suspecter un traumatisme abdominal","q":"Quels sont les signes à rechercher lors de l'inspection et de la palpation de l'abdomen pour suspecter un traumatisme abdominal ?","a":"<ul><li>À l'<strong>inspection</strong>, on recherche des <strong>contusions</strong>, le « <strong>signe de la ceinture</strong> » ou un <strong>météorisme</strong>.</li><li>À la <strong>palpation</strong>, on recherche une <strong>défense</strong>, une <strong>contracture</strong>, une <strong>matité</strong> (en faveur d'un <strong>hémopéritoine</strong>) ou un <strong>tympanisme</strong> (en faveur d'un <strong>pneumopéritoine</strong>).</li></ul>"},{"i":"d7bb2a61597d","n":334,"o":"334-29","u":"Diagnostic positif","t":"Savoir suspecter un traumatisme abdominal","q":"Dans quelles situations classiques un traumatisme abdominal doit-il être évoqué en urgence, constituant un piège diagnostique ?","a":"<p>Un traumatisme abdominal doit être évoqué pendant le transport devant :</p><ul><li>Un <strong>remplissage par &gt; 1 L</strong> (non efficace).</li><li>Une <strong>hypotension persistante</strong>.</li><li>Un <strong>arrêt cardiaque massé</strong> chez un traumatisé.</li></ul><p>Il faut toujours considérer <strong>tout traumatisé sévère</strong> comme un <strong>traumatisé du bassin</strong> jusqu'à preuve du contraire (notamment en présence d'une <strong>instabilité à la palpation des crêtes iliaques</strong>).</p>"},{"i":"f2df9e0f84f4","n":334,"o":"334-29","u":"Diagnostic positif","t":"Savoir suspecter un traumatisme abdominal","q":"Quels syndromes associés doivent faire suspecter un traumatisme abdominal ?","a":"<p>On doit rechercher :</p><ul><li>Un <strong>syndrome péritonéal</strong>.</li><li>Un <strong>syndrome occlusif</strong>.</li><li>Des <strong>signes de choc hémorragique</strong>.</li></ul>"},{"i":"062d8006fef5","n":334,"o":"334-3","u":"Diagnostic positif","t":"Savoir identifier et caractériser les lésions cliniquement","q":"Que faut-il faire et rechercher lors de l'étape 'E' (Exposure) de l'évaluation d'un polytraumatisé, et quel est le piège associé ?","a":"<p>Il faut réaliser un <strong>déshabillage complet</strong> pour rechercher les <strong>plaies</strong> et les <strong>foyers de fracture</strong>. La <strong>prévention de l'hypothermie</strong> est systématique. Un <strong>toucher rectal</strong> est systématique si le patient est inconscient ou en cas de suspicion de lésion du rachis ; une <strong>béance anale</strong> fait suspecter une <strong>lésion médullaire</strong>.</p>"},{"i":"074ce0796f01","n":334,"o":"334-3","u":"Diagnostic positif","t":"Savoir identifier et caractériser les lésions cliniquement","q":"Quels sont les éléments clés à évaluer lors de l'étape 'B' (Breathing) de la prise en charge d'un polytraumatisé ?","a":"<ul><li><strong>SpO₂</strong></li><li><strong>Fréquence respiratoire (FR)</strong></li><li><strong>Cyanose</strong></li><li>Signes de <strong>détresse respiratoire</strong></li></ul>"},{"i":"0844c309b4f5","n":334,"o":"334-3","u":"Diagnostic positif","t":"Savoir identifier et caractériser les lésions cliniquement","q":"Quelle est l'approche systématique utilisée par le médecin du SMUR pour évaluer un polytraumatisé à l'arrivée sur les lieux ?","a":"<p>L'évaluation est réalisée selon la grille universelle <strong>ABCDE</strong>, dans un ordre strict.</p>"},{"i":"3d366d02197f","n":334,"o":"334-3","u":"Diagnostic positif","t":"Savoir identifier et caractériser les lésions cliniquement","q":"Que recherche le médecin du SMUR lors de l'étape 'A' (Airway) de l'évaluation initiale d'un polytraumatisé ?","a":"<p>Il recherche la <strong>liberté des voies aériennes</strong> et toute <strong>obstruction</strong>. Le <strong>rachis cervical est immobilisé</strong>.</p>"},{"i":"7cb8cb80477b","n":334,"o":"334-3","u":"Diagnostic positif","t":"Savoir identifier et caractériser les lésions cliniquement","q":"Quels sont les paramètres cliniques essentiels à évaluer lors de l'étape 'C' (Circulation) chez un polytraumatisé ?","a":"<ul><li>Recherche d'un <strong>état de choc</strong></li><li><strong>Pression artérielle (PA)</strong> : un pouls radial palpable indique une PAS > 70 mmHg</li><li><strong>Fréquence cardiaque (FC)</strong></li><li>Recherche d'une <strong>hémorragie active</strong></li></ul>"},{"i":"b1e5f92af87c","n":334,"o":"334-3","u":"Diagnostic positif","t":"Savoir identifier et caractériser les lésions cliniquement","q":"Quelles sont les 5 régions du corps à examiner cliniquement de manière systématique chez un polytraumatisé ?","a":"<ul><li><strong>Tête-cou-rachis</strong></li><li><strong>Thorax</strong></li><li><strong>Abdomen</strong></li><li><strong>Bassin</strong></li><li><strong>Membres</strong></li></ul>"},{"i":"c3e2b6dade1f","n":334,"o":"334-3","u":"Diagnostic positif","t":"Savoir identifier et caractériser les lésions cliniquement","q":"Quels sont les éléments à évaluer lors de l'étape 'D' (Disability) de la prise en charge d'un polytraumatisé ?","a":"<ul><li>Score de <strong>Glasgow</strong></li><li><strong>Pupilles</strong> (réactivité, symétrie)</li><li><strong>Tonicité des membres</strong></li><li><strong>Tonus du sphincter anal</strong> (par Toucher Rectal)</li></ul>"},{"i":"035de39873eb","n":334,"o":"334-30","u":"Examens complémentaires","t":"Savoir demander les examens d’imagerie permettant le diagnostic de traumatisme abdominal","q":"Comment se présente une fracture de rate sur une TDM dans le cadre d'un traumatisme splénique ?","a":"<p>Une fracture de rate se présente comme une <strong>hypodensité arciforme intra-splénique</strong> visible à tous les temps de l'acquisition TDM, souvent associée à un <strong>réhaussement tigré physiologique</strong> au temps artériel.</p>"},{"i":"20652ddc2344","n":334,"o":"334-30","u":"Examens complémentaires","t":"Savoir demander les examens d’imagerie permettant le diagnostic de traumatisme abdominal","q":"Quelle est l'approche d'imagerie pour le diagnostic d'un traumatisme abdominal chez un patient polytraumatisé <b>stable hémodynamiquement</b> ?","a":"<p>Chez un patient stable hémodynamiquement, l'examen de référence est la <strong>TDM abdomino-pelvienne injectée</strong>, également appelée body-TDM. Elle permet de cartographier les lésions et d'identifier, en cas de <strong>blush</strong> (fuite active de produit de contraste), un foyer hémorragique.</p>"},{"i":"516ed8656dea","n":334,"o":"334-30","u":"Examens complémentaires","t":"Savoir demander les examens d’imagerie permettant le diagnostic de traumatisme abdominal","q":"Quelle est l'approche d'imagerie initiale pour le diagnostic d'un traumatisme abdominal chez un patient polytraumatisé <b>instable hémodynamiquement</b> ?","a":"<p>Chez un patient instable hémodynamiquement, l'approche d'imagerie initiale inclut :</p><ul><li>Une <strong>radiographie du thorax</strong> (RXT)</li><li>Une <strong>radiographie du bassin</strong></li><li>Une <strong>FAST-échographie</strong> (Focused Assessment with Sonography for Trauma)</li></ul>"},{"i":"c2ddcfe5d1c2","n":334,"o":"334-30","u":"Examens complémentaires","t":"Savoir demander les examens d’imagerie permettant le diagnostic de traumatisme abdominal","q":"Quel est le <b>piège classique</b> concernant la FAST-échographie dans l'évaluation d'un traumatisme abdominal ?","a":"<p>La FAST-échographie <strong>ne voit pas</strong> l'hémorragie rétropéritonéale, qui est le siège électif des hémorragies sur traumatisme du bassin.</p>"},{"i":"f1259cd3e00d","n":334,"o":"334-30","u":"Examens complémentaires","t":"Savoir demander les examens d’imagerie permettant le diagnostic de traumatisme abdominal","q":"Que permet la FAST-échographie dans le cadre du bilan d'un traumatisme abdominal chez le polytraumatisé instable ?","a":"<p>La FAST-échographie permet de rechercher un <strong>hémopéritoine</strong>. Elle identifie des images anéchogènes dans les espaces inter-hépato-rénal (<strong>Morrison</strong>), inter-spléno-rénal (<strong>Köhler</strong>) et le <strong>cul-de-sac de Douglas</strong>.</p>"},{"i":"8252fe9c0c92","n":334,"o":"334-31","u":"Identifier une urgence","t":"Savoir identifier le recours à une thérapeutique d’hémostase en urgence chez l’adulte et l’enfant","q":"Quelle est l'attitude thérapeutique d'hémostase en urgence à adopter devant un patient polytraumatisé instable avec un hémopéritoine au FAST ?","a":"<p>La conduite à tenir est une <strong>laparotomie « damage control » de sauvetage</strong>.</p>"},{"i":"91a6fdf5bbd5","n":334,"o":"334-31","u":"Identifier une urgence","t":"Savoir identifier le recours à une thérapeutique d’hémostase en urgence chez l’adulte et l’enfant","q":"Quelle est la thérapeutique de sauvetage en cas d'instabilité hémodynamique extrême et réfractaire chez un patient polytraumatisé ?","a":"<p>En cas d'instabilité extrême réfractaire, la thérapeutique de sauvetage est la pose d'un <strong>ballon d'occlusion intra-aortique</strong>, à réaliser avant la chirurgie ou l'embolisation.</p>"},{"i":"96546f2119ce","n":334,"o":"334-31","u":"Identifier une urgence","t":"Savoir identifier le recours à une thérapeutique d’hémostase en urgence chez l’adulte et l’enfant","q":"Quelle est l'attitude générale face à un patient polytraumatisé stable présentant un traumatisme abdominal fermé ?","a":"<p>Chez le patient <strong>stable</strong> (représentant <strong>90 %</strong> des traumatismes abdominaux fermés), l'attitude est <strong>non opératoire</strong> avec surveillance en milieu chirurgical, quel que soit l'organe atteint.</p>"},{"i":"9ddc0a5109b3","n":334,"o":"334-31","u":"Identifier une urgence","t":"Savoir identifier le recours à une thérapeutique d’hémostase en urgence chez l’adulte et l’enfant","q":"Quelle thérapeutique d'hémostase en urgence est indiquée chez un patient polytraumatisé stable présentant un blush artériel au scanner (TDM) ?","a":"<p>Chez un patient stable avec un blush artériel au TDM, une <strong>embolisation artérielle sélective différée</strong> est indiquée.</p>"},{"i":"ad959a1b2991","n":334,"o":"334-31","u":"Identifier une urgence","t":"Savoir identifier le recours à une thérapeutique d’hémostase en urgence chez l’adulte et l’enfant","q":"Dans quel contexte clinique général doit-on envisager le recours à une hémostase en urgence chez un patient polytraumatisé adulte ou enfant ?","a":"<p>Le recours à une hémostase en urgence est dicté par l'<strong>instabilité hémodynamique</strong> du patient.</p>"},{"i":"f844b3bf92c5","n":334,"o":"334-31","u":"Identifier une urgence","t":"Savoir identifier le recours à une thérapeutique d’hémostase en urgence chez l’adulte et l’enfant","q":"Quelle est la stratégie d'hémostase recommandée face à un patient polytraumatisé en choc avec un fracas du bassin radiologique et un FAST négatif ?","a":"<p>En présence d'une hémorragie pelvienne probable, l'indication est une <strong>artério-embolisation</strong>.</p>"},{"i":"1ff5e50dc82f","n":334,"o":"334-35","u":"Diagnostic positif","t":"Savoir suspecter à l’anamnèse et à l’examen clinique une lésion osseuse","q":"Quels sont les facteurs aggravants d'une lésion osseuse à rechercher systématiquement à l'examen clinique chez un polytraumatisé ?","a":"<p>Les facteurs aggravants à rechercher systématiquement sont :</p><ul><li>La présence de <strong>plusieurs foyers fracturaires</strong> (polyfracturé des membres).</li><li>Une <strong>articulation flottante</strong> (fracture au-dessus et au-dessous d'une même articulation).</li><li>Une <strong>fracture articulaire</strong>, qui expose à un risque de complications tardives (arthrose, raideur).</li><li>Des <strong>fractures-luxations</strong> (urgence à ne pas manquer).</li></ul>"},{"i":"3d020caac6c4","n":334,"o":"334-35","u":"Diagnostic positif","t":"Savoir suspecter à l’anamnèse et à l’examen clinique une lésion osseuse","q":"Quelles complications doit-on systématiquement rechercher à l'examen clinique devant toute lésion osseuse chez un polytraumatisé ?","a":"<p>Devant toute lésion osseuse, il faut systématiquement rechercher les complications suivantes :</p><ul><li>Les <strong>complications vasculaires</strong> : examen des <strong>pouls périphériques</strong> en aval de la lésion.</li><li>Les <strong>complications nerveuses</strong> : <strong>examen sensitivo-moteur</strong> en aval de la lésion.</li><li>Une <strong>ouverture cutanée</strong>, signe de fracture ouverte.</li></ul>"},{"i":"614bed5c1f9d","n":334,"o":"334-35","u":"Diagnostic positif","t":"Savoir suspecter à l’anamnèse et à l’examen clinique une lésion osseuse","q":"Quelle est la triade clinique classique permettant de suspecter une fracture chez un polytraumatisé ?","a":"<p>La fracture est suspectée devant la triade clinique classique :</p><ul><li><strong>Douleur localisée</strong>, exacerbée à la palpation.</li><li><strong>Déformation du membre</strong> (angulation, raccourcissement, décalage rotatoire).</li><li><strong>Impotence fonctionnelle</strong> du membre.</li></ul>"},{"i":"d4eacd22113a","n":334,"o":"334-35","u":"Diagnostic positif","t":"Savoir suspecter à l’anamnèse et à l’examen clinique une lésion osseuse","q":"Quels éléments clés de l'anamnèse recherche-t-on pour suspecter une lésion osseuse chez un polytraumatisé ?","a":"<p>Devant une suspicion de lésion osseuse chez un polytraumatisé, l'anamnèse doit préciser :</p><ul><li>Le <strong>mécanisme du traumatisme</strong> (direct ou indirect).</li><li>L'<strong>énergie du traumatisme</strong> (élevée ou faible).</li><li>Le <strong>terrain du patient</strong> (âge, comorbidités, etc.).</li></ul>"},{"i":"0412a9a482dc","n":334,"o":"334-36","u":"Identifier une urgence","t":"Savoir suspecter des complications vasculaires et neurologiques","q":"En cas de luxation gléno-humérale chez un polytraumatisé, quel(s) nerf(s) est(sont) particulièrement à risque de lésion ?","a":"Lors d'une luxation gléno-humérale, le <strong>nerf axillaire</strong> est à risque, potentiellement accompagné d'une lésion du <strong>plexus brachial</strong>."},{"i":"1fede18a0a80","n":334,"o":"334-36","u":"Identifier une urgence","t":"Savoir suspecter des complications vasculaires et neurologiques","q":"Quelle est l'attitude thérapeutique en urgence face à une compression nerveuse ou une ischémie aiguë de membre chez un polytraumatisé ?","a":"Face à ces urgences :<ul><li>Une <strong>compression nerveuse</strong> doit être <strong>levée en urgence</strong>.</li><li>Une <strong>ischémie aiguë de membre</strong> impose une <strong>revascularisation immédiate</strong>.</li></ul>"},{"i":"2e0caa623cfc","n":334,"o":"334-36","u":"Identifier une urgence","t":"Savoir suspecter des complications vasculaires et neurologiques","q":"Quelle artère est à risque de lésion en cas de fracture supracondylienne chez un polytraumatisé ?","a":"En cas de fracture supracondylienne, l'<strong>artère humérale</strong> est particulièrement à risque de lésion."},{"i":"4a6b3076e16a","n":334,"o":"334-36","u":"Identifier une urgence","t":"Savoir suspecter des complications vasculaires et neurologiques","q":"Quels sont les signes cliniques permettant de suspecter une complication vasculaire ischémique chez un polytraumatisé ?","a":"Les signes cliniques d'une complication vasculaire ischémique sont :<ul><li><strong>Asymétrie des pouls</strong></li><li><strong>Pâleur et froideur</strong> du membre en aval</li><li><strong>Douleur intense</strong></li></ul>"},{"i":"81d644bf9676","n":334,"o":"334-36","u":"Identifier une urgence","t":"Savoir suspecter des complications vasculaires et neurologiques","q":"Quels examens complémentaires permettent de confirmer une complication vasculaire ischémique chez un polytraumatisé ?","a":"La confirmation d'une complication vasculaire ischémique se fait par :<ul><li><strong>Écho-Doppler</strong></li><li><strong>Angio-TDM</strong></li><li><strong>Artériographie</strong></li></ul>"},{"i":"ad93f4a2d6a8","n":334,"o":"334-36","u":"Identifier une urgence","t":"Savoir suspecter des complications vasculaires et neurologiques","q":"Quel nerf est à risque de lésion en cas de fracture de la diaphyse humérale chez un polytraumatisé ?","a":"En cas de fracture de la diaphyse humérale, le <strong>nerf radial</strong> est le nerf à risque de lésion."},{"i":"cd49740abe6f","n":334,"o":"334-36","u":"Identifier une urgence","t":"Savoir suspecter des complications vasculaires et neurologiques","q":"Chez un polytraumatisé, quelles sont les localisations osseuses à risque de lésion de l'artère poplitée ?","a":"L'artère poplitée est à risque en cas de :<ul><li><strong>Luxation du genou</strong></li><li><strong>Fracture fémorale distale</strong></li><li><strong>Fracture tibiale proximale</strong></li></ul>"},{"i":"17a4ba445526","n":334,"o":"334-37","u":"Examens complémentaires","t":"Connaître les indications et savoir demander un examen d’imagerie devant un traumatisé des membres et/ou du bassin","q":"Quelle est l'indication des radiographies standards et leurs spécificités devant un traumatisé des membres ?","a":"<p>Les radiographies standards sont indiquées pour évaluer un traumatisme des membres. Elles doivent comporter <strong>deux incidences orthogonales</strong> et visualiser les <strong>articulations sus- et sous-jacentes</strong> (ex: pour une fracture de jambe : jambe de face et de profil, incluant le genou et la cheville).</p>"},{"i":"29a94eb70b9f","n":334,"o":"334-37","u":"Examens complémentaires","t":"Connaître les indications et savoir demander un examen d’imagerie devant un traumatisé des membres et/ou du bassin","q":"L'IRM est-elle indispensable en urgence pour un traumatisme des membres ?","a":"<p>Non, l'<strong>IRM n'est pas indispensable en urgence</strong> pour l'exploration d'un traumatisme des membres.</p>"},{"i":"32809c4f003f","n":334,"o":"334-37","u":"Examens complémentaires","t":"Connaître les indications et savoir demander un examen d’imagerie devant un traumatisé des membres et/ou du bassin","q":"Dans quel contexte prescrit-on un TDM corps entier injecté chez un traumatisé, notamment du bassin ?","a":"<p>Un TDM corps entier injecté est prescrit en cas de <strong>polyfracturé</strong>, de <strong>polytraumatisé</strong> ou de <strong>traumatisé du bassin</strong>. Il est essentiel pour le bassin car la FAST ne permet pas de visualiser les hémorragies rétropéritonéales.</p>"},{"i":"5c2dc2be7f19","n":334,"o":"334-37","u":"Examens complémentaires","t":"Connaître les indications et savoir demander un examen d’imagerie devant un traumatisé des membres et/ou du bassin","q":"Quels examens d'imagerie vasculaire sont indiqués en cas de suspicion d'atteinte artérielle chez un traumatisé des membres ?","a":"<p>En cas d'atteinte artérielle cliniquement suspectée chez un traumatisé des membres, les examens indiqués sont l'<strong>écho-doppler</strong>, l'<strong>angio-TDM</strong> ou l'<strong>artériographie</strong>.</p>"},{"i":"b87dc5d2fc63","n":334,"o":"334-37","u":"Examens complémentaires","t":"Connaître les indications et savoir demander un examen d’imagerie devant un traumatisé des membres et/ou du bassin","q":"Quand indique-t-on une TDM centrée pour un traumatisme des membres ?","a":"<p>Une TDM centrée est indiquée pour <strong>préciser une fracture articulaire</strong>, notamment pour mieux analyser sa complexité ou son extension intra-articulaire.</p>"},{"i":"1deabab83ee5","n":334,"o":"334-4","u":"Diagnostic positif","t":"Connaître les critères de gravité d’un traumatisé","q":"Selon l'algorithme de Vittel, quand est-ce qu'un traumatisé est considéré comme sévère, impliquant une orientation vers un centre spécialisé ?","a":"<p>Un traumatisé est classé comme sévère dès qu'un <strong>seul critère</strong> de gravité est présent, parmi les 5 étapes de l'algorithme de Vittel.</p>"},{"i":"2d0c02ceab91","n":334,"o":"334-4","u":"Diagnostic positif","t":"Connaître les critères de gravité d’un traumatisé","q":"Quels sont les critères physiologiques, selon l'algorithme de Vittel, qui définissent un traumatisé sévère nécessitant une orientation en centre spécialisé ?","a":"<ul><li><strong>Glasgow < 13</strong></li><li><strong>Pression Artérielle Systolique (PAS) < 90 mmHg</strong></li><li><strong>SpO₂ < 90 %</strong></li></ul><p>On parle de particulière gravité si Glasgow = 3, PAS < 65 mmHg, ou SpO₂ < 80 % ou imprenable.</p>"},{"i":"6d837330dfaa","n":334,"o":"334-4","u":"Diagnostic positif","t":"Connaître les critères de gravité d’un traumatisé","q":"Quels sont les critères lésionnels, selon l'algorithme de Vittel, qui définissent un traumatisé sévère nécessitant une orientation en centre spécialisé ?","a":"<ul><li><strong>Trauma pénétrant</strong> (tête, cou, thorax, abdomen, bassin, bras, cuisse)</li><li><strong>Volet thoracique</strong></li><li><strong>Fracas ou instabilité du bassin</strong></li><li>Suspicion d'<strong>atteinte médullaire</strong></li><li><strong>Brûlure sévère</strong></li><li><strong>Amputation</strong></li><li><strong>Ischémie aiguë de membre</strong></li></ul>"},{"i":"98ecbbdbec4b","n":334,"o":"334-4","u":"Diagnostic positif","t":"Connaître les critères de gravité d’un traumatisé","q":"Quels sont les critères de terrain, selon l'algorithme de Vittel, qui doivent faire discuter une admission en réanimation ou en unité de surveillance continue chez un traumatisé ?","a":"<ul><li><strong>Âge > 65 ans</strong></li><li><strong>Insuffisance cardiaque</strong>, <strong>coronarienne</strong> ou <strong>respiratoire</strong></li><li><strong>Grossesse</strong> (2ᵉ ou 3ᵉ trimestre)</li><li><strong>Trouble de la crase</strong> ou traitement <strong>antithrombotique</strong></li></ul>"},{"i":"a5a048c64cb0","n":334,"o":"334-4","u":"Diagnostic positif","t":"Connaître les critères de gravité d’un traumatisé","q":"Quels sont les critères liés à la réanimation préhospitalière, selon l'algorithme de Vittel, qui définissent un traumatisé sévère nécessitant une orientation en centre spécialisé ?","a":"<ul><li><strong>Ventilation assistée</strong></li><li><strong>Remplissage > 1 litre</strong></li><li>Administration de <strong>catécholamines</strong></li><li>Utilisation d'un <strong>pantalon antichoc gonflé</strong></li></ul>"},{"i":"ee6002e576c5","n":334,"o":"334-4","u":"Diagnostic positif","t":"Connaître les critères de gravité d’un traumatisé","q":"Quels sont les critères cinétiques, selon l'algorithme de Vittel, qui définissent un traumatisé sévère nécessitant une orientation en centre spécialisé ?","a":"<ul><li><strong>Éjection du véhicule</strong></li><li>Victime <strong>projetée ou écrasée</strong></li><li><strong>Chute > 6 mètres</strong></li><li>Autre passager <strong>décédé</strong></li><li><strong>Déformation importante du véhicule</strong></li><li>Exposition à un <strong>blast</strong></li></ul>"},{"i":"1773492ef7a4","n":334,"o":"334-40","u":"Examens complémentaires","t":"Savoir rechercher des complications précoces","q":"Comment diagnostiquer une embolie graisseuse chez un polytraumatisé, et quels sont les éléments distinctifs de cette complication ?","a":"<p>Le diagnostic d'embolie graisseuse est évoqué devant un <strong>intervalle libre</strong> (quelques heures à 48 heures) après le traumatisme. Elle se manifeste par la <strong>triade de Gurd</strong> :</p><ul><li>Signes de <strong>SDRA (détresse respiratoire aiguë)</strong>.</li><li><strong>Signes neuropsychiques</strong> (confusion, agitation, coma).</li><li><strong>Purpura pétéchial</strong>, typiquement localisé au niveau du <strong>tronc, du cou, des conjonctives et de la muqueuse buccale</strong>.</li></ul><p>Bien qu'elle complique moins de 1% des fractures isolées d'os long, la fréquence peut atteindre 30% en cas de fractures multiples et prise en charge retardée.</p>"},{"i":"ba7f77cd42e4","n":334,"o":"334-40","u":"Examens complémentaires","t":"Savoir rechercher des complications précoces","q":"Quelles sont les complications infectieuses précoces à surveiller chez un patient polytraumatisé ?","a":"<p>Les complications infectieuses à surveiller chez un polytraumatisé sont :</p><ul><li>La <strong>gangrène gazeuse</strong>, causée notamment par <em>Clostridium</em>.</li><li>Les infections par <strong>germes pyogènes</strong>.</li><li>Le <strong>tétanos</strong>, nécessitant une prévention par <strong>SAT-VAT</strong> (Sérothérapie Antitétanique et Vaccination Anatétanique).</li></ul>"},{"i":"d55b3568b1ad","n":334,"o":"334-40","u":"Examens complémentaires","t":"Savoir rechercher des complications précoces","q":"Quels sont les signes cliniques et les risques d'une rhabdomyolyse (crush syndrome) chez un patient polytraumatisé ?","a":"<p>La rhabdomyolyse résulte d'une <strong>destruction myocytaire</strong> et se manifeste cliniquement par :</p><ul><li>Une <strong>myoglobinurie</strong>, donnant des urines de couleur « <strong>porto</strong> ».</li></ul><p>Biologiquement, on observe des <strong>taux élevés de CPK</strong> (Créatine PhosphoKinase).</p><p>Les risques majeurs de la rhabdomyolyse sont l'<strong>insuffisance rénale aiguë</strong> et l'<strong>hyperkaliémie</strong> (pouvant entraîner des troubles du rythme cardiaque).</p>"},{"i":"f0e38375d835","n":334,"o":"334-40","u":"Examens complémentaires","t":"Savoir rechercher des complications précoces","q":"Comment reconnaître un syndrome des loges chez un patient polytraumatisé, afin d'évaluer la nécessité d'une aponévrotomie en urgence ?","a":"<p>Devant un syndrome des loges, il faut rechercher les signes cliniques suivants :</p><ul><li>Des <strong>douleurs insomniantes</strong>, <strong>exacerbées à la palpation et à l'extension passive</strong> des muscles de la loge, et <strong>résistantes aux antalgiques</strong>.</li><li>Des <strong>pouls longtemps conservés</strong>.</li></ul><p>La mesure des pressions intra-compartimentales est diagnostique : <strong>pression supérieure à 30 mmHg</strong> ou un <strong>gradient pression diastolique artérielle - pression intra-compartimentale inférieur à 30 mmHg (ΔPAD < 30 mmHg)</strong>, indiquant une aponévrotomie en urgence.</p>"},{"i":"3107df201442","n":334,"o":"334-41","u":"Prise en charge","t":"Connaître des principes de prise en charge initiale d’une fracture","q":"Quelle mesure spécifique doit être prise en présence d'une fracture ouverte sur les lieux de l'accident ?","a":"<p>En cas de fracture ouverte, il faut réaliser un <strong>pansement occlusif stérile</strong> sur les plaies.</p>"},{"i":"3c6f71876b82","n":334,"o":"334-41","u":"Prise en charge","t":"Connaître des principes de prise en charge initiale d’une fracture","q":"Quel type d'antalgie est recommandé en traumatologie pour la prise en charge d'une fracture aux urgences ?","a":"<p>L'antalgie recommandée inclut les <strong>Anti-Inflammatoires Non Stéroïdiens (AINS)</strong> qui sont efficaces en traumatologie, ainsi que la <strong>morphine</strong>.</p>"},{"i":"3c727a5de647","n":334,"o":"334-41","u":"Prise en charge","t":"Connaître des principes de prise en charge initiale d’une fracture","q":"Quelle est la particularité de la prise en charge initiale d'une fracture de la ceinture pelvienne sur les lieux de l'accident ?","a":"<p>Une fracture de la ceinture pelvienne nécessite l'application d'une <strong>ceinture pelvienne</strong> en raison du <strong>risque vital par hématome rétropéritonéal</strong>.</p>"},{"i":"863dd34052d1","n":334,"o":"334-41","u":"Prise en charge","t":"Connaître des principes de prise en charge initiale d’une fracture","q":"Quelle est la prise en charge spécifique d'une ouverture cutanée associée à une fracture aux urgences ?","a":"<p>En cas d'ouverture cutanée, il faut administrer une <strong>SAT-VAT</strong> et une <strong>antibioprophylaxie</strong> au plus tôt. Il faut également réaliser un <strong>lavage abondant</strong>, appliquer un <strong>antiseptique aqueux</strong> (jamais de solution alcoolique sur peau lésée) et un <strong>pansement stérile</strong>.</p>"},{"i":"b22bb7be2c0f","n":334,"o":"334-41","u":"Prise en charge","t":"Connaître des principes de prise en charge initiale d’une fracture","q":"Quelle est la première étape de la prise en charge d'une fracture sur les lieux de l'accident et son objectif principal ?","a":"<p>La première étape est la <strong>stabilisation par une attelle</strong>. Son objectif principal est de <strong>calmer la douleur</strong>, ce qui participe également à la prise en charge de l'état de choc.</p>"},{"i":"f3708bf68ecb","n":334,"o":"334-41","u":"Prise en charge","t":"Connaître des principes de prise en charge initiale d’une fracture","q":"Quelles sont les mesures initiales à mettre en place aux urgences pour un patient présentant une fracture ?","a":"<p>Aux urgences, le patient doit être mis <strong>à jeun</strong>. Il faut poser des <strong>Voies Veineuses Périphériques (VVP)</strong> et réaliser un <strong>bilan pré-opératoire</strong>.</p>"},{"i":"fe13345f7595","n":334,"o":"334-41","u":"Prise en charge","t":"Connaître des principes de prise en charge initiale d’une fracture","q":"Quand et comment une attelle plâtrée est-elle appliquée après une fracture aux urgences ?","a":"<p>Une attelle plâtrée est appliquée <strong>après réduction</strong> si la fracture présente un <strong>grand déplacement</strong> ou une <strong>menace cutanée</strong>.</p>"},{"i":"3079f39b61f6","n":334,"o":"334-43","u":"Prise en charge","t":"Connaître les principes de prise en charge des principales complications des fractures","q":"Comment prend-on en charge une pseudarthrose ou un cal vicieux après une fracture ?","a":"<p>La prise en charge d'une pseudarthrose ou d'un cal vicieux est une <strong>reprise chirurgicale</strong>, incluant :</p><ul><li>La <strong>décortication</strong>.</li><li>La <strong>greffe osseuse</strong>.</li></ul>"},{"i":"3cb4890f3f9e","n":334,"o":"334-43","u":"Prise en charge","t":"Connaître les principes de prise en charge des principales complications des fractures","q":"Comment prend-on en charge une rhabdomyolyse compliquant une fracture ?","a":"<p>La prise en charge de la rhabdomyolyse repose sur :</p><ul><li>Une <strong>réhydratation agressive</strong> (par exemple, <strong>500 mL/h</strong>).</li><li>Une <strong>alcalinisation des urines</strong> (maintenir un <strong>pH > 6</strong>).</li><li>Le traitement de l'<strong>hyperkaliémie</strong>.</li><li>L'<strong>épuration extrarénale</strong> si hyperkaliémie menaçante, acidose réfractaire, ou anurie.</li></ul>"},{"i":"3fa17b43f4ff","n":334,"o":"334-43","u":"Prise en charge","t":"Connaître les principes de prise en charge des principales complications des fractures","q":"Comment prend-on en charge l'embolie graisseuse après une fracture ?","a":"<p>Le traitement curatif de l'embolie graisseuse est purement <strong>symptomatique</strong>, incluant :</p><ul><li>L'<strong>oxygénothérapie</strong>.</li><li>La <strong>ventilation mécanique</strong> (VM) en cas de syndrome de détresse respiratoire aiguë (SDRA).</li></ul>"},{"i":"a0af799e7f43","n":334,"o":"334-43","u":"Prise en charge","t":"Connaître les principes de prise en charge des principales complications des fractures","q":"Dans quels cas la prévention de la maladie thromboembolique veineuse (MTEV) est-elle systématique chez un patient polytraumatisé avec fractures ?","a":"<p>La prévention de la MTEV est systématique en cas de :</p><ul><li>Lésion du <strong>membre inférieur</strong>.</li><li>Lésion du <strong>rachis</strong>.</li><li><strong>Polytraumatisme</strong>.</li></ul>"},{"i":"e0e4c96e888b","n":334,"o":"334-43","u":"Prise en charge","t":"Connaître les principes de prise en charge des principales complications des fractures","q":"Quelles sont les mesures préventives de l'embolie graisseuse après une fracture ?","a":"<p>La prévention de l'embolie graisseuse repose sur :</p><ul><li>L'<strong>immobilisation précoce et complète</strong> de la fracture.</li><li>La lutte contre l'<strong>hypovolémie</strong>.</li></ul>"},{"i":"fa8fa7d45626","n":334,"o":"334-43","u":"Prise en charge","t":"Connaître les principes de prise en charge des principales complications des fractures","q":"Quelle est la prise en charge d'urgence d'un syndrome des loges après une fracture ?","a":"<p>La prise en charge du syndrome des loges est une <strong>aponévrotomie en urgence</strong>. La peau n'est pas refermée initialement, un pansement occlusif est appliqué. La fermeture est progressive sur <strong>5 à 7 jours</strong>, ou une greffe de peau est réalisée si nécessaire.</p>"},{"i":"3921af02d53e","n":334,"o":"334-44","u":"Définition","t":"Connaître la définition de la fracture du rachis et de l’atteinte médullaire associée","q":"Quels sont les types de lésions rachidiennes instables et leurs caractéristiques ?","a":"<ul><li><strong>Lésion disco-ligamentaire pure</strong> : il s'agit d'une rupture des moyens d'union du segment mobile rachidien (par exemple, entorse grave, luxation). Elle se retrouve surtout au cervical.</li><li><strong>Lésion osseuse pure</strong> : elle concerne l'atteinte du segment vertébral moyen (mur postérieur, pédicules, articulaires postérieures). Elle est fréquente à la jonction thoraco-lombaire et peut prendre la forme d'une <strong>burst fracture</strong> (éclatement comminutif du corps) ou d'une <strong>tear drop</strong> (fracture du corps vertébral avec rupture complète du segment mobile rachidien).</li></ul>"},{"i":"4cc62ce003d9","n":334,"o":"334-44","u":"Définition","t":"Connaître la définition de la fracture du rachis et de l’atteinte médullaire associée","q":"Quand une fracture du rachis est-elle considérée comme instable ?","a":"<p>Une fracture du rachis est instable lorsqu'elle expose à une <strong>lésion neurologique secondaire</strong> en cas de déplacement.</p>"},{"i":"6016ac6d02f9","n":334,"o":"334-44","u":"Définition","t":"Connaître la définition de la fracture du rachis et de l’atteinte médullaire associée","q":"Qu'est-ce qu'une atteinte médullaire primaire et ses caractéristiques ?","a":"<p>Une atteinte médullaire primaire est une lésion <strong>mécanique</strong> qui survient au moment même du traumatisme. Elle est considérée comme inaccessible au traitement et se présente généralement sous forme d'écrasement ou d'étirement de la moelle, plutôt qu'une section complète.</p>"},{"i":"79c99442397a","n":334,"o":"334-44","u":"Définition","t":"Connaître la définition de la fracture du rachis et de l’atteinte médullaire associée","q":"Qu'est-ce que la stabilité du rachis en traumatologie ?","a":"<p>La stabilité du rachis correspond à sa capacité à maintenir des rapports anatomiques normaux entre les vertèbres, prévenant ainsi toute lésion neurologique.</p>"},{"i":"8609aa582a36","n":334,"o":"334-44","u":"Définition","t":"Connaître la définition de la fracture du rachis et de l’atteinte médullaire associée","q":"Qu'est-ce qu'une atteinte médullaire secondaire et quelle est sa prise en charge ?","a":"<p>Une atteinte médullaire secondaire correspond à des <strong>agressions médullaires systémiques</strong> (<strong>AMSOS</strong>), survenant dans les heures ou jours suivant le traumatisme, comme l'ischémie ou la nécrose. Ces lésions sont accessibles à la prise en charge, principalement par le maintien de la pression artérielle (PA) et de l'oxygénation.</p>"},{"i":"56579cf3cbda","n":334,"o":"334-46","u":"Diagnostic positif","t":"Circonstances, signes fonctionnels et physiques, savoir effectuer un examen neurologique complet et renseigner l’échelle ASIA","q":"Quelle est l'approche pour effectuer un examen neurologique complet chez un polytraumatisé, notamment pour évaluer la motricité des membres ?","a":"<p>L'examen neurologique chez un polytraumatisé doit être <strong>complet, daté et consigné par écrit</strong>. Pour la motricité des 4 membres, on utilise la cotation MRC de 0 à 5 :</p><ul><li><strong>0</strong> : aucune contraction</li><li><strong>1</strong> : contraction visible sans déplacement</li><li><strong>2</strong> : mouvement sans pesanteur</li><li><strong>3</strong> : mouvement contre pesanteur</li><li><strong>4</strong> : mouvement contre résistance</li><li><strong>5</strong> : force normale</li></ul>"},{"i":"afb890d00f44","n":334,"o":"334-46","u":"Diagnostic positif","t":"Circonstances, signes fonctionnels et physiques, savoir effectuer un examen neurologique complet et renseigner l’échelle ASIA","q":"Comment l'échelle ASIA est-elle utilisée pour évaluer et graduer une atteinte médullaire chez un polytraumatisé ?","a":"<p>L'échelle ASIA (American Spinal Injury Association) permet une observation standardisée internationale :</p><ul><li>Le <strong>score moteur</strong> évalue 10 fonctions clés sur les 2 côtés.</li><li>Les <strong>scores sensitifs</strong> évaluent 28 dermatomes pour la piqûre et le tact.</li></ul><p>Le grade AIS (ASIA Impairment Scale) quantifie le caractère incomplet de l'atteinte en analysant les segments sacrés S4-S5 :</p><ul><li><strong>Grade A</strong> : Atteinte complète (aucune fonction motrice ni sensitive en S4-S5).</li><li><strong>Grade B</strong> : Sensibilité préservée en S4-S5, motricité abolie.</li><li><strong>Grade C</strong> : Motricité incomplète, force résiduelle non fonctionnelle (moins de 50 % des muscles clés à 3 ou plus).</li><li><strong>Grade D</strong> : Motricité préservée (50 % ou plus des muscles clés à 3 ou plus), marche souvent possible.</li><li><strong>Grade E</strong> : Fonctions sensitives et motrices normales.</li></ul>"},{"i":"f6d0e81b485b","n":334,"o":"334-46","u":"Diagnostic positif","t":"Circonstances, signes fonctionnels et physiques, savoir effectuer un examen neurologique complet et renseigner l’échelle ASIA","q":"Quels sont les éléments spécifiques de l'examen neurologique à rechercher pour évaluer une éventuelle atteinte médullaire chez un polytraumatisé ?","a":"<p>Pour évaluer une atteinte médullaire, l'examen neurologique doit spécifiquement rechercher :</p><ul><li>La <strong>motricité périnéale</strong> (contraction anale au toucher rectal)</li><li>La <strong>sensibilité</strong> (détermination du niveau métamérique)</li><li>Les <strong>réflexes ostéo-tendineux (ROT)</strong></li><li>Les <strong>réflexes bulbo-caverneux et clitorido-anal</strong></li><li>Un <strong>priapisme</strong>, signe d'une atteinte médullaire de mauvais pronostic.</li></ul>"},{"i":"61de79100596","n":334,"o":"334-47","u":"Identifier une urgence","t":"Connaître les symptômes devant faire suspecter une lésion médullaire","q":"Quels sont les signes cliniques considérés comme des éléments de mauvais pronostic devant faire suspecter une lésion médullaire complète aiguë ?","a":"<p>Les éléments de mauvais pronostic devant faire suspecter une lésion médullaire complète aiguë sont :</p><ul><li>L'<strong>atonie du sphincter anal</strong>.</li><li>Le <strong>priapisme</strong>.</li><li>La <strong>disparition du réflexe bulbo-caverneux</strong>.</li></ul><p>L'examen périnéal et le toucher rectal sont essentiels pour rechercher ces signes.</p>"},{"i":"7d236be69f5e","n":334,"o":"334-47","u":"Identifier une urgence","t":"Connaître les symptômes devant faire suspecter une lésion médullaire","q":"Quels sont les éléments cliniques permettant de suspecter une lésion médullaire chez un polytraumatisé ?","a":"<p>La suspicion de lésion médullaire repose sur la présence d'un <strong>syndrome rachidien</strong> (douleur spontanée ou provoquée à la palpation des épineuses, raideur, déformation rachidienne) et/ou d'un <strong>syndrome lésionnel ou sous-lésionnel</strong> (déficit moteur, sensitif, troubles sphinctériens).</p>"},{"i":"b807c5e99d56","n":334,"o":"334-47","u":"Identifier une urgence","t":"Connaître les symptômes devant faire suspecter une lésion médullaire","q":"En cas de choc spinal, comment se manifeste le premier temps de l'atteinte médullaire immédiate ?","a":"<p>Le premier temps du choc spinal (interruption médullaire complète) est caractérisé par :</p><ul><li>Une <strong>paralysie flasque</strong> sous-lésionnelle.</li><li>Une <strong>anesthésie</strong> à tous les modes sous la lésion.</li><li>Une <strong>abolition des réflexes ostéotendineux (ROT)</strong> sous la lésion.</li><li>Une <strong>rétention aiguë d'urine</strong>.</li></ul>"},{"i":"d0014b18538e","n":334,"o":"334-47","u":"Identifier une urgence","t":"Connaître les symptômes devant faire suspecter une lésion médullaire","q":"Quelle doit être l'attitude immédiate devant tout déficit neurologique suspect de lésion médullaire, notamment s'il est incomplet et évolutif ?","a":"<p>Tout déficit neurologique, particulièrement s'il est <strong>incomplet et évolutif</strong>, impose une <strong>imagerie</strong> et un <strong>avis chirurgical en urgence immédiate</strong>.</p>"},{"i":"0531159914c0","n":334,"o":"334-48","u":"Prise en charge","t":"Connaître les indications et les modalités des principes d’immobilisation","q":"Quelles sont les modalités pratiques de l'immobilisation chez un polytraumatisé ou un traumatisé du rachis ?","a":"<ul><li>Mise en place d'un <strong>collier/minerve cervicale rigide systématique</strong>. Le principe est que « tout traumatisé crânien est un traumatisé du rachis cervical jusqu'à preuve du contraire ».</li><li>Maintien de la <strong>rectitude tête-cou-tronc</strong>, sans exercer de traction axiale.</li><li>Mobilisation en bloc (avec <strong>4 personnes au minimum</strong>) pour l'installation sur un <strong>plan dur</strong> ou un <strong>matelas à dépression (matelas-coquille)</strong>.</li><li>Mise en place d'une <strong>ceinture de contention pelvienne</strong> au moindre doute sur un traumatisme du bassin.</li></ul>"},{"i":"0e45d0b00d5d","n":334,"o":"334-48","u":"Prise en charge","t":"Connaître les indications et les modalités des principes d’immobilisation","q":"Pour quels patients et quand l'immobilisation doit-elle être mise en œuvre en cas de traumatisme ?","a":"<p>L'immobilisation doit être mise en œuvre systématiquement pour <strong>tout traumatisé du rachis</strong> et <strong>tout polytraumatisé</strong>, dès la prise en charge sur les lieux de l'accident et pendant toute la durée du transport à l'hôpital. Il est crucial de noter que l'<strong>absence de déficit neurologique initial n'exclut pas une lésion vertébrale instable</strong>.</p>"},{"i":"133b6a6a7bcb","n":334,"o":"334-48","u":"Prise en charge","t":"Connaître les indications et les modalités des principes d’immobilisation","q":"Jusqu'à quand l'immobilisation du rachis doit-elle être maintenue chez un patient traumatisé ?","a":"<p>L'immobilisation du rachis doit être maintenue jusqu'à l'<strong>interprétation du scanner rachidien (TDM rachidien) par le radiologue</strong>, qui permettra de confirmer ou d'exclure une lésion instable.</p>"},{"i":"0f2b70fb8546","n":334,"o":"334-49","u":"Examens complémentaires","t":"Connaître les indications d’imagerie devant un traumatisé du rachis ou vertébro-médullaire","q":"Dans quelles situations spécifiques l'IRM rachidienne est-elle indiquée chez un traumatisé du rachis ou vertébro-médullaire ?","a":"<p>L'IRM rachidienne est indiquée dans les situations suivantes :</p><ul><li>En cas de <strong>déficit neurologique inexpliqué</strong> par les résultats de la TDM.</li><li>En cas de <strong>suspicion d'atteinte disco-ligamentaire</strong>.</li></ul><p>Elle est le seul examen permettant de visualiser la <strong>moelle épinière</strong>, les <strong>ligaments</strong> et un éventuel <strong>hématome épidural</strong>.</p>"},{"i":"834ff5aa6310","n":334,"o":"334-49","u":"Examens complémentaires","t":"Connaître les indications d’imagerie devant un traumatisé du rachis ou vertébro-médullaire","q":"Quelle est l'indication principale de la TDM du rachis chez un polytraumatisé ou brûlé avec suspicion de traumatisme vertébro-médullaire ?","a":"<p>La <strong>TDM du rachis</strong> est l'examen de référence, indiquée de manière <strong>systématique</strong> chez le traumatisé sévère pour évaluer le rachis. Elle est particulièrement efficace pour visualiser les <strong>traits de fracture</strong> et la <strong>sténose canalaire</strong>.</p>"},{"i":"ee310939fead","n":334,"o":"334-49","u":"Examens complémentaires","t":"Connaître les indications d’imagerie devant un traumatisé du rachis ou vertébro-médullaire","q":"Quel est le piège à éviter concernant les radiographies dynamiques (hyperflexion/hyperextension) en urgence pour un traumatisme cervical ?","a":"<p>Le piège est de ne <strong>jamais réaliser en urgence</strong> des clichés dynamiques (hyperflexion/hyperextension) pour un traumatisme cervical. Ces examens sont indiqués <strong>à distance (8 à 10 jours)</strong> de l'épisode traumatique, une fois la <strong>contracture musculaire levée</strong>, pour rechercher une instabilité disco-ligamentaire.</p>"},{"i":"f6fb34c55604","n":334,"o":"334-49","u":"Examens complémentaires","t":"Connaître les indications d’imagerie devant un traumatisé du rachis ou vertébro-médullaire","q":"Quand les radiographies du rachis sont-elles utiles en cas de traumatisme vertébro-médullaire ?","a":"<p>Les radiographies du rachis sont utiles dans deux situations principales :</p><ul><li>Si la <strong>TDM ou l'IRM sont inaccessibles</strong>.</li><li>En cas de <strong>traumatisme à faible cinétique</strong> et <strong>sans signe neurologique</strong>.</p>"},{"i":"04d7d3c5bad0","n":334,"o":"334-5","u":"Prise en charge","t":"Connaître les principes de prise en charge préhospitalère des lésions","q":"Quels sont les gestes d'hémostase prioritaires en préhospitalier pour un polytraumatisé, avant les secours médicalisés ?","a":"<p>La priorité n°1 est le contrôle des hémorragies :</p><ul><li><strong>Compression directe</strong> de toute hémorragie extériorisée.</li><li>En cas de plaie hémorragique du scalp, une <strong>suture simple</strong> est possible.</li><li>Pour une épistaxis, un <strong>tamponnement</strong> est indiqué.</li><li>Pour une hémorragie artérielle d'un membre ou une amputation, l'application d'un <strong>garrot à la racine du membre</strong> est essentielle, en notant l'heure de pose.</li></ul>"},{"i":"6d0f8b2e0634","n":334,"o":"334-5","u":"Prise en charge","t":"Connaître les principes de prise en charge préhospitalère des lésions","q":"Quelles sont les mesures thérapeutiques complémentaires et les principes de transport et de délai pour un polytraumatisé en préhospitalier ?","a":"<ul><li><strong>Antalgie</strong> : Administration de <strong>morphine IVD</strong>.</li><li><strong>Immobilisation</strong> : Réduction et immobilisation des fractures déplacées avec des <strong>attelles à dépression</strong>.</li><li><strong>Lutte contre l'hypothermie</strong> : Utilisation d'une <strong>couverture de survie</strong>.</li><li><strong>Acide tranexamique</strong> : Injection de <strong>1 g sur 10 minutes</strong> chez tout traumatisé sévère.</li><li><strong>Antibioprophylaxie</strong> : <strong>Amoxicilline-acide clavulanique</strong> si fracture ouverte.</li><li><strong>Transport</strong> : Le délai de transport vers l'hôpital ne doit jamais excéder <strong>90 minutes</strong>. Une hémorragie non contrôlée impose un <strong>transfert immédiat</strong> vers un centre apte à l'hémostase, sans aucun examen retardateur.</li></ul>"},{"i":"8fad9526c659","n":334,"o":"334-5","u":"Prise en charge","t":"Connaître les principes de prise en charge préhospitalère des lésions","q":"Quels gestes spécifiques et médicaux peuvent être réalisés en préhospitalier face à un polytraumatisé présentant un pneumothorax sous tension ou un traumatisme pelvien suspecté ?","a":"<ul><li>Pour un <strong>pneumothorax sous tension</strong>, une <strong>exsufflation à l'aiguille</strong> doit être réalisée. Il n'y a pas de drainage thoracique en préhospitalier.</li><li>En cas de <strong>suspicion de traumatisme pelvien</strong>, la mise en place d'une <strong>ceinture de contention pelvienne au niveau des trochanters</strong> est nécessaire.</li></ul>"},{"i":"9cffd0cf5d7c","n":334,"o":"334-5","u":"Prise en charge","t":"Connaître les principes de prise en charge préhospitalère des lésions","q":"Quels sont les principes du premier maillon de la chaîne de survie, applicable par un témoin, face à un polytraumatisé en préhospitalier ?","a":"<p>Face à un polytraumatisé, le témoin doit appliquer les principes de <strong>P.A.S.</strong> :</p><ul><li><strong>Protéger</strong> : Éviter le sur-accident en sécurisant la zone.</li><li><strong>Alerter</strong> : Contacter les services d'urgence (<strong>15 SAMU, 18 pompiers, 112</strong>).</li><li><strong>Secourir</strong> : Réaliser des gestes simples comme la compression d'une hémorragie, et mettre en position d'attente sur avis du régulateur.</li></ul>"},{"i":"17badfcfac32","n":334,"o":"334-53","u":"Diagnostic positif","t":"Savoir suspecter et diagnostiquer un traumatisme crânien","q":"Quels signes cliniques orientent vers une complication spécifique de traumatisme crânien comme une fracture de la base du crâne ou une brèche ostéo-méningée ?","a":"<p>Certains signes cliniques sont évocateurs de complications :</p><ul><li>Une <strong>déformation crânienne (embarrure)</strong> suggère une fracture enfoncée.</li><li>Une <strong>rhinorrhée ou une otorrhée claire</strong> évoque une <strong>brèche ostéo-méningée</strong> avec fuite de LCS.</li><li>Une <strong>otorragie</strong>, une <strong>rhinorrhée</strong>, ou des <strong>ecchymoses péri-orbitaires (signe des lunettes)</strong> ou <strong>mastoïdiennes (signe de Battle)</strong> doivent faire évoquer une <strong>fracture de la base du crâne</strong>.</li></ul>"},{"i":"55c791fc78f0","n":334,"o":"334-53","u":"Diagnostic positif","t":"Savoir suspecter et diagnostiquer un traumatisme crânien","q":"Comment doit être réalisé l'examen neurologique initial d'un patient polytraumatisé pour suspecter un traumatisme crânien ?","a":"<p>L'examen neurologique initial doit être <strong>complet, daté et consigné</strong>. Il inclut systématiquement le calcul du <strong>Score de Glasgow</strong> et l'examen des <strong>pupilles (recherche d'anisocorie et de réactivité)</strong>.</p>"},{"i":"75ba90d3d7dc","n":334,"o":"334-53","u":"Diagnostic positif","t":"Savoir suspecter et diagnostiquer un traumatisme crânien","q":"Quels autres éléments neurologiques sont importants à évaluer lors de l'examen clinique d'un traumatisme crânien potentiellement grave ?","a":"<p>Il est crucial d'effectuer :</p><ul><li>Un <strong>testing sensitivo-moteur</strong>.</li><li>Un examen des <strong>nerfs crâniens</strong>.</li><li>La recherche de <strong>signes de localisation</strong> (ex: déficit moteur focal) et de <strong>signes d'engagement cérébral</strong> (ex: mydriase unilatérale aréactive, troubles du rythme respiratoire).</p></li></ul>"},{"i":"f2717dc7a809","n":334,"o":"334-53","u":"Diagnostic positif","t":"Savoir suspecter et diagnostiquer un traumatisme crânien","q":"Quels éléments spécifiques doit rechercher l'examen du cuir chevelu chez un patient suspect de traumatisme crânien ?","a":"<p>L'examen du cuir chevelu doit rechercher :</p><ul><li>Des <strong>plaies</strong>.</li><li>Une <strong>hémorragie active</strong>.</li><li>Une <strong>fuite de liquide cérébrospinal (LCS)</strong>.</li></ul>"},{"i":"670a56623283","n":334,"o":"334-54","u":"Identifier une urgence","t":"Identifier le traumatisé crânien grave","q":"Quel score est utilisé pour évaluer les réflexes du tronc cérébral dans le cadre d'un traumatisme crânien grave et quels sont ses composants ?","a":"<p>Le <strong>score de Liège</strong> évalue les réflexes du tronc cérébral dans le sens cranio-caudal :</p><ul><li>Fronto-orbiculaire (5)</li><li>Oculocéphalique vertical (4)</li><li>Photomoteur (3)</li><li>Oculocéphalique horizontal (2)</li><li>Oculo-cardiaque (1)</li><li>Tous absents (0)</li></ul><p>La disparition du dernier réflexe (oculo-cardiaque) peut signer la mort encéphalique.</p>"},{"i":"6c68c17adef3","n":334,"o":"334-54","u":"Identifier une urgence","t":"Identifier le traumatisé crânien grave","q":"Quelle est la particularité à prendre en compte avant de rechercher le réflexe oculocéphalogyre chez un traumatisé crânien ?","a":"<p>Le réflexe oculocéphalogyre ne doit être recherché <strong>qu'après un scanner du rachis cervical</strong> ayant éliminé une lésion instable.</p>"},{"i":"6eb388c149b2","n":334,"o":"334-54","u":"Identifier une urgence","t":"Identifier le traumatisé crânien grave","q":"Quels sont les signes de gravité associés à un traumatisme crânien grave ?","a":"<p>Les signes de gravité associés au TC grave comprennent :</p><ul><li>Des <strong>signes de localisation</strong> : asymétrie faciale, déficit moteur d'un hémicorps.</li><li>Des <strong>signes d'engagement</strong> : mydriase unilatérale aréactive (engagement temporal), décortication/décérébration, et désintégration rostro-caudale des réflexes du tronc.</li></ul>"},{"i":"74159856085c","n":334,"o":"334-54","u":"Identifier une urgence","t":"Identifier le traumatisé crânien grave","q":"Comment est défini un traumatisme crânien (TC) grave ?","a":"<p>Un traumatisme crânien grave est défini par un score de Glasgow <strong>inférieur ou égal à 8</strong>.</p>"},{"i":"3cbe96f29b1b","n":334,"o":"334-55","u":"Identifier une urgence","t":"Identifier le traumatisé crânien nécessitant une évaluation spécialisée","q":"Quand un traumatisé crânien est-il classé dans le Groupe 3 (risque élevé) selon Masters, et quelle est la stratégie thérapeutique initiale ?","a":"<p>Un traumatisé crânien est classé dans le Groupe 3 si l'on observe :</p><ul><li>Un <strong>Glasgow ≤ 13</strong>.</li><li>Des <strong>signes de focalisation</strong> neurologique.</li><li>Une <strong>brèche ostéo-méningée</strong>.</li><li>Une <strong>embarrure</strong>.</li></ul><p>La stratégie thérapeutique initiale est :</p><ul><li>Une <strong>TDM en urgence</strong>.</li><li>Un <strong>transfert vers un centre spécialisé</strong> (neurochirurgie).</li></ul>"},{"i":"69ff81fbdaba","n":334,"o":"334-55","u":"Identifier une urgence","t":"Identifier le traumatisé crânien nécessitant une évaluation spécialisée","q":"Comment la classification de Masters stratifie-t-elle le risque de lésion intracrânienne chez le traumatisé crânien ?","a":"<p>La classification de Masters stratifie le risque en <strong>3 groupes</strong> :</p><ul><li><strong>Groupe 1</strong> : Faible risque</li><li><strong>Groupe 2</strong> : Risque modéré</li><li><strong>Groupe 3</strong> : Risque élevé</li></ul>"},{"i":"cd29598e39aa","n":334,"o":"334-55","u":"Identifier une urgence","t":"Identifier le traumatisé crânien nécessitant une évaluation spécialisée","q":"Quelles sont les caractéristiques cliniques d'un traumatisé crânien de Groupe 1 (faible risque) selon la classification de Masters, et quelle est la conduite à tenir ?","a":"<p>Un traumatisé crânien de Groupe 1 présente :</p><ul><li>Un <strong>Glasgow de 15</strong>.</li><li>Est <strong>asymptomatique</strong>, ou présente des céphalées régressives, ou des vertiges.</li></ul><p>La conduite à tenir est :</p><ul><li><strong>Pas de TDM systématique</strong>.</li><li><strong>Surveillance</strong> et éducation.</li><li>Autorisation de <strong>retour à domicile (RAD)</strong> si l'entourage est fiable.</li></ul>"},{"i":"f700630d5b84","n":334,"o":"334-55","u":"Identifier une urgence","t":"Identifier le traumatisé crânien nécessitant une évaluation spécialisée","q":"Quels sont les critères cliniques définissant un traumatisé crânien de Groupe 2 (risque modéré) selon la classification de Masters, et quelle prise en charge est recommandée ?","a":"<p>Un traumatisé crânien de Groupe 2 présente :</p><ul><li>Un <strong>Glasgow de 14-15</strong>.</li><li>Une <strong>amnésie</strong> ou une <strong>perte de connaissance initiale</strong>.</li><li>Des vomissements, des céphalées croissantes.</li><li>Une intoxication, un trouble de la coagulation.</li><li>Un polytraumatisme, une plaie pénétrante.</li><li>Un <strong>âge > 65 ans</strong> ou un <strong>enfant < 2 ans</strong>.</li></ul><p>La prise en charge recommandée est :</p><ul><li>Une <strong>TDM</strong>.</li><li>Une <strong>hospitalisation de 24-48 heures</strong> pour surveillance.</li></ul>"},{"i":"6a58bf1e6e74","n":334,"o":"334-56","u":"Examens complémentaires","t":"Savoir demander à bon escient l’examen d’imagerie pertinent devant un traumatisme crânien à la phase aiguë","q":"Pourquoi et quand doit-on toujours considérer la réalisation d'une TDM du rachis cervical chez un traumatisé crânien ?","a":"<p>Une TDM du rachis cervical doit être réalisée au moindre doute, car <strong>tout traumatisé crânien est considéré comme un traumatisé du rachis cervical jusqu'à preuve du contraire</strong>.</p>"},{"i":"846a6e335c5f","n":334,"o":"334-56","u":"Examens complémentaires","t":"Savoir demander à bon escient l’examen d’imagerie pertinent devant un traumatisme crânien à la phase aiguë","q":"Dans quel contexte demande-t-on une Angio-TDM chez un patient polytraumatisé avec traumatisme crânien ?","a":"<p>Une Angio-TDM est demandée si l'on recherche des <strong>lésions vasculaires associées</strong> (par exemple, une dissection) ou pour évaluer la <strong>perfusion cérébrale</strong>.</p>"},{"i":"97ef2c10dbe5","n":334,"o":"334-56","u":"Examens complémentaires","t":"Savoir demander à bon escient l’examen d’imagerie pertinent devant un traumatisme crânien à la phase aiguë","q":"Quelle est la limite de la TDM cérébrale initiale de phase aiguë pour le diagnostic des lésions axonales diffuses (LAD) ?","a":"<p>Les <strong>lésions axonales diffuses (LAD)</strong> sont souvent <strong>non visibles sur la TDM initiale</strong>. En cas de coma sans lésion TDM expliquant le tableau clinique, une <strong>IRM à distance</strong> peut être nécessaire pour les diagnostiquer.</p>"},{"i":"e4ffca4d3443","n":334,"o":"334-56","u":"Examens complémentaires","t":"Savoir demander à bon escient l’examen d’imagerie pertinent devant un traumatisme crânien à la phase aiguë","q":"Quel est l'examen d'imagerie de référence à réaliser devant un traumatisme crânien à la phase aiguë ?","a":"<p>L'examen d'imagerie de référence devant un traumatisme crânien à la phase aiguë est la <strong>TDM cérébrale sans injection</strong>.</p>"}]};